constexpr bool BhrcFullPgdRestoreDeadlineElapsed(uint64_t started, uint64_t now) {
  return started != 0 && now >= started &&
      now - started >= kBhrcFullPgdRestoreWindowMs;
}

static_assert(!BhrcFullPgdRestoreDeadlineElapsed(0, 120000));
static_assert(!BhrcFullPgdRestoreDeadlineElapsed(1000, 999));
static_assert(!BhrcFullPgdRestoreDeadlineElapsed(1000, 60999));
static_assert(BhrcFullPgdRestoreDeadlineElapsed(1000, 61000));
static_assert(BhrcFullPgdRestoreDeadlineElapsed(1000, 120000));
static_assert(BhrcFullPgdRestoreDeadlineElapsed(0xfffffff0ULL, 0x10000ea50ULL));

bool BhrcFullPgdRestoreWindowClosed(const BhrcExpeditionProbeAttempt& probe) {
  return probe.full_pgd_restore_expired || probe.full_pgd_restore_finished ||
      BhrcFullPgdRestoreDeadlineElapsed(
          probe.full_pgd_restore_started_tick_ms, GetTickCount64());
}

