    const auto* record = FindSessionRecordByKey(ReadGameGlobalPtr(kNetModeManagerPtrRva), actual_key);
    event.live_slot = ReadI32(record != nullptr ? record + 0xd0 : nullptr, -1);
    event.live_d4 = ReadI32(record != nullptr ? record + 0xd4 : nullptr, -1);
