    Log("BHRC_NAME_TRACE consume seq=%ld nonce=%08x generation=%u stage=%s sourceKey=%016llx record=%p slot=%d bytes=%d originalBytes=%d payloadId=%d inputName=\"%s\" comparisonSeen=%d localId=%d substituted=%d reason=%s permitRequired=%d permitResult=%d nameValid=%d targetIndex=%d targetPgd=%p writerCalls=%u notReached=-1 payloadMutation=0",
        event.trace_seq, probe.request_nonce, probe.client_generation,
        BhrcExpeditionProbeStageName(probe.stage), static_cast<unsigned long long>(event.key),
        event.record, event.slot, event.result, event.original_result,
        ReadI32(event.payload, -1), name, event.comparison_seen ? 1 : 0,
        event.local_id, event.identity_substituted ? 1 : 0,
        event.comparison_reason, event.permit_required, event.permit_result,
        event.name_valid, event.target_index, event.target_pgd, event.writer_calls);
