      (g_bhrc_name_tls.event.trace_seq != 0 || probe.request_nonce != 0 ||
       GetCurrentNrscMasterLobbyId() != 0) &&
      BhrcDiagnosticBudget(&g_bhrc_name_writer_count, 96, "name_writer", &seq);
  char before[96]{}, input[96]{};
  const void* caller = _ReturnAddress();
  if (trace) {
    ReadBhrcDiagnosticName(static_cast<const uint8_t*>(pgd) + 0x9c, before, sizeof(before));
    ReadBhrcDiagnosticName(name, input, sizeof(input));
  }
  if (g_bhrc_name_tls.consumer == 0xdddc10 && g_bhrc_name_tls.event.payload_readable)
    ++g_bhrc_name_tls.event.writer_calls;
