bool UseBhrcSteamIdentityForAutomaticMetadata(const BhrcNameEvent& event, const char** reason) {
  const auto deny = [reason](const char* value) { *reason = value; return false; };
  if (!g_config.enable_nrsc_steam_control || g_nrsc_module == nullptr ||
      InterlockedCompareExchange(&g_bhrc_name_hooks_ready, 0, 0) == 0)
    return deny("reconnect_scope");

  const uint64_t local = g_nrsc_steam_control_state.local_steam_id;
  const uint64_t master = GetCurrentNrscMasterLobbyId();
  const uint64_t host = g_nrsc_steam_control_state.owner_steam_id;
  const auto active_peer = [](uint64_t key) {
    bool active = false;
    return TryReadNrscNativePeerActive(key, &active) ? active : IsNrscPeerActive(key);
  };
  if (local == 0 || master == 0 || host == 0 || event.key == 0 || event.key == local ||
      !active_peer(event.key) || (host != local && !active_peer(host)))
    return deny("steam_identity_or_peer");

  void* const session = ReadGameGlobalPtr(kNetModeManagerPtrRva);
  if (session == nullptr || session != event.manager ||
      ReadU32(static_cast<const uint8_t*>(session) + 0xc, UINT32_MAX) != (host == local ? 3u : 6u))
    return deny("session_state");
  const auto* record = FindSessionRecordByKey(session, event.key);
  const auto* self = FindSessionRecordByKey(session, local);
  if (record == nullptr || record != event.record || self == nullptr ||
      ReadU8(record + 0xe1, 0xff) != 0 ||
      ReadU8(record + 0xe5, 0xff) != 0 ||
      ReadU64(record + 0xc0, 0) == 0 || ReadU64(record + 0xc8, 0) == 0 ||
      ReadI32(record + 0xd0, -1) != event.slot || event.slot < 0 ||
      !BhrcPgdSlotIsUnique(session, event.key, event.slot) ||
      ReadU8(self + 0xe1, 0) != 1 || ReadU8(self + 0xe5, 0xff) != 0 ||
      ReadU64(self + 0xc0, 0) == 0 || ReadU64(self + 0xc8, 0) == 0)
    return deny("record_provider_or_slot");

  const uint32_t manager_id = ReadU32(
      static_cast<const uint8_t*>(session) + 8, 0);
  const auto lookup = ReadBhrcNativeManagerRegistry(session, manager_id);
  const auto manager = ReadBhrcNativeJoinOwnershipSnapshot(lookup.manager);
  if (manager_id == 0 || lookup.read_fault || lookup.provider == nullptr ||
      lookup.manager == nullptr || manager.manager_id != manager_id ||
      manager.native_state != 2 ||
      manager.owned_lobby == 0 || manager.owned_lobby == master ||
      RvaOf(reinterpret_cast<const void*>(manager.manager_vtable)) !=
          kNativeSteamLobbyManagerVtableRva)
    return deny("native_B_owner");

  if (GetCurrentNrscMasterLobbyId() != master ||
      g_nrsc_steam_control_state.owner_steam_id != host ||
      FindSessionRecordByKey(session, event.key) != record ||
      !BhrcPgdSlotIsUnique(session, event.key, event.slot)) return deny("binding_changed");

  *reason = "steam_remote_record_proven";
  return true;
}

int32_t __fastcall HookBhrcNameLocalId(void* manager) {
  using Fn = int32_t(__fastcall*)(void*);
  const int32_t result = ResolveNative<Fn>(0xafe130)(manager);
  auto& event = g_bhrc_name_tls.event;
  event.comparison_seen = true;
  event.local_id = result;
  event.comparison_reason = "comparison_not_substitutable";
  if (RvaOf(_ReturnAddress()) == 0xdddd3c && result == 0 &&
      g_bhrc_name_tls.consumer == 0xdddc10 && event.type == 0x60 &&
      event.original_result == 0x30 && event.result == 0x30 &&
      event.requested == 0x30 && event.payload_readable &&
      ReadI32(event.payload, -1) == 0 &&
      UseBhrcSteamIdentityForAutomaticMetadata(event, &event.comparison_reason)) {
    // The verified dddd3c CMP is the only consumer of this return value.
    // Offline account IDs are both zero, but the live Steam record is remote.
    // Keep the payload intact; dddc10 still owns permit/name validation,
    // PGD lookup, +c/+ec/+720 writes, 20d730 and df2730 refresh.
    event.identity_substituted = true;
    return -1;
  }
  return result;
}

