void BeginBhrcNameRecordRead(void* manager, const void* record, uint32_t type,
    uint32_t size) {
  if (g_bhrc_name_tls.consumer != 0xdddc10 || type != 0x60) return;
  FlushBhrcNameDiagnostic();
  auto& event = g_bhrc_name_tls.event;
  event = {};
  const auto* bytes = static_cast<const uint8_t*>(record);
  event.type = type;
  event.manager = manager;
  event.record = record;
  event.key = ReadU64(bytes != nullptr ? bytes + 0x10 : nullptr, 0);
  event.slot = ReadI32(bytes != nullptr ? bytes + 0xd0 : nullptr, -1);
  event.requested = size;
}

void CaptureBhrcNameRecordRead(void* manager, const void* record, uint32_t type,
    void* payload, uint32_t size, int32_t original_result, int32_t result) {
  auto& event = g_bhrc_name_tls.event;
  if (g_bhrc_name_tls.consumer != 0xdddc10 || type != 0x60 ||
      event.type != type || event.manager != manager || event.record != record)
    return;
  event.result = result;
  event.original_result = original_result;
  event.payload_readable = result == 0x30 && original_result == 0x30 &&
      size == sizeof(event.payload) &&
      TryCopyBhrcMetadataPayload(payload, event.payload, sizeof(event.payload));
  if (event.payload_readable) {
    LONG seq = 0;
    if (BhrcDiagnosticBudget(&g_bhrc_name_event_count, 96, "name_consume", &seq))
      event.trace_seq = seq;
  }
}

void TraceBhrcReconnectEffectApply(void* entity, uint32_t effect_id,
                                 uint8_t mode, uint8_t result, uintptr_t caller_rva) {
  if (!BhrcEffectTraceActive() || entity == nullptr ||
      entity != BhrcEffectLocalPlayer() || IsLocalNrscHost()) return;
  const BhrcExpeditionProbeAttempt probe = SnapshotBhrcExpeditionProbe();
  if (!IsBhrcAuthorizedClientProbe(probe) || probe.native_attempt_transport_lost) return;
  const LONG count = InterlockedIncrement(&g_bhrc_effect_apply_count);
  if (count > 128) {
    if (count == 129) LogWarn("BHRC_EFFECT_TRACE budget kind=apply limit=128 furtherAppliesSuppressed=1");
    return;
  }
  const BhrcEffectSnapshot state = ReadBhrcEffectSnapshot(nullptr);
  bool present = false;
  for (uint32_t i = 0; i < state.count; ++i) present |= state.ids[i] == effect_id;
  const int present_after = !state.list_readable ? -1 :
      present ? 1 : state.truncated ? -1 : 0;
  Log(
      "BHRC_EFFECT_TRACE apply seq=%ld nonce=%08x generation=%u replay=%s player=%p effectId=%u mode=%u nativeResult=%u listReadable=%d presentAfter=%d hp=%d maxHp=%d callerRva=%llx observedEntry=3c7fd0 behaviorMutation=0",
      count, probe.request_nonce, probe.client_generation, BhrcEffectReplayPhaseName(),
      entity, effect_id, static_cast<unsigned>(mode), static_cast<unsigned>(result),
      state.list_readable ? 1 : 0, present_after, state.hp, state.max_hp,
      static_cast<unsigned long long>(caller_rva));
  if (count <= 8) {
    void* frames[8]{};
    const USHORT depth = CaptureStackBackTrace(
        0, static_cast<DWORD>(_countof(frames)), frames, nullptr);
    char stack[192]{};
    size_t used = 0;
    for (USHORT i = 0; i < depth; ++i) {
      const int written = std::snprintf(stack + used, sizeof(stack) - used,
          "%s%p", i == 0 ? "" : ",", frames[i]);
      if (written <= 0 || static_cast<size_t>(written) >= sizeof(stack) - used) break;
      used += static_cast<size_t>(written);
    }
    Log("BHRC_EFFECT_TRACE apply_stack seq=%ld frames=%u addresses=[%s] afterOriginal=1",
        count, static_cast<unsigned>(depth), stack);
  }
}


