// 7a66e71 src/dllmain.cpp:5277
void RepublishAuthoritativePlayerStatusAfterNativeRegistration(
    void* peer,
    const void* packet,
    int size,
    uintptr_t caller_rva) {
  constexpr uint32_t kHeaderSize = 4;
  constexpr uint32_t kEntrySize = 9;
  constexpr uint32_t kMaxEntryCount = 0x100;

  if (packet == nullptr || size < static_cast<int>(kHeaderSize)) {
    return;
  }

  const auto* bytes = static_cast<const uint8_t*>(packet);
  const uint32_t entry_count = ReadU32(bytes, UINT32_MAX);
  const uint64_t expected_size =
      static_cast<uint64_t>(kHeaderSize) +
      static_cast<uint64_t>(entry_count) * kEntrySize;
  if (entry_count > kMaxEntryCount ||
      expected_size != static_cast<uint64_t>(size)) {
    LogWarn(
        "PlayerStateRepublish native17_rejected peer=%p count=%u size=%d expected=%llu "
        "callerRva=%llx reason=invalid_native_registration_packet",
        peer,
        entry_count,
        size,
        static_cast<unsigned long long>(expected_size),
        static_cast<unsigned long long>(caller_rva));
    return;
  }

  if (g_entity_lookup == nullptr || g_world_chr_authority == nullptr ||
      g_world_chr_status_mark_dirty == nullptr || g_game_base == 0) {
    LogWarn(
        "PlayerStateRepublish native17_skipped peer=%p count=%u callerRva=%llx "
        "reason=native_function_unavailable lookup=%p authority=%p markDirty=%p",
        peer,
        entry_count,
        static_cast<unsigned long long>(caller_rva),
        reinterpret_cast<void*>(g_entity_lookup),
        reinterpret_cast<void*>(g_world_chr_authority),
        reinterpret_cast<void*>(g_world_chr_status_mark_dirty));
    return;
  }

  void* world_chr_man = GetWorldChrMan();
  if (world_chr_man == nullptr) {
    return;
  }
  void* status_manager = reinterpret_cast<void*>(ReadU64(
      static_cast<const uint8_t*>(world_chr_man) + 0x17530, 0));
  if (status_manager == nullptr) {
    return;
  }

  uint32_t active_count = 0;
  uint32_t player_count = 0;
  uint32_t authority_count = 0;
  uint32_t requeued_count = 0;
  uint32_t missing_count = 0;
  for (uint32_t index = 0; index < entry_count; ++index) {
    const uint8_t* entry = bytes + kHeaderSize + index * kEntrySize;
    const uint64_t raw_entity_id = ReadU64(entry, UINT64_MAX);
    const uint8_t active = ReadU8(entry + 8, 0);
    if (active == 0 || raw_entity_id == UINT64_MAX) {
      continue;
    }
    ++active_count;

    const EntityId entity_id{
        static_cast<uint32_t>(raw_entity_id),
        static_cast<uint32_t>(raw_entity_id >> 32)};
    void* entity = nullptr;
    EntityId lookup_id = entity_id;
    __try {
      entity = g_entity_lookup(world_chr_man, &lookup_id);
    } __except (LogSehException(
        "PlayerStateRepublish EntityLookup", GetExceptionInformation())) {
      entity = nullptr;
    }
    if (entity == nullptr) {
      ++missing_count;
      continue;
    }
    if (ReadU64(entity, 0) != g_game_base + kPlayerInsVtableRva) {
      continue;
    }
    ++player_count;

    uint8_t local_authority = 0;
    EntityId authority_id = entity_id;
    __try {
      local_authority = g_world_chr_authority(world_chr_man, &authority_id);
    } __except (LogSehException(
        "PlayerStateRepublish WorldChrAuthority", GetExceptionInformation())) {
      local_authority = 0;
    }
    if (local_authority == 0) {
      continue;
    }
    ++authority_count;

    EntityId dirty_id = entity_id;
    __try {
      g_world_chr_status_mark_dirty(status_manager, &dirty_id);
      ++requeued_count;
    } __except (LogSehException(
        "PlayerStateRepublish WorldChrStatusMarkDirty", GetExceptionInformation())) {
      LogError(
          "PlayerStateRepublish native17_mark_exception peer=%p entity=%08x:%08x "
          "statusManager=%p callerRva=%llx",
          peer,
          entity_id.high,
          entity_id.low,
          status_manager,
          static_cast<unsigned long long>(caller_rva));
    }
  }

  if (player_count != 0 || requeued_count != 0) {
    Log(
        "PlayerStateRepublish native17_post_send peer=%p count=%u active=%u players=%u "
        "authority=%u requeued=%u missing=%u statusManager=%p callerRva=%llx "
        "next=FUN_1404eec00_native_0x70",
        peer,
        entry_count,
        active_count,
        player_count,
        authority_count,
        requeued_count,
        missing_count,
        status_manager,
        static_cast<unsigned long long>(caller_rva));
  }
}


// 7a66e71 src/dllmain.cpp:11140
int CountPartyMemberPlayers(void* party_member_info) {
  if (party_member_info == nullptr) {
    return 0;
  }

  int count = 0;
  uint8_t slot[kPartyMemberSlotStride]{};
  for (int i = 0; i < kObservedPartyMemberSlots; ++i) {
    if (ReadPartyMemberSlot(party_member_info, i, slot) && PartyMemberSlotHasPlayer(slot)) {
      ++count;
    }
  }
  return count;
}


// 7a66e71 src/dllmain.cpp:11155
int CountRemotePlayerGameDataEntities() {
  int count = 0;
  for (uint32_t i = 0; i < kExpandedRemotePlayerGameDataSlots; ++i) {
    void* entry = GetRemotePlayerGameDataEntry(static_cast<int>(i));
    const uint32_t entity_id =
        entry != nullptr ? ReadU32(static_cast<const uint8_t*>(entry) + 8, kInvalidEntityPart) : kInvalidEntityPart;
    if (entity_id != kInvalidEntityPart) {
      ++count;
    }
  }
  return count;
}


// 7a66e71 src/dllmain.cpp:11335
int BhrcHexNibble(wchar_t value) {
  if (value >= L'0' && value <= L'9') {
    return static_cast<int>(value - L'0');
  }
  if (value >= L'a' && value <= L'f') {
    return static_cast<int>(value - L'a') + 10;
  }
  if (value >= L'A' && value <= L'F') {
    return static_cast<int>(value - L'A') + 10;
  }
  return -1;
}


