// 7a66e71 src/dllmain.cpp:12207
void MarkBhrcFullPgdRestoreGateStage(
    const BhrcExpeditionProbeAttempt& probe,
    BhrcFullPgdRestoreGateStage stage) {
  const BhrcNativeExpeditionAuthorityState authority =
      SnapshotNativeExpeditionAuthority();
  BhrcExpeditionWorldPhaseState world_phase{};
  if (stage == BhrcFullPgdRestoreGateStage::FinalApplied) {
    AcquireSRWLockShared(&g_bhrc_expedition_world_phase_lock);
    world_phase = g_bhrc_expedition_world_phase;
    ReleaseSRWLockShared(&g_bhrc_expedition_world_phase_lock);
  }
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  if (BhrcFullPgdRestoreGateMatchesProbe(
          g_bhrc_full_pgd_restore_gate, probe, authority) &&
      static_cast<uint8_t>(stage) >
          static_cast<uint8_t>(g_bhrc_full_pgd_restore_gate.stage)) {
    if (g_bhrc_full_pgd_restore_gate.local_manager_id == 0) {
      g_bhrc_full_pgd_restore_gate.local_manager_id =
          authority.manager_id;
    }
    if (g_bhrc_full_pgd_restore_gate.native_manager == nullptr) {
      g_bhrc_full_pgd_restore_gate.native_manager =
          authority.native_manager;
    }
    g_bhrc_full_pgd_restore_gate.stage = stage;
    if (stage == BhrcFullPgdRestoreGateStage::FinalApplied) {
      g_bhrc_full_pgd_restore_gate.final_world_chr_man =
          ReadGameGlobalPtr(kWorldChrManPtrRva);
      if (BhrcFullPgdRestoreTicketMatchesProbe(
              g_bhrc_full_pgd_restore_ticket, probe) &&
          g_bhrc_full_pgd_restore_ticket.final_applied) {
        g_bhrc_full_pgd_restore_gate.final_player_game_data =
            g_bhrc_full_pgd_restore_ticket.final_player_game_data;
      }
      g_bhrc_full_pgd_restore_gate.final_local_base_registration_seq =
          world_phase.local_base_registration_seq;
    }
    g_bhrc_full_pgd_restore_gate.updated_tick_ms = GetTickCount64();
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
}


// 7a66e71 src/dllmain.cpp:12249
bool IsBhrcFullPgdCaptureFrozen(
    const BhrcNativeExpeditionAuthorityState& authority,
    uint64_t local_steam_id,
    uint64_t host_steam_id) {
  const BhrcExpeditionProbeAttempt probe = SnapshotBhrcExpeditionProbe();
  if ((probe.full_pgd_restore_expired || probe.full_pgd_restore_finished) &&
      probe.host_steam_id == host_steam_id &&
      probe.master_lobby_id == authority.master_lobby_id &&
      probe.expedition_lobby_id == authority.lobby_id &&
      probe.authority_commit_seq == authority.commit_seq) {
    return false;
  }
  bool frozen = false;
  AcquireSRWLockShared(&g_bhrc_full_pgd_restore_lock);
  frozen = g_bhrc_full_pgd_restore_gate.valid &&
      g_bhrc_full_pgd_restore_gate.local_steam_id == local_steam_id &&
      g_bhrc_full_pgd_restore_gate.host_steam_id == host_steam_id &&
      g_bhrc_full_pgd_restore_gate.master_lobby_id ==
          authority.master_lobby_id &&
      g_bhrc_full_pgd_restore_gate.expedition_lobby_id ==
          authority.lobby_id &&
      g_bhrc_full_pgd_restore_gate.authority_commit_seq ==
          authority.commit_seq &&
      g_bhrc_full_pgd_restore_gate.local_manager_id ==
          authority.manager_id &&
      g_bhrc_full_pgd_restore_gate.native_manager != nullptr &&
      g_bhrc_full_pgd_restore_gate.native_manager ==
          authority.native_manager &&
      static_cast<uint8_t>(g_bhrc_full_pgd_restore_gate.stage) <
          static_cast<uint8_t>(
              BhrcFullPgdRestoreGateStage::FinalApplied);
  ReleaseSRWLockShared(&g_bhrc_full_pgd_restore_lock);
  return frozen;
}


// 7a66e71 src/dllmain.cpp:12276
void* ResolveBhrcFinalFullPgdRestoreTarget(
    const BhrcExpeditionProbeAttempt& probe,
    const BhrcNativeExpeditionAuthorityState& authority) {
  void* const local_pgd =
      ResolveBhrcAuthorizedFullPgdRestoreTarget(probe, authority);
  if (local_pgd == nullptr) {
    return nullptr;
  }

  BhrcExpeditionWorldPhaseState world_phase{};
  AcquireSRWLockShared(&g_bhrc_expedition_world_phase_lock);
  world_phase = g_bhrc_expedition_world_phase;
  ReleaseSRWLockShared(&g_bhrc_expedition_world_phase_lock);
  void* const current_world_chr_man =
      ReadGameGlobalPtr(kWorldChrManPtrRva);
  const ULONGLONG now = GetTickCount64();
  if (world_phase.authority_commit_seq != authority.commit_seq ||
      world_phase.last_local_base_authority_seq != authority.commit_seq ||
      world_phase.local_base_registration_seq <=
          world_phase.commit_local_base_registration_seq ||
      world_phase.last_local_base_world_chr_man == nullptr ||
      world_phase.last_local_base_world_chr_man != current_world_chr_man ||
      world_phase.last_local_base_registration_tick_ms == 0 ||
      now < world_phase.last_local_base_registration_tick_ms ||
      now - world_phase.last_local_base_registration_tick_ms <
          kBhrcFullPgdRestoreTargetStableMs) {
    return nullptr;
  }
  // Observe the original local-base WorldChr registration as the generation
  // boundary.  The restored PGD's game-data id is part of the body being
  // repaired and is therefore not a valid prerequisite for reaching the final
  // native deserialize pass.
  return local_pgd;
}


