void __fastcall HookBhrcReconnectRuneFinalizer(
    void* context,
    uint8_t mode) {
  if (g_bhrc_reconnect_rune_finalizer == nullptr) {
    return;
  }

  const BhrcExpeditionProbeAttempt probe = SnapshotBhrcExpeditionProbe();
  const void* caller = _ReturnAddress();
  LONG trace_seq = 0;
  const bool trace = context != nullptr &&
      context == ReadGameGlobalPtr(kBhrcRuneControllerGlobalPtrRva) &&
      BhrcDiagnosticBudget(&g_bhrc_rune_finalize_count, 64, "rune_finalize", &trace_seq);
  const BhrcRuneSnapshot before = trace ? ReadBhrcRuneSnapshot() : BhrcRuneSnapshot{};
  if (probe.trigger !=
          BhrcExpeditionProbeTrigger::StartupPreviousSession ||
      probe.request_nonce == 0) {
    __try { g_bhrc_reconnect_rune_finalizer(context, mode); }
    __finally {
      if (trace) {
        Log("BHRC_RUNE_TRACE finalize_gate seq=%ld trigger=%s stage=%s nonce=%08x modeIn=%u modeOut=%u suppress=0 reason=not_automatic_attempt",
            trace_seq, BhrcExpeditionProbeTriggerName(probe.trigger),
            BhrcExpeditionProbeStageName(probe.stage), probe.request_nonce, mode, mode);
        LogBhrcRuneTransition("finalize_729200", trace_seq, before, caller, mode, mode,
                              AbnormalTermination() != FALSE);
        if (trace_seq <= 16) LogBhrcDiagnosticStack("rune_finalize", trace_seq);
      }
    }
    return;
  }

  const uint64_t local_steam_id =
      g_nrsc_steam_control_state.local_steam_id;
  const bool restore_pending = IsBhrcFullPgdRestorePendingForProbe(probe);
  const uintptr_t caller_rva = RvaOf(caller);
  const bool loading_settlement = caller_rva == 0xc3f2df || caller_rva == 0xc3f4e5;
  const BhrcNativeExpeditionAuthorityState authority = SnapshotNativeExpeditionAuthority();
  AcquireSRWLockShared(&g_bhrc_full_pgd_restore_lock);
  // The gate also retains final completion when a transport ticket is retired
  // or its nonce is rearmed. Do not use the over-strict admission completion
  // predicate to prolong this currency guard after an applied final restore.
  const bool restore_finished =
      (BhrcFullPgdRestoreTicketMatchesProbe(g_bhrc_full_pgd_restore_ticket, probe) &&
       g_bhrc_full_pgd_restore_ticket.final_applied) ||
      (BhrcFullPgdRestoreGateMatchesProbe(g_bhrc_full_pgd_restore_gate, probe, authority) &&
       static_cast<uint8_t>(g_bhrc_full_pgd_restore_gate.stage) >=
           static_cast<uint8_t>(BhrcFullPgdRestoreGateStage::FinalApplied));
  ReleaseSRWLockShared(&g_bhrc_full_pgd_restore_lock);
  // The original positive-confirm callback precedes the previous-session
  // owner. Cover that loading interval too, without arming on a mere offer.
  const bool confirmed_restore_phase =
      (probe.stage == BhrcExpeditionProbeStage::AuthorizedReturning &&
       probe.restoring_player_metadata) ||
      (probe.stage == BhrcExpeditionProbeStage::HandedOff &&
       probe.native_owner_ready);
  const bool local_context = context != nullptr &&
      context == ReadGameGlobalPtr(kBhrcRuneControllerGlobalPtrRva);
  const bool exact_pending_automatic_reconnect =
      mode == 0 && local_context && !IsLocalNrscHost() &&
      loading_settlement && confirmed_restore_phase && !restore_finished &&
      probe.host_phase == BhrcExpeditionHostPhase::RunningExpedition &&
      probe.membership == BhrcExpeditionMembership::ReturningSameB &&
      probe.native_attempt_running_authorized &&
      !probe.native_attempt_transport_lost &&
      !probe.authority_observer_only &&
      probe.master_lobby_id != 0 && probe.expedition_lobby_id != 0 &&
      probe.host_steam_id != 0 && local_steam_id != 0 &&
      probe.host_steam_id != local_steam_id &&
      probe.record_key == local_steam_id && probe.authority_commit_seq != 0 &&
      probe.manager_id != 0 && GetCurrentNrscMasterLobbyId() == probe.master_lobby_id &&
      g_nrsc_steam_control_state.owner_steam_id == probe.host_steam_id;

  __try {
    g_bhrc_reconnect_rune_finalizer(
        context, exact_pending_automatic_reconnect ? 1 : mode);
  } __finally {
    if (trace) {
      Log("BHRC_RUNE_TRACE finalize_gate seq=%ld trigger=%s stage=%s nonce=%08x generation=%u modeIn=%u modeOut=%u suppress=%d pending=%d confirmed=%d localContext=%d metadataPhase=%d ownerReady=%d phase=%s membership=%s runningAuthorized=%d transportLost=%d observerOnly=%d masterA=%016llx expeditionB=%016llx host=%016llx local=%016llx recordKey=%016llx localHost=%d loadingSettlement=%d finalApplied=%d requiresReceivedTicket=0 normalDeathPassthrough=1 originalCalls=1 policy=authorized_loading_until_final",
          trace_seq, BhrcExpeditionProbeTriggerName(probe.trigger), BhrcExpeditionProbeStageName(probe.stage),
          probe.request_nonce, probe.client_generation, mode, exact_pending_automatic_reconnect ? 1 : mode,
          exact_pending_automatic_reconnect ? 1 : 0, restore_pending ? 1 : 0,
          confirmed_restore_phase ? 1 : 0, local_context ? 1 : 0,
          probe.restoring_player_metadata ? 1 : 0, probe.native_owner_ready ? 1 : 0,
          BhrcExpeditionHostPhaseName(probe.host_phase), BhrcExpeditionMembershipName(probe.membership),
          probe.native_attempt_running_authorized ? 1 : 0, probe.native_attempt_transport_lost ? 1 : 0,
          probe.authority_observer_only ? 1 : 0,
          static_cast<unsigned long long>(probe.master_lobby_id),
          static_cast<unsigned long long>(probe.expedition_lobby_id),
          static_cast<unsigned long long>(probe.host_steam_id),
          static_cast<unsigned long long>(local_steam_id),
          static_cast<unsigned long long>(probe.record_key), IsLocalNrscHost() ? 1 : 0,
          loading_settlement ? 1 : 0, restore_finished ? 1 : 0);
      LogBhrcRuneTransition("finalize_729200", trace_seq, before, caller, mode,
          exact_pending_automatic_reconnect ? 1 : mode, AbnormalTermination() != FALSE);
      if (trace_seq <= 16) LogBhrcDiagnosticStack("rune_finalize", trace_seq);
    }
  }

}


// 7a66e71 src/dllmain.cpp:12384
void MarkBhrcFullPgdRestoreFailed(
    const BhrcFullPgdRestoreTicket& expected,
    const char* reason) {
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  if (SameBhrcFullPgdRestoreTicketIdentity(
          g_bhrc_full_pgd_restore_ticket, expected)) {
    if (g_bhrc_full_pgd_restore_ticket.cancel_pending) {
      g_bhrc_full_pgd_restore_ticket = BhrcFullPgdRestoreTicket{};
      std::memset(
          g_bhrc_full_pgd_restore_payload, 0,
          sizeof(g_bhrc_full_pgd_restore_payload));
    } else {
      g_bhrc_full_pgd_restore_ticket.applying = false;
      g_bhrc_full_pgd_restore_ticket.failed = true;
      g_bhrc_full_pgd_restore_ticket.applied = false;
    }
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  LogWarn(
      "BHRC full_pgd_restore outcome=failed reason=%s owner=%016llx host=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu nonce=%08x clientGeneration=%u codecVersion=%u revision=%llu size=%u hash=%08x retryCorruptBlob=0 coldStorage=0",
      reason != nullptr ? reason : "unknown",
      static_cast<unsigned long long>(expected.owner_steam_id),
      static_cast<unsigned long long>(expected.host_steam_id),
      static_cast<unsigned long long>(expected.master_lobby_id),
      static_cast<unsigned long long>(expected.expedition_lobby_id),
      static_cast<unsigned long long>(expected.authority_commit_seq),
      expected.request_nonce, expected.client_generation,
      expected.codec_version,
      static_cast<unsigned long long>(expected.snapshot_revision),
      expected.payload_size, expected.payload_hash32);
}


// Only the game thread retires a pending application. A network receive can
// reject an expired packet, but must not interrupt native deserialize/refresh.
void ExpireBhrcFullPgdRestoreWindowMainThread() {
  const ULONGLONG now = GetTickCount64();
  const auto before = SnapshotBhrcExpeditionProbe();
  if (before.full_pgd_restore_expired || before.full_pgd_restore_finished ||
      !BhrcFullPgdRestoreDeadlineElapsed(
          before.full_pgd_restore_started_tick_ms, now)) return;
  BhrcExpeditionProbeAttempt expired{};
  bool retired = false;
  bool seed_applied = false;
  AcquireSRWLockExclusive(&g_bhrc_expedition_probe_lock);
  auto& probe = g_bhrc_expedition_probe;
  if (!probe.full_pgd_restore_expired && !probe.full_pgd_restore_finished &&
      BhrcFullPgdRestoreDeadlineElapsed(
          probe.full_pgd_restore_started_tick_ms, now)) {
    AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
    auto& ticket = g_bhrc_full_pgd_restore_ticket;
    const bool same_ticket = ticket.valid &&
        ticket.host_steam_id == probe.host_steam_id &&
        ticket.master_lobby_id == probe.master_lobby_id &&
        ticket.client_generation == probe.client_generation;
    const bool final_applied = same_ticket && ticket.final_applied;
    if (!ticket.applying && !final_applied) {
      probe.full_pgd_restore_expired = true;
      expired = probe;
      if (same_ticket) {
        seed_applied = ticket.applied;
        ticket.failed = true;
        ticket.cancel_pending = true;
        std::memset(g_bhrc_full_pgd_restore_payload, 0,
                    sizeof(g_bhrc_full_pgd_restore_payload));
      }
      retired = true;
    }
    ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  }
  ReleaseSRWLockExclusive(&g_bhrc_expedition_probe_lock);
  if (!retired) return;

  AcquireSRWLockExclusive(&g_bhrc_full_pgd_assembly_lock);
  for (auto& assembly : g_bhrc_full_pgd_inbound_assemblies) {
    if (assembly.valid && assembly.purpose ==
            static_cast<uint16_t>(BhrcFullPgdTransferPurpose::RestoreDelivery) &&
        assembly.sender_steam_id == expired.host_steam_id &&
        assembly.master_lobby_id == expired.master_lobby_id &&
        assembly.client_generation == expired.client_generation) {
      std::memset(&assembly, 0, sizeof(assembly));
    }
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_assembly_lock);
  LogWarn(
      "BHRC full_pgd_restore_window outcome=expired nonce=%08x clientGeneration=%u host=%016llx masterA=%016llx expeditionB=%016llx startedTickMs=%llu elapsedMs=%llu limitMs=%llu seedApplied=%d finalApplied=0 pendingReplayCancelled=1 keepCurrentNativeData=1 leaveLobby=0 admissionCompleted=0",
      expired.request_nonce, expired.client_generation,
      static_cast<unsigned long long>(expired.host_steam_id),
      static_cast<unsigned long long>(expired.master_lobby_id),
      static_cast<unsigned long long>(expired.expedition_lobby_id),
      static_cast<unsigned long long>(expired.full_pgd_restore_started_tick_ms),
      static_cast<unsigned long long>(now - expired.full_pgd_restore_started_tick_ms),
      static_cast<unsigned long long>(kBhrcFullPgdRestoreWindowMs),
      seed_applied ? 1 : 0);
}

// 7a66e71 src/dllmain.cpp:12416
void TryApplyBhrcFullPgdRestoreMainThread(bool post_native_update) {
  if (IsLocalNrscHost() || g_player_game_data_full_deserialize == nullptr ||
      g_player_game_data_codec_version == nullptr ||
      g_native_read_stream_init == nullptr ||
      g_native_read_stream_destroy == nullptr ||
      g_player_game_data_post_load_refresh == nullptr ||
      g_player_game_data_post_load_rebuild == nullptr) {
    return;
  }
  const BhrcExpeditionProbeAttempt probe = SnapshotBhrcExpeditionProbe();
  // Drain only a seed started in this exact native update. This is not a
  // renewed window: no later frame may start or finish an expired replay.
  const bool finish_current_update = post_native_update &&
      g_bhrc_full_pgd_seed_applied_this_update;
  if (BhrcFullPgdRestoreWindowClosed(probe) && !finish_current_update) {
    ExpireBhrcFullPgdRestoreWindowMainThread();
    return;
  }
  if (!IsBhrcAuthorizedClientProbe(probe) ||
      probe.membership != BhrcExpeditionMembership::ReturningSameB ||
      !probe.native_owner_ready) {
    return;
  }

  BhrcFullPgdRestoreTicket ticket{};
  AcquireSRWLockShared(&g_bhrc_full_pgd_restore_lock);
  ticket = g_bhrc_full_pgd_restore_ticket;
  ReleaseSRWLockShared(&g_bhrc_full_pgd_restore_lock);
  if (!BhrcFullPgdRestoreTicketMatchesProbe(ticket, probe) ||
      ticket.applying || ticket.final_applied || ticket.failed ||
      ticket.cancel_pending) {
    return;
  }
  const bool final_stage = ticket.applied;
  // The seed must exist before the original update builds the reconnecting
  // player.  The final replay must run after that update: the native
  // reconnect/death command can update PGD+0xd4 during the same frame, and a
  // pre-update final replay would let that transient death-rune pool survive.
  if (final_stage != post_native_update) {
    return;
  }

  const BhrcNativeExpeditionAuthorityState local_authority =
      SnapshotNativeExpeditionAuthority();
  if (!local_authority.valid ||
      local_authority.manager_id == 0 ||
      ticket.local_manager_id != local_authority.manager_id ||
      ticket.native_manager == nullptr ||
      ticket.native_manager != local_authority.native_manager) {
    return;
  }
  void* const local_pgd = final_stage
      ? ResolveBhrcFinalFullPgdRestoreTarget(probe, local_authority)
      : ResolveBhrcAuthorizedFullPgdRestoreTarget(probe, local_authority);
  if (local_pgd == nullptr) {
    return;
  }
  void* const effect_player = final_stage ? BhrcEffectLocalPlayer() : nullptr;
  if (final_stage) {
    const auto* controller = effect_player != nullptr
        ? reinterpret_cast<const uint8_t*>(ReadU64(static_cast<const uint8_t*>(effect_player) + 0x190, 0))
        : nullptr;
    if (effect_player == nullptr || controller == nullptr ||
        ReadU64(controller + 0x10, 0) != reinterpret_cast<uint64_t>(effect_player)) return;
  }
  const int32_t local_record_d4_id =
      ReadI32(static_cast<const uint8_t*>(local_pgd) + 8, -1);
  if (local_record_d4_id < 0) {
    return;
  }

  const ULONGLONG now = GetTickCount64();
  if (!final_stage) {
    bool target_stable = false;
    AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
    if (SameBhrcFullPgdRestoreTicketIdentity(
            g_bhrc_full_pgd_restore_ticket, ticket) &&
        !g_bhrc_full_pgd_restore_ticket.applying &&
        !g_bhrc_full_pgd_restore_ticket.applied &&
        !g_bhrc_full_pgd_restore_ticket.failed &&
        !g_bhrc_full_pgd_restore_ticket.cancel_pending) {
      if (g_bhrc_full_pgd_restore_ticket.ready_player_game_data != local_pgd ||
          g_bhrc_full_pgd_restore_ticket.ready_record_d4_id !=
              local_record_d4_id ||
          g_bhrc_full_pgd_restore_ticket.ready_since_tick_ms == 0 ||
          now < g_bhrc_full_pgd_restore_ticket.ready_since_tick_ms) {
        g_bhrc_full_pgd_restore_ticket.ready_player_game_data = local_pgd;
        g_bhrc_full_pgd_restore_ticket.ready_record_d4_id =
            local_record_d4_id;
        g_bhrc_full_pgd_restore_ticket.ready_since_tick_ms = now;
      } else {
        target_stable =
            now - g_bhrc_full_pgd_restore_ticket.ready_since_tick_ms >=
            kBhrcFullPgdRestoreTargetStableMs;
      }
    }
    ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
    if (!target_stable) {
      return;
    }
  }

  const uint32_t current_codec = g_player_game_data_codec_version();
  if (current_codec == 0 || current_codec != ticket.codec_version) {
    MarkBhrcFullPgdRestoreFailed(ticket, "codec_version_mismatch");
    return;
  }
  uint8_t* payload = static_cast<uint8_t*>(
      HeapAlloc(GetProcessHeap(), 0, ticket.payload_size));
  if (payload == nullptr) {
    return;
  }
  bool claimed = false;
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  if (SameBhrcFullPgdRestoreTicketIdentity(
          g_bhrc_full_pgd_restore_ticket, ticket) &&
      !g_bhrc_full_pgd_restore_ticket.applying &&
      g_bhrc_full_pgd_restore_ticket.applied == final_stage &&
      !g_bhrc_full_pgd_restore_ticket.final_applied &&
      !g_bhrc_full_pgd_restore_ticket.failed &&
      !g_bhrc_full_pgd_restore_ticket.cancel_pending &&
      (finish_current_update || !BhrcFullPgdRestoreWindowClosed(probe)) &&
      (final_stage ||
       (g_bhrc_full_pgd_restore_ticket.ready_player_game_data == local_pgd &&
        g_bhrc_full_pgd_restore_ticket.ready_record_d4_id ==
            local_record_d4_id &&
        g_bhrc_full_pgd_restore_ticket.ready_since_tick_ms != 0 &&
        now >= g_bhrc_full_pgd_restore_ticket.ready_since_tick_ms &&
        now - g_bhrc_full_pgd_restore_ticket.ready_since_tick_ms >=
            kBhrcFullPgdRestoreTargetStableMs))) {
    g_bhrc_full_pgd_restore_ticket.applying = true;
    std::memcpy(
        payload, g_bhrc_full_pgd_restore_payload, ticket.payload_size);
    ticket = g_bhrc_full_pgd_restore_ticket;
    claimed = true;
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  if (!claimed) {
    HeapFree(GetProcessHeap(), 0, payload);
    return;
  }
  if (BhrcFnv1a32(payload, ticket.payload_size) !=
      ticket.payload_hash32) {
    HeapFree(GetProcessHeap(), 0, payload);
    MarkBhrcFullPgdRestoreFailed(ticket, "restore_blob_identity_mismatch");
    return;
  }

  std::memset(g_bhrc_full_pgd_reader_stream, 0,
              sizeof(g_bhrc_full_pgd_reader_stream));
  bool initialized = false;
  bool applied = false;
  const uint8_t previous_effect_phase = g_bhrc_effect_replay_phase;
  const uint64_t previous_effect_revision = g_bhrc_effect_replay_revision;
  const uint32_t previous_effect_hash = g_bhrc_effect_replay_hash;
  g_bhrc_effect_replay_phase = final_stage ? 2 : 1;
  g_bhrc_effect_replay_revision = ticket.snapshot_revision;
  g_bhrc_effect_replay_hash = ticket.payload_hash32;
  if (g_bhrc_effect_trace_window.nonce != probe.request_nonce ||
      g_bhrc_effect_trace_window.generation != probe.client_generation) {
    g_bhrc_effect_trace_window = BhrcEffectTraceWindow{};
    g_bhrc_effect_trace_window.nonce = probe.request_nonce;
    g_bhrc_effect_trace_window.generation = probe.client_generation;
    g_bhrc_effect_trace_window.pgd = local_pgd;
  }
  InterlockedExchange64(&g_bhrc_effect_trace_until_ms,
                        static_cast<LONG64>(GetTickCount64() + 30000));
  __try {
    g_native_read_stream_init(
        g_bhrc_full_pgd_reader_stream, payload, ticket.payload_size);
    initialized = true;
    applied = g_player_game_data_full_deserialize(
                  local_pgd, g_bhrc_full_pgd_reader_stream,
                  ticket.codec_version) != 0;
  } __except (LogSehException(
      "BHRC full PlayerGameData deserialize", GetExceptionInformation())) {
    applied = false;
  }
  if (initialized) {
    __try {
      g_native_read_stream_destroy(g_bhrc_full_pgd_reader_stream);
    } __except (LogSehException(
        "BHRC full PlayerGameData reader destroy", GetExceptionInformation())) {
      applied = false;
    }
  }
  if (!applied) {
    g_bhrc_effect_replay_phase = previous_effect_phase;
    g_bhrc_effect_replay_revision = previous_effect_revision;
    g_bhrc_effect_replay_hash = previous_effect_hash;
    HeapFree(GetProcessHeap(), 0, payload);
    MarkBhrcFullPgdRestoreFailed(ticket, "native_deserializer_rejected");
    return;
  }
  bool refresh_ok = true;
  __try {
    // Exact post-load order used by FUN_1406b24a0 after a successful native
    // PlayerGameData load. This rebuilds dependent inventory/status views.
    g_player_game_data_post_load_refresh(local_pgd);
    LogBhrcEffectSnapshot("after_refresh", local_pgd, -1);
    g_player_game_data_post_load_rebuild(local_pgd);
    LogBhrcEffectSnapshot("after_rebuild", local_pgd, -1);
  } __except (LogSehException(
      "BHRC full PlayerGameData post-load refresh",
      GetExceptionInformation())) {
    refresh_ok = false;
  }
  if (!refresh_ok) {
    g_bhrc_effect_replay_phase = previous_effect_phase;
    g_bhrc_effect_replay_revision = previous_effect_revision;
    g_bhrc_effect_replay_hash = previous_effect_hash;
    HeapFree(GetProcessHeap(), 0, payload);
    MarkBhrcFullPgdRestoreFailed(ticket, "native_post_load_refresh_exception");
    return;
  }

  // Native construction may already have applied some saved effects. After
  // final PGD replay, apply only the missing multiplicities to this same actor.
  if (final_stage) {
    uint32_t already_present = 0, pending_apply = 0;
    bool effects_ok = effect_player == BhrcEffectLocalPlayer() && local_pgd == BhrcEffectLocalPgd();
    const auto current_probe = SnapshotBhrcExpeditionProbe();
    effects_ok = effects_ok && current_probe.request_nonce == probe.request_nonce &&
        current_probe.client_generation == probe.client_generation &&
        current_probe.authority_commit_seq == probe.authority_commit_seq;
    AcquireSRWLockShared(&g_bhrc_full_pgd_restore_lock);
    effects_ok = effects_ok && SameBhrcFullPgdRestoreTicketIdentity(g_bhrc_full_pgd_restore_ticket, ticket) &&
        g_bhrc_full_pgd_restore_ticket.applying && !g_bhrc_full_pgd_restore_ticket.cancel_pending;
    ReleaseSRWLockShared(&g_bhrc_full_pgd_restore_lock);
    if (effects_ok) {
      __try {
        LogBhrcEffectSnapshot("before_final_saved_effect_apply", local_pgd, -1);
        effects_ok = ApplyBhrcMissingSavedEffects(local_pgd, effect_player, &already_present, &pending_apply);
        LogBhrcEffectSnapshot("after_final_saved_effect_apply", local_pgd, -1);
      } __except (LogSehException("BHRC final saved effects apply", GetExceptionInformation())) {
        effects_ok = false;
      }
    }
    if (!effects_ok) {
      g_bhrc_effect_replay_phase = previous_effect_phase;
      g_bhrc_effect_replay_revision = previous_effect_revision;
      g_bhrc_effect_replay_hash = previous_effect_hash;
      HeapFree(GetProcessHeap(), 0, payload);
      MarkBhrcFullPgdRestoreFailed(ticket, "final_saved_effect_target_or_apply_failed");
      return;
    }
    Log("BHRC full_pgd_saved_effects outcome=applied nonce=%08x generation=%u revision=%llu pgd=%p player=%p nativeApply=2099e0 calls=1 scope=post_world_final alreadyPresent=%u pendingApply=%u policy=missing_multiplicity_only existingActorRemoved=0",
        probe.request_nonce, probe.client_generation,
        static_cast<unsigned long long>(ticket.snapshot_revision), local_pgd, effect_player,
        already_present, pending_apply);
  }

  bool committed = false;
  bool cancelled = false;
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  if (SameBhrcFullPgdRestoreTicketIdentity(
          g_bhrc_full_pgd_restore_ticket, ticket) &&
      g_bhrc_full_pgd_restore_ticket.applying) {
    if (g_bhrc_full_pgd_restore_ticket.cancel_pending) {
      g_bhrc_full_pgd_restore_ticket = BhrcFullPgdRestoreTicket{};
      std::memset(
          g_bhrc_full_pgd_restore_payload, 0,
          sizeof(g_bhrc_full_pgd_restore_payload));
      cancelled = true;
    } else {
      g_bhrc_full_pgd_restore_ticket.applying = false;
      g_bhrc_full_pgd_restore_ticket.failed = false;
      if (final_stage) {
        g_bhrc_full_pgd_restore_ticket.final_applied = true;
        g_bhrc_full_pgd_restore_ticket.final_player_game_data = local_pgd;
        g_bhrc_full_pgd_restore_ticket.final_applied_tick_ms =
            GetTickCount64();
      } else {
        g_bhrc_full_pgd_restore_ticket.applied = true;
        g_bhrc_full_pgd_restore_ticket.applied_player_game_data = local_pgd;
        g_bhrc_full_pgd_restore_ticket.applied_tick_ms = GetTickCount64();
      }
      committed = true;
    }
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  bool hot_revision_floor_installed = !final_stage;
  if (committed && final_stage) {
    hot_revision_floor_installed = StoreBhrcFullPgdHotSnapshot(
        ticket.owner_steam_id, ticket.master_lobby_id,
        ticket.expedition_lobby_id, ticket.authority_commit_seq,
        ticket.codec_version, ticket.snapshot_revision, payload,
        ticket.payload_size, ticket.payload_hash32, false,
        "native_full_pgd_restore_revision_floor", nullptr, true);
    if (!hot_revision_floor_installed) {
      LogError(
          "BHRC full_pgd_restore_hot_floor outcome=failed owner=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu revision=%llu size=%u hash=%08x",
          static_cast<unsigned long long>(ticket.owner_steam_id),
          static_cast<unsigned long long>(ticket.master_lobby_id),
          static_cast<unsigned long long>(ticket.expedition_lobby_id),
          static_cast<unsigned long long>(ticket.authority_commit_seq),
          static_cast<unsigned long long>(ticket.snapshot_revision),
          ticket.payload_size, ticket.payload_hash32);
    }
  }
  HeapFree(GetProcessHeap(), 0, payload);
  if (committed) {
    if (!final_stage) g_bhrc_full_pgd_seed_applied_this_update = true;
    MarkBhrcFullPgdRestoreGateStage(
        probe,
        final_stage
            ? BhrcFullPgdRestoreGateStage::FinalApplied
            : BhrcFullPgdRestoreGateStage::SeedApplied);
  }
  if (committed && final_stage) {
    AcquireSRWLockExclusive(&g_bhrc_expedition_probe_lock);
    if (g_bhrc_expedition_probe.request_nonce == probe.request_nonce &&
        g_bhrc_expedition_probe.client_generation == probe.client_generation &&
        g_bhrc_expedition_probe.full_pgd_restore_started_tick_ms ==
            probe.full_pgd_restore_started_tick_ms) {
      g_bhrc_expedition_probe.full_pgd_restore_finished = true;
    }
    ReleaseSRWLockExclusive(&g_bhrc_expedition_probe_lock);
    g_bhrc_effect_trace_window.final_tick_ms = GetTickCount64();
    g_bhrc_effect_trace_window.pgd = local_pgd;
  }
  Log(
      "BHRC full_pgd_restore outcome=%s stage=%s reason=native_complete_pgd_applied owner=%016llx host=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu nonce=%08x clientGeneration=%u codecVersion=%u revision=%llu size=%u hash=%08x pgd=%p deserializeCalls=1 postLoadCalls=2 nativeUpdateBoundary=%s identityStable=1 coldStorage=0",
      committed ? "applied" : (cancelled ? "cancelled" : "superseded"),
      final_stage ? "post_world_final" : "pre_world_seed",
      static_cast<unsigned long long>(ticket.owner_steam_id),
      static_cast<unsigned long long>(ticket.host_steam_id),
      static_cast<unsigned long long>(ticket.master_lobby_id),
      static_cast<unsigned long long>(ticket.expedition_lobby_id),
      static_cast<unsigned long long>(ticket.authority_commit_seq),
      ticket.request_nonce, ticket.client_generation, ticket.codec_version,
      static_cast<unsigned long long>(ticket.snapshot_revision),
      ticket.payload_size, ticket.payload_hash32, local_pgd,
      post_native_update ? "post_original" : "pre_original");
  g_bhrc_effect_replay_phase = previous_effect_phase;
  g_bhrc_effect_replay_revision = previous_effect_revision;
  g_bhrc_effect_replay_hash = previous_effect_hash;
}


// 7a66e71 src/dllmain.cpp:12673
void ClearBhrcFullPgdTransportForPeer(uint64_t steam_id, const char* reason) {
  uint32_t assemblies = 0;
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_assembly_lock);
  for (BhrcFullPgdInboundAssembly& assembly :
       g_bhrc_full_pgd_inbound_assemblies) {
    if (assembly.valid &&
        (assembly.sender_steam_id == steam_id ||
         assembly.target_steam_id == steam_id)) {
      std::memset(&assembly, 0, sizeof(assembly));
      ++assemblies;
    }
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_assembly_lock);
  bool ticket_cleared = false;
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  if (g_bhrc_full_pgd_restore_ticket.valid &&
      g_bhrc_full_pgd_restore_ticket.host_steam_id == steam_id) {
    if (g_bhrc_full_pgd_restore_ticket.applying) {
      g_bhrc_full_pgd_restore_ticket.cancel_pending = true;
    } else {
      g_bhrc_full_pgd_restore_ticket = BhrcFullPgdRestoreTicket{};
      std::memset(
          g_bhrc_full_pgd_restore_payload, 0,
          sizeof(g_bhrc_full_pgd_restore_payload));
    }
    ticket_cleared = true;
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  if (assemblies != 0 || ticket_cleared) {
    Log(
        "BHRC full_pgd_transport_clear reason=%s peer=%016llx assemblies=%u restoreTicket=%d hotSnapshotsRetained=1 coldStorage=0",
        reason != nullptr ? reason : "unknown",
        static_cast<unsigned long long>(steam_id), assemblies,
        ticket_cleared ? 1 : 0);
  }
}


// 7a66e71 src/dllmain.cpp:12710
void ClearBhrcFullPgdAdmissionTransport(const char* reason) {
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_assembly_lock);
  for (BhrcFullPgdInboundAssembly& assembly :
       g_bhrc_full_pgd_inbound_assemblies) {
    std::memset(&assembly, 0, sizeof(assembly));
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_assembly_lock);
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  if (g_bhrc_full_pgd_restore_ticket.applying) {
    g_bhrc_full_pgd_restore_ticket.cancel_pending = true;
  } else {
    g_bhrc_full_pgd_restore_ticket = BhrcFullPgdRestoreTicket{};
    std::memset(
        g_bhrc_full_pgd_restore_payload, 0,
        sizeof(g_bhrc_full_pgd_restore_payload));
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  Log(
      "BHRC full_pgd_admission_transport_clear reason=%s hotSnapshotsRetained=1 coldStorage=0",
      reason != nullptr ? reason : "unknown");
}


// 7a66e71 src/dllmain.cpp:12732
void ReconcileBhrcFullPgdAuthorityGeneration(
    const BhrcNativeExpeditionAuthorityState& previous,
    const BhrcNativeExpeditionAuthorityState& committed) {
  if (!committed.valid) {
    return;
  }
  // The authorized probe describes the host's authority generation.  Its
  // manager id is meaningful only in the host process; committed.manager_id
  // identifies the independently-created manager in this client process.
  const BhrcExpeditionProbeAttempt probe =
      SnapshotBhrcExpeditionProbe();
  const bool probe_matches_committed =
      IsBhrcAuthorizedClientProbe(probe) &&
      probe.membership == BhrcExpeditionMembership::ReturningSameB &&
      probe.host_steam_id == committed.owner_steam_id &&
      probe.master_lobby_id == committed.master_lobby_id &&
      probe.expedition_lobby_id == committed.lobby_id &&
      probe.authority_commit_seq == committed.commit_seq &&
      probe.manager_id != 0 &&
      committed.manager_id != 0 &&
      committed.native_manager != nullptr &&
      committed.local_steam_id ==
          g_nrsc_steam_control_state.local_steam_id;
  const bool prior_same_expedition = previous.valid &&
      previous.master_lobby_id == committed.master_lobby_id &&
      previous.lobby_id == committed.lobby_id;
  const bool expedition_changed = previous.valid && !prior_same_expedition;
  uint32_t rebound = 0;
  uint32_t cleared = 0;
  bool restore_ticket_invalidated = false;
  bool restore_gate_invalidated = false;
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_hot_lock);
  for (BhrcFullPgdHotSnapshot& snapshot : g_bhrc_full_pgd_hot_snapshots) {
    if (!snapshot.valid) {
      continue;
    }
    if (snapshot.master_lobby_id != committed.master_lobby_id ||
        snapshot.expedition_lobby_id != committed.lobby_id) {
      std::memset(&snapshot, 0, sizeof(snapshot));
      ++cleared;
    } else if (committed.local_steam_id == committed.owner_steam_id &&
               snapshot.master_lobby_id == committed.master_lobby_id &&
               snapshot.expedition_lobby_id == committed.lobby_id) {
      snapshot.authority_commit_seq = committed.commit_seq;
      snapshot.publish_pending = true;
      ++rebound;
    }
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_hot_lock);
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  const bool ticket_matches_committed =
      probe_matches_committed &&
      BhrcFullPgdRestoreTicketMatchesProbe(
          g_bhrc_full_pgd_restore_ticket, probe) &&
      g_bhrc_full_pgd_restore_ticket.owner_steam_id ==
          committed.local_steam_id &&
      g_bhrc_full_pgd_restore_ticket.host_steam_id ==
          committed.owner_steam_id &&
      g_bhrc_full_pgd_restore_ticket.master_lobby_id ==
          committed.master_lobby_id &&
      g_bhrc_full_pgd_restore_ticket.expedition_lobby_id ==
          committed.lobby_id &&
      g_bhrc_full_pgd_restore_ticket.authority_commit_seq ==
          committed.commit_seq &&
      (g_bhrc_full_pgd_restore_ticket.local_manager_id == 0 ||
       g_bhrc_full_pgd_restore_ticket.local_manager_id ==
           committed.manager_id) &&
      (g_bhrc_full_pgd_restore_ticket.native_manager == nullptr ||
       g_bhrc_full_pgd_restore_ticket.native_manager ==
           committed.native_manager);
  if (g_bhrc_full_pgd_restore_ticket.valid &&
      !ticket_matches_committed) {
    restore_ticket_invalidated = true;
    if (g_bhrc_full_pgd_restore_ticket.applying) {
      g_bhrc_full_pgd_restore_ticket.cancel_pending = true;
    } else {
      g_bhrc_full_pgd_restore_ticket = BhrcFullPgdRestoreTicket{};
      std::memset(
          g_bhrc_full_pgd_restore_payload, 0,
          sizeof(g_bhrc_full_pgd_restore_payload));
    }
  } else if (ticket_matches_committed) {
    g_bhrc_full_pgd_restore_ticket.local_manager_id =
        committed.manager_id;
    g_bhrc_full_pgd_restore_ticket.native_manager =
        committed.native_manager;
  }
  const bool gate_matches_committed =
      probe_matches_committed &&
      BhrcFullPgdRestoreGateMatchesProbe(
          g_bhrc_full_pgd_restore_gate, probe, committed) &&
      g_bhrc_full_pgd_restore_gate.local_steam_id ==
          committed.local_steam_id &&
      g_bhrc_full_pgd_restore_gate.host_steam_id ==
          committed.owner_steam_id &&
      g_bhrc_full_pgd_restore_gate.master_lobby_id ==
          committed.master_lobby_id &&
      g_bhrc_full_pgd_restore_gate.expedition_lobby_id ==
          committed.lobby_id &&
      g_bhrc_full_pgd_restore_gate.authority_commit_seq ==
          committed.commit_seq &&
      (g_bhrc_full_pgd_restore_gate.local_manager_id == 0 ||
       g_bhrc_full_pgd_restore_gate.local_manager_id ==
           committed.manager_id) &&
      (g_bhrc_full_pgd_restore_gate.native_manager == nullptr ||
       g_bhrc_full_pgd_restore_gate.native_manager ==
           committed.native_manager);
  if (g_bhrc_full_pgd_restore_gate.valid && !gate_matches_committed) {
    g_bhrc_full_pgd_restore_gate = BhrcFullPgdRestoreGate{};
    restore_gate_invalidated = true;
  } else if (gate_matches_committed) {
    g_bhrc_full_pgd_restore_gate.local_manager_id =
        committed.manager_id;
    g_bhrc_full_pgd_restore_gate.native_manager =
        committed.native_manager;
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  if (restore_gate_invalidated &&
      committed.local_steam_id != committed.owner_steam_id &&
      probe_matches_committed) {
    ArmBhrcFullPgdRestoreGate(probe);
  }
  if (expedition_changed) {
    AcquireSRWLockExclusive(&g_bhrc_full_pgd_authority_receipt_lock);
    g_bhrc_full_pgd_authority_receipt = BhrcFullPgdAuthorityReceipt{};
    ReleaseSRWLockExclusive(&g_bhrc_full_pgd_authority_receipt_lock);
    if (!ticket_matches_committed) {
      ClearBhrcFullPgdAdmissionTransport(
          "native_expedition_generation_changed");
    }
  } else if (committed.local_steam_id == committed.owner_steam_id) {
    PublishBhrcFullPgdAuthorityReceipt(
        committed.master_lobby_id, committed.lobby_id,
        committed.owner_steam_id, committed.commit_seq);
  }
  Log(
      "BHRC full_pgd_authority_reconcile priorValid=%d masterA=%016llx expeditionB=%016llx authoritySeq=%llu sourceManagerId=%08x localManagerId=%08x localHost=%d rebound=%u cleared=%u sameExpedition=%d restoreTicketInvalidated=%d restoreGateInvalidated=%d hotOnly=1 coldStorage=0",
      previous.valid ? 1 : 0,
      static_cast<unsigned long long>(committed.master_lobby_id),
      static_cast<unsigned long long>(committed.lobby_id),
      static_cast<unsigned long long>(committed.commit_seq),
      probe_matches_committed ? probe.manager_id : 0,
      committed.manager_id,
      committed.local_steam_id == committed.owner_steam_id ? 1 : 0,
      rebound, cleared, prior_same_expedition ? 1 : 0,
      restore_ticket_invalidated ? 1 : 0,
      restore_gate_invalidated ? 1 : 0);
}


// 7a66e71 src/dllmain.cpp:12881
bool BhrcFullPgdAdmissionAttemptIdentityMatches(
    const BhrcHostAdmissionAttempt& lhs,
    const BhrcHostAdmissionAttempt& rhs) {
  return lhs.valid && rhs.valid &&
      lhs.reservation_serial == rhs.reservation_serial &&
      lhs.steam_id == rhs.steam_id &&
      lhs.record_key == rhs.record_key &&
      lhs.master_lobby_id == rhs.master_lobby_id &&
      lhs.expedition_lobby_id == rhs.expedition_lobby_id &&
      lhs.authority_commit_seq == rhs.authority_commit_seq &&
      lhs.manager_id == rhs.manager_id &&
      lhs.request_nonce == rhs.request_nonce &&
      lhs.client_generation == rhs.client_generation &&
      lhs.identity_hash32 == rhs.identity_hash32 &&
      lhs.trigger == rhs.trigger &&
      lhs.membership == rhs.membership;
}


// 7a66e71 src/dllmain.cpp:12899
bool BhrcFullPgdPinnedRestoreMatchesAttempt(
    const BhrcFullPgdPinnedRestore& pinned,
    const BhrcHostAdmissionAttempt& attempt,
    bool require_reservation_serial) {
  return pinned.valid && pinned.payload != nullptr &&
      (!require_reservation_serial ||
       pinned.reservation_serial == attempt.reservation_serial) &&
      pinned.steam_id == attempt.steam_id &&
      pinned.client_generation == attempt.client_generation &&
      pinned.key.owner_steam_id == attempt.steam_id &&
      pinned.key.master_lobby_id == attempt.master_lobby_id &&
      pinned.key.expedition_lobby_id == attempt.expedition_lobby_id &&
      pinned.key.authority_commit_seq == attempt.authority_commit_seq &&
      (attempt.full_pgd_codec_version == 0 ||
       pinned.key.codec_version == attempt.full_pgd_codec_version) &&
      (attempt.full_pgd_snapshot_revision == 0 ||
       pinned.key.snapshot_revision ==
           attempt.full_pgd_snapshot_revision) &&
      (attempt.full_pgd_payload_size == 0 ||
       pinned.key.payload_size == attempt.full_pgd_payload_size) &&
      (attempt.full_pgd_snapshot_hash32 == 0 ||
       pinned.key.payload_hash32 ==
           attempt.full_pgd_snapshot_hash32);
}


// 7a66e71 src/dllmain.cpp:12924
void ResetBhrcFullPgdPinnedRestoreLocked(
    BhrcFullPgdPinnedRestore* pinned) {
  if (pinned == nullptr) {
    return;
  }
  if (pinned->payload != nullptr) {
    HeapFree(GetProcessHeap(), 0, pinned->payload);
  }
  *pinned = BhrcFullPgdPinnedRestore{};
}


// 7a66e71 src/dllmain.cpp:12935
void ClearBhrcFullPgdPinnedRestoreForSerial(uint64_t reservation_serial) {
  if (reservation_serial == 0) {
    return;
  }
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_pinned_restore_lock);
  for (BhrcFullPgdPinnedRestore& pinned :
       g_bhrc_full_pgd_pinned_restores) {
    if (pinned.valid &&
        pinned.reservation_serial == reservation_serial) {
      ResetBhrcFullPgdPinnedRestoreLocked(&pinned);
    }
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_pinned_restore_lock);
}


