// 7a66e71 src/dllmain.cpp:12973
bool CopyBhrcFullPgdPinnedRestoreForAttempt(
    const BhrcHostAdmissionAttempt& attempt,
    BhrcFullPgdSnapshotKey* out_key,
    uint8_t** out_payload) {
  if (out_key != nullptr) {
    *out_key = BhrcFullPgdSnapshotKey{};
  }
  if (out_payload != nullptr) {
    *out_payload = nullptr;
  }
  if (!attempt.valid || attempt.reservation_serial == 0 ||
      out_key == nullptr || out_payload == nullptr) {
    return false;
  }
  BhrcFullPgdSnapshotKey key{};
  uint8_t* copy = nullptr;
  AcquireSRWLockShared(&g_bhrc_full_pgd_pinned_restore_lock);
  for (const BhrcFullPgdPinnedRestore& pinned :
       g_bhrc_full_pgd_pinned_restores) {
    if (!BhrcFullPgdPinnedRestoreMatchesAttempt(
            pinned, attempt, true) ||
        pinned.request_nonce != attempt.request_nonce ||
        pinned.key.payload_size < kBhrcFullPgdMinPayloadSize ||
        pinned.key.payload_size > kBhrcFullPgdMaxPayloadSize) {
      continue;
    }
    copy = static_cast<uint8_t*>(HeapAlloc(
        GetProcessHeap(), 0, pinned.key.payload_size));
    if (copy != nullptr) {
      key = pinned.key;
      std::memcpy(copy, pinned.payload, key.payload_size);
    }
    break;
  }
  ReleaseSRWLockShared(&g_bhrc_full_pgd_pinned_restore_lock);
  if (copy == nullptr ||
      BhrcFnv1a32(copy, key.payload_size) != key.payload_hash32) {
    if (copy != nullptr) {
      HeapFree(GetProcessHeap(), 0, copy);
    }
    return false;
  }
  *out_key = key;
  *out_payload = copy;
  return true;
}


// 7a66e71 src/dllmain.cpp:13020
bool PinBhrcFullPgdRestoreSnapshotForAttempt(
    const BhrcHostAdmissionAttempt& attempt,
    BhrcFullPgdSnapshotKey* out_requested) {
  if (out_requested != nullptr) {
    *out_requested = BhrcFullPgdSnapshotKey{};
  }
  if (!attempt.valid || attempt.reservation_serial == 0 ||
      attempt.membership != BhrcExpeditionMembership::ReturningSameB ||
      attempt.steam_id == 0 ||
      attempt.expires_tick_ms <= GetTickCount64() ||
      out_requested == nullptr) {
    return false;
  }

  BhrcHostAdmissionAttempt current_attempt{};
  AcquireSRWLockShared(&g_bhrc_host_admission_lock);
  for (const BhrcHostAdmissionAttempt& current :
       g_bhrc_host_admission_attempts) {
    if (BhrcFullPgdAdmissionAttemptIdentityMatches(current, attempt)) {
      current_attempt = current;
      break;
    }
  }
  ReleaseSRWLockShared(&g_bhrc_host_admission_lock);
  if (!current_attempt.valid) {
    return false;
  }
  if (current_attempt.expires_tick_ms <= GetTickCount64()) {
    return false;
  }

  AcquireSRWLockShared(&g_bhrc_full_pgd_pinned_restore_lock);
  for (const BhrcFullPgdPinnedRestore& pinned :
       g_bhrc_full_pgd_pinned_restores) {
    if (BhrcFullPgdPinnedRestoreMatchesAttempt(
            pinned, current_attempt, true) &&
        pinned.request_nonce == current_attempt.request_nonce) {
      *out_requested = pinned.key;
      ReleaseSRWLockShared(&g_bhrc_full_pgd_pinned_restore_lock);
      return true;
    }
  }
  ReleaseSRWLockShared(&g_bhrc_full_pgd_pinned_restore_lock);

  BhrcFullPgdSnapshotKey candidate_key{};
  uint8_t* candidate_payload = nullptr;
  if (current_attempt.full_pgd_snapshot_revision != 0) {
    AcquireSRWLockShared(&g_bhrc_full_pgd_pinned_restore_lock);
    for (const BhrcFullPgdPinnedRestore& pinned :
         g_bhrc_full_pgd_pinned_restores) {
      if (!BhrcFullPgdPinnedRestoreMatchesAttempt(
              pinned, current_attempt, false) ||
          pinned.key.codec_version !=
              current_attempt.full_pgd_codec_version ||
          pinned.key.snapshot_revision !=
              current_attempt.full_pgd_snapshot_revision ||
          pinned.key.payload_size !=
              current_attempt.full_pgd_payload_size ||
          pinned.key.payload_hash32 !=
              current_attempt.full_pgd_snapshot_hash32) {
        continue;
      }
      candidate_payload = static_cast<uint8_t*>(HeapAlloc(
          GetProcessHeap(), 0, pinned.key.payload_size));
      if (candidate_payload != nullptr) {
        candidate_key = pinned.key;
        std::memcpy(
            candidate_payload, pinned.payload, pinned.key.payload_size);
      }
      break;
    }
    ReleaseSRWLockShared(&g_bhrc_full_pgd_pinned_restore_lock);
  }
  if (candidate_payload == nullptr) {
    BhrcFullPgdSnapshotKey requested{};
    requested.owner_steam_id = current_attempt.steam_id;
    requested.master_lobby_id = current_attempt.master_lobby_id;
    requested.expedition_lobby_id =
        current_attempt.expedition_lobby_id;
    requested.authority_commit_seq =
        current_attempt.authority_commit_seq;
    requested.codec_version =
        current_attempt.full_pgd_codec_version;
    requested.snapshot_revision =
        current_attempt.full_pgd_snapshot_revision;
    requested.payload_size =
        current_attempt.full_pgd_payload_size;
    requested.payload_hash32 =
        current_attempt.full_pgd_snapshot_hash32;
    if (!CopyBhrcFullPgdHotSnapshot(
            requested, &candidate_key, &candidate_payload)) {
      return false;
    }
  }
  if (BhrcFnv1a32(candidate_payload, candidate_key.payload_size) !=
      candidate_key.payload_hash32) {
    HeapFree(GetProcessHeap(), 0, candidate_payload);
    return false;
  }

  bool installed = false;
  AcquireSRWLockExclusive(&g_bhrc_host_admission_lock);
  BhrcHostAdmissionAttempt* live_attempt = nullptr;
  for (BhrcHostAdmissionAttempt& current :
       g_bhrc_host_admission_attempts) {
    if (BhrcFullPgdAdmissionAttemptIdentityMatches(
            current, current_attempt)) {
      live_attempt = &current;
      break;
    }
  }
  if (live_attempt != nullptr &&
      live_attempt->expires_tick_ms > GetTickCount64() &&
      (live_attempt->full_pgd_snapshot_revision == 0 ||
       (live_attempt->full_pgd_codec_version ==
            candidate_key.codec_version &&
        live_attempt->full_pgd_snapshot_revision ==
            candidate_key.snapshot_revision &&
        live_attempt->full_pgd_payload_size ==
            candidate_key.payload_size &&
        live_attempt->full_pgd_snapshot_hash32 ==
            candidate_key.payload_hash32))) {
    AcquireSRWLockExclusive(&g_bhrc_full_pgd_pinned_restore_lock);
    BhrcFullPgdPinnedRestore* target = nullptr;
    for (BhrcFullPgdPinnedRestore& pinned :
         g_bhrc_full_pgd_pinned_restores) {
      if (BhrcFullPgdPinnedRestoreMatchesAttempt(
              pinned, *live_attempt, true) &&
          pinned.request_nonce == live_attempt->request_nonce) {
        target = &pinned;
        break;
      }
      if (!pinned.valid && target == nullptr) {
        target = &pinned;
      }
    }
    if (target != nullptr) {
      ResetBhrcFullPgdPinnedRestoreLocked(target);
      target->valid = true;
      target->reservation_serial =
          live_attempt->reservation_serial;
      target->steam_id = live_attempt->steam_id;
      target->request_nonce = live_attempt->request_nonce;
      target->client_generation =
          live_attempt->client_generation;
      target->key = candidate_key;
      target->payload = candidate_payload;
      candidate_payload = nullptr;
      live_attempt->full_pgd_codec_version =
          candidate_key.codec_version;
      live_attempt->full_pgd_snapshot_revision =
          candidate_key.snapshot_revision;
      live_attempt->full_pgd_payload_size =
          candidate_key.payload_size;
      live_attempt->full_pgd_snapshot_hash32 =
          candidate_key.payload_hash32;
      installed = true;
    }
    ReleaseSRWLockExclusive(&g_bhrc_full_pgd_pinned_restore_lock);
  }
  ReleaseSRWLockExclusive(&g_bhrc_host_admission_lock);
  if (candidate_payload != nullptr) {
    HeapFree(GetProcessHeap(), 0, candidate_payload);
  }
  if (!installed) {
    return false;
  }
  *out_requested = candidate_key;
  Log(
      "BHRC full_pgd_restore_pin owner=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu nonce=%08x clientGeneration=%u codecVersion=%u revision=%llu size=%u hash=%08x immutableAttemptPayload=1 coldStorage=0",
      static_cast<unsigned long long>(current_attempt.steam_id),
      static_cast<unsigned long long>(current_attempt.master_lobby_id),
      static_cast<unsigned long long>(
          current_attempt.expedition_lobby_id),
      static_cast<unsigned long long>(
          current_attempt.authority_commit_seq),
      current_attempt.request_nonce, current_attempt.client_generation,
      candidate_key.codec_version,
      static_cast<unsigned long long>(candidate_key.snapshot_revision),
      candidate_key.payload_size, candidate_key.payload_hash32);
  return true;
}


// 7a66e71 src/dllmain.cpp:13203
bool SendBhrcFullPgdRestoreToAttempt(
    const BhrcHostAdmissionAttempt& attempt,
    const char* reason) {
  if (!attempt.valid ||
      attempt.membership != BhrcExpeditionMembership::ReturningSameB ||
      attempt.steam_id == 0 || attempt.request_nonce == 0 ||
      attempt.expires_tick_ms <= GetTickCount64()) {
    return false;
  }
  BhrcFullPgdSnapshotKey pinned_key{};
  if (!PinBhrcFullPgdRestoreSnapshotForAttempt(
          attempt, &pinned_key)) {
    return false;
  }
  BhrcHostAdmissionAttempt pinned_attempt = attempt;
  pinned_attempt.full_pgd_codec_version = pinned_key.codec_version;
  pinned_attempt.full_pgd_snapshot_revision =
      pinned_key.snapshot_revision;
  pinned_attempt.full_pgd_payload_size = pinned_key.payload_size;
  pinned_attempt.full_pgd_snapshot_hash32 =
      pinned_key.payload_hash32;
  uint8_t* payload = nullptr;
  BhrcFullPgdSnapshotKey copied_key{};
  if (!CopyBhrcFullPgdPinnedRestoreForAttempt(
          pinned_attempt, &copied_key, &payload)) {
    return false;
  }
  const bool ok = SendBhrcFullPgdPayload(
      attempt.steam_id, copied_key, payload,
      BhrcFullPgdTransferPurpose::RestoreDelivery,
      attempt.request_nonce, attempt.client_generation, reason,
      &pinned_attempt);
  HeapFree(GetProcessHeap(), 0, payload);
  if (ok) {
    AcquireSRWLockExclusive(&g_bhrc_host_admission_lock);
    for (BhrcHostAdmissionAttempt& current :
         g_bhrc_host_admission_attempts) {
      if (BhrcFullPgdAdmissionAttemptIdentityMatches(
              current, attempt) &&
          current.full_pgd_codec_version == copied_key.codec_version &&
          current.full_pgd_snapshot_revision ==
              copied_key.snapshot_revision &&
          current.full_pgd_payload_size == copied_key.payload_size &&
          current.full_pgd_snapshot_hash32 ==
              copied_key.payload_hash32) {
        current.last_full_pgd_send_tick_ms = GetTickCount64();
        current.full_pgd_restore_sent = true;
        break;
      }
    }
    ReleaseSRWLockExclusive(&g_bhrc_host_admission_lock);
  }
  return ok;
}


// 7a66e71 src/dllmain.cpp:13258
void AdvanceBhrcFullPgdHostRestoreDeliveries() {
  if (!IsLocalNrscHost()) {
    return;
  }
  const ULONGLONG now = GetTickCount64();
  BhrcHostAdmissionAttempt due[kBhrcHostAdmissionCapacity]{};
  uint32_t due_count = 0;
  AcquireSRWLockShared(&g_bhrc_host_admission_lock);
  for (const BhrcHostAdmissionAttempt& attempt :
       g_bhrc_host_admission_attempts) {
    if (attempt.valid &&
        attempt.membership == BhrcExpeditionMembership::ReturningSameB &&
        attempt.expires_tick_ms > now &&
        (attempt.consumed_event_mask & kBhrcNativeEventMask0c) == 0 &&
        (attempt.last_full_pgd_send_tick_ms == 0 ||
         now - attempt.last_full_pgd_send_tick_ms >=
             kBhrcFullPgdRestoreRetryMs) &&
        due_count < _countof(due)) {
      due[due_count++] = attempt;
    }
  }
  ReleaseSRWLockShared(&g_bhrc_host_admission_lock);
  for (uint32_t index = 0; index < due_count; ++index) {
    SendBhrcFullPgdRestoreToAttempt(
        due[index], "authorized_returning_full_pgd_retry");
  }
}


// 7a66e71 src/dllmain.cpp:13286
void AdvanceBhrcFullPgdTransport() {
  AdvanceBhrcFullPgdSnapshotPublication();
  AdvanceBhrcFullPgdHostRestoreDeliveries();
}


// 7a66e71 src/dllmain.cpp:13291
BhrcFullPgdHotSnapshot* FindBhrcFullPgdHotSnapshotLocked(
    uint64_t owner_steam_id,
    uint64_t master_lobby_id,
    uint64_t expedition_lobby_id,
    uint64_t authority_commit_seq) {
  for (BhrcFullPgdHotSnapshot& snapshot : g_bhrc_full_pgd_hot_snapshots) {
    if (snapshot.valid && snapshot.owner_steam_id == owner_steam_id &&
        snapshot.master_lobby_id == master_lobby_id &&
        snapshot.expedition_lobby_id == expedition_lobby_id &&
        snapshot.authority_commit_seq == authority_commit_seq) {
      return &snapshot;
    }
  }
  return nullptr;
}


// 7a66e71 src/dllmain.cpp:13307
bool StoreBhrcFullPgdHotSnapshot(
    uint64_t owner_steam_id,
    uint64_t master_lobby_id,
    uint64_t expedition_lobby_id,
    uint64_t authority_commit_seq,
    uint32_t codec_version,
    uint64_t requested_revision,
    const void* payload,
    uint32_t payload_size,
    uint32_t payload_hash32,
    bool publish_pending,
    const char* reason,
    BhrcFullPgdSnapshotKey* out_key,
    bool authoritative_replace) {
  if (out_key != nullptr) {
    *out_key = BhrcFullPgdSnapshotKey{};
  }
  if (owner_steam_id == 0 || master_lobby_id == 0 ||
      expedition_lobby_id == 0 || authority_commit_seq == 0 ||
      codec_version == 0 || payload == nullptr ||
      payload_hash32 == 0 ||
      !IsBhrcFullPgdPayloadShapeValid(
          payload_size,
          static_cast<uint16_t>(
              (payload_size + kBhrcFullPgdChunkPayloadSize - 1) /
              kBhrcFullPgdChunkPayloadSize)) ||
      BhrcFnv1a32(payload, payload_size) != payload_hash32) {
    return false;
  }

  bool changed = false;
  bool rejected_revision = false;
  const char* revision_reject_reason = "revision_rollback";
  BhrcFullPgdSnapshotKey stored{};
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_hot_lock);
  for (BhrcFullPgdHotSnapshot& candidate :
       g_bhrc_full_pgd_hot_snapshots) {
    if (candidate.valid && candidate.owner_steam_id == owner_steam_id &&
        candidate.master_lobby_id == master_lobby_id &&
        candidate.expedition_lobby_id == expedition_lobby_id &&
        candidate.authority_commit_seq != authority_commit_seq) {
      std::memset(&candidate, 0, sizeof(candidate));
    }
  }
  BhrcFullPgdHotSnapshot* target = FindBhrcFullPgdHotSnapshotLocked(
      owner_steam_id, master_lobby_id, expedition_lobby_id,
      authority_commit_seq);
  if (target == nullptr) {
    for (BhrcFullPgdHotSnapshot& candidate :
         g_bhrc_full_pgd_hot_snapshots) {
      if (!candidate.valid) {
        target = &candidate;
        break;
      }
    }
  }
  if (target == nullptr) {
    target = &g_bhrc_full_pgd_hot_snapshots[0];
    for (BhrcFullPgdHotSnapshot& candidate :
         g_bhrc_full_pgd_hot_snapshots) {
      if (candidate.updated_tick_ms < target->updated_tick_ms) {
        target = &candidate;
      }
    }
  }

  const bool exact_existing = target->valid &&
      target->owner_steam_id == owner_steam_id &&
      target->master_lobby_id == master_lobby_id &&
      target->expedition_lobby_id == expedition_lobby_id &&
      target->authority_commit_seq == authority_commit_seq;
  const bool same_revision_conflict = exact_existing &&
      requested_revision != 0 &&
      requested_revision == target->snapshot_revision &&
      (target->codec_version != codec_version ||
       target->payload_size != payload_size ||
       target->payload_hash32 != payload_hash32 ||
       std::memcmp(target->payload, payload, payload_size) != 0);
  if (!authoritative_replace && exact_existing &&
      requested_revision != 0 &&
      requested_revision < target->snapshot_revision) {
    rejected_revision = true;
  } else if (!authoritative_replace && same_revision_conflict) {
    rejected_revision = true;
    revision_reject_reason = "same_revision_payload_conflict";
  } else {
    const bool identical = exact_existing &&
        target->codec_version == codec_version &&
        target->payload_size == payload_size &&
        target->payload_hash32 == payload_hash32 &&
        std::memcmp(target->payload, payload, payload_size) == 0;
    if (authoritative_replace || !identical ||
        (requested_revision != 0 && exact_existing &&
         requested_revision > target->snapshot_revision)) {
      uint64_t revision = requested_revision;
      if (revision == 0) {
        revision = exact_existing ? target->snapshot_revision + 1 : 1;
        if (revision == 0) {
          revision = 1;
        }
      }
      std::memset(target, 0, sizeof(*target));
      target->valid = true;
      target->publish_pending = publish_pending;
      target->updated_tick_ms = GetTickCount64();
      target->owner_steam_id = owner_steam_id;
      target->master_lobby_id = master_lobby_id;
      target->expedition_lobby_id = expedition_lobby_id;
      target->authority_commit_seq = authority_commit_seq;
      target->codec_version = codec_version;
      target->snapshot_revision = revision;
      target->payload_size = payload_size;
      target->payload_hash32 = payload_hash32;
      std::memcpy(target->payload, payload, payload_size);
      changed = true;
    }
    if (target->valid) {
      stored.owner_steam_id = target->owner_steam_id;
      stored.master_lobby_id = target->master_lobby_id;
      stored.expedition_lobby_id = target->expedition_lobby_id;
      stored.authority_commit_seq = target->authority_commit_seq;
      stored.codec_version = target->codec_version;
      stored.snapshot_revision = target->snapshot_revision;
      stored.payload_size = target->payload_size;
      stored.payload_hash32 = target->payload_hash32;
    }
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_hot_lock);

  if (rejected_revision) {
    LogWarn(
        "BHRC full_pgd_hot_store outcome=rejected reason=%s requestReason=%s owner=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu revision=%llu size=%u hash=%08x coldStorage=0",
        revision_reject_reason,
        reason != nullptr ? reason : "unknown",
        static_cast<unsigned long long>(owner_steam_id),
        static_cast<unsigned long long>(master_lobby_id),
        static_cast<unsigned long long>(expedition_lobby_id),
        static_cast<unsigned long long>(authority_commit_seq),
        static_cast<unsigned long long>(requested_revision), payload_size,
        payload_hash32);
    return false;
  }
  if (out_key != nullptr) {
    *out_key = stored;
  }
  if (changed) {
    Log(
        "BHRC full_pgd_hot_store outcome=stored reason=%s owner=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu codecVersion=%u revision=%llu size=%u hash=%08x publishPending=%d coldStorage=0 nativeCodec=1",
        reason != nullptr ? reason : "unknown",
        static_cast<unsigned long long>(stored.owner_steam_id),
        static_cast<unsigned long long>(stored.master_lobby_id),
        static_cast<unsigned long long>(stored.expedition_lobby_id),
        static_cast<unsigned long long>(stored.authority_commit_seq),
        stored.codec_version,
        static_cast<unsigned long long>(stored.snapshot_revision),
        stored.payload_size, stored.payload_hash32,
        publish_pending ? 1 : 0);
  }
  return stored.owner_steam_id != 0;
}


// 7a66e71 src/dllmain.cpp:13468
bool HasExactBhrcFullPgdHotSnapshot(
    uint64_t owner_steam_id,
    const BhrcNativeExpeditionAuthorityState& authority) {
  if (owner_steam_id == 0 || !authority.valid ||
      authority.master_lobby_id == 0 || authority.lobby_id == 0 ||
      authority.commit_seq == 0) {
    return false;
  }
  bool found = false;
  AcquireSRWLockShared(&g_bhrc_full_pgd_hot_lock);
  const BhrcFullPgdHotSnapshot* snapshot =
      FindBhrcFullPgdHotSnapshotLocked(
          owner_steam_id, authority.master_lobby_id, authority.lobby_id,
          authority.commit_seq);
  found = snapshot != nullptr && snapshot->codec_version != 0 &&
      snapshot->payload_hash32 != 0 &&
      snapshot->payload_size >= kBhrcFullPgdMinPayloadSize;
  ReleaseSRWLockShared(&g_bhrc_full_pgd_hot_lock);
  return found;
}


// 7a66e71 src/dllmain.cpp:13489
bool CopyBhrcFullPgdHotSnapshot(
    const BhrcFullPgdSnapshotKey& requested,
    BhrcFullPgdSnapshotKey* out_key,
    uint8_t** out_payload) {
  if (out_key != nullptr) {
    *out_key = BhrcFullPgdSnapshotKey{};
  }
  if (out_payload != nullptr) {
    *out_payload = nullptr;
  }
  if (requested.owner_steam_id == 0 || out_key == nullptr ||
      out_payload == nullptr) {
    return false;
  }
  uint8_t* copy = nullptr;
  BhrcFullPgdSnapshotKey key{};
  AcquireSRWLockShared(&g_bhrc_full_pgd_hot_lock);
  const BhrcFullPgdHotSnapshot* snapshot =
      FindBhrcFullPgdHotSnapshotLocked(
          requested.owner_steam_id, requested.master_lobby_id,
          requested.expedition_lobby_id,
          requested.authority_commit_seq);
  if (snapshot != nullptr &&
      (requested.codec_version == 0 ||
       requested.codec_version == snapshot->codec_version) &&
      (requested.snapshot_revision == 0 ||
       requested.snapshot_revision == snapshot->snapshot_revision) &&
      (requested.payload_size == 0 ||
       requested.payload_size == snapshot->payload_size) &&
      (requested.payload_hash32 == 0 ||
       requested.payload_hash32 == snapshot->payload_hash32) &&
      snapshot->payload_size >= kBhrcFullPgdMinPayloadSize &&
      snapshot->payload_size <= kBhrcFullPgdMaxPayloadSize) {
    copy = static_cast<uint8_t*>(HeapAlloc(
        GetProcessHeap(), 0, snapshot->payload_size));
    if (copy != nullptr) {
      std::memcpy(copy, snapshot->payload, snapshot->payload_size);
      key.owner_steam_id = snapshot->owner_steam_id;
      key.master_lobby_id = snapshot->master_lobby_id;
      key.expedition_lobby_id = snapshot->expedition_lobby_id;
      key.authority_commit_seq = snapshot->authority_commit_seq;
      key.codec_version = snapshot->codec_version;
      key.snapshot_revision = snapshot->snapshot_revision;
      key.payload_size = snapshot->payload_size;
      key.payload_hash32 = snapshot->payload_hash32;
    }
  }
  ReleaseSRWLockShared(&g_bhrc_full_pgd_hot_lock);
  if (copy == nullptr) {
    return false;
  }
  *out_key = key;
  *out_payload = copy;
  return true;
}


// 7a66e71 src/dllmain.cpp:13545
bool SerializeBhrcLocalFullPgd(
    void* player_game_data,
    uint32_t* out_codec_version,
    uint32_t* out_payload_size,
    uint32_t* out_payload_hash32) {
  if (out_codec_version != nullptr) {
    *out_codec_version = 0;
  }
  if (out_payload_size != nullptr) {
    *out_payload_size = 0;
  }
  if (out_payload_hash32 != nullptr) {
    *out_payload_hash32 = 0;
  }
  if (player_game_data == nullptr || g_player_game_data_full_serialize == nullptr ||
      g_player_game_data_codec_version == nullptr ||
      g_native_write_stream_init == nullptr ||
      g_native_write_stream_remaining == nullptr ||
      g_native_write_stream_capacity == nullptr ||
      g_native_write_stream_destroy == nullptr) {
    return false;
  }

  TraceBhrcSavedEffectSerializeInput(player_game_data);
  std::memset(g_bhrc_full_pgd_writer_stream, 0,
              sizeof(g_bhrc_full_pgd_writer_stream));
  uint32_t codec_version = 0;
  uint64_t remaining = 0;
  uint64_t capacity = 0;
  bool initialized = false;
  bool serialized = false;
  __try {
    codec_version = g_player_game_data_codec_version();
    g_native_write_stream_init(
        g_bhrc_full_pgd_writer_stream, g_bhrc_full_pgd_capture_scratch,
        kBhrcFullPgdMaxPayloadSize);
    initialized = true;
    serialized = g_player_game_data_full_serialize(
                     player_game_data, g_bhrc_full_pgd_writer_stream) != 0;
    remaining =
        g_native_write_stream_remaining(g_bhrc_full_pgd_writer_stream);
    capacity =
        g_native_write_stream_capacity(g_bhrc_full_pgd_writer_stream);
  } __except (LogSehException(
      "BHRC full PlayerGameData serialize", GetExceptionInformation())) {
    serialized = false;
  }
  if (initialized) {
    __try {
      g_native_write_stream_destroy(g_bhrc_full_pgd_writer_stream);
    } __except (LogSehException(
        "BHRC full PlayerGameData writer destroy", GetExceptionInformation())) {
      serialized = false;
    }
  }

  // Native FUN_14217b410/FUN_14217b4d0 return byte metrics, not memory
  // cursors. Original FUN_1406b97d0 calculates used bytes as
  // capacity - remaining; the payload always begins at the caller buffer.
  if (!serialized || codec_version == 0 ||
      capacity != kBhrcFullPgdMaxPayloadSize || remaining > capacity) {
    return false;
  }
  const uint64_t size64 = capacity - remaining;
  if (size64 < kBhrcFullPgdMinPayloadSize ||
      size64 > kBhrcFullPgdMaxPayloadSize) {
    return false;
  }
  const uint32_t size = static_cast<uint32_t>(size64);
  const uint32_t hash =
      BhrcFnv1a32(g_bhrc_full_pgd_capture_scratch, size);
  if (hash == 0) {
    return false;
  }
  if (out_codec_version != nullptr) {
    *out_codec_version = codec_version;
  }
  if (out_payload_size != nullptr) {
    *out_payload_size = size;
  }
  if (out_payload_hash32 != nullptr) {
    *out_payload_hash32 = hash;
  }
  return true;
}


// 7a66e71 src/dllmain.cpp:13641
LARGE_INTEGER BeginBhrcTemporaryFullPgdProfile() {
  LARGE_INTEGER start{};
  QueryPerformanceCounter(&start);
  return start;
}


// 7a66e71 src/dllmain.cpp:13647
void FinishBhrcTemporaryFullPgdProfile(LARGE_INTEGER start) {
  LARGE_INTEGER finish{};
  QueryPerformanceCounter(&finish);
  if (g_bhrc_temporary_full_pgd_profiler.frequency.QuadPart == 0 &&
      !QueryPerformanceFrequency(
          &g_bhrc_temporary_full_pgd_profiler.frequency)) {
    return;
  }
  if (finish.QuadPart < start.QuadPart) {
    return;
  }
  g_bhrc_temporary_full_pgd_profiler.total_ticks +=
      static_cast<uint64_t>(finish.QuadPart - start.QuadPart);
  ++g_bhrc_temporary_full_pgd_profiler.sample_count;
  if (g_bhrc_temporary_full_pgd_profiler.sample_count < 10) {
    return;
  }

  const double total_ms =
      static_cast<double>(g_bhrc_temporary_full_pgd_profiler.total_ticks) *
      1000.0 /
      static_cast<double>(
          g_bhrc_temporary_full_pgd_profiler.frequency.QuadPart);
  Log(
      "BHRC full_pgd_serialize_profiler samples=10 totalMs=%.3f averageMs=%.3f scope=native_serialize_hash_validate_compare_store temporary=1",
      total_ms, total_ms / 10.0);
  g_bhrc_temporary_full_pgd_profiler.total_ticks = 0;
  g_bhrc_temporary_full_pgd_profiler.sample_count = 0;
}


// 7a66e71 src/dllmain.cpp:13678
void TraceBhrcPgdCaptureState(const char* state,
    const BhrcNativeExpeditionAuthorityState& authority, void* pgd = nullptr,
    const BhrcFullPgdSnapshotKey* key = nullptr) {
  const ULONGLONG now = GetTickCount64();
  static const char* last_state = nullptr;
  static ULONGLONG last_ms = 0;
  static volatile LONG count = 0;
  if (last_state == state && now - last_ms < kNr6pfAliveHeartbeatIntervalMs) return;
  last_state = state;
  last_ms = now;
  LONG seq = 0;
  if (!BhrcDiagnosticBudget(&count, 256, "pgd_capture_state", &seq)) return;
  Log("BHRC_PGD_CAPTURE seq=%ld state=%s local=%016llx host=%016llx currentA=%016llx expectedA=%016llx expeditionB=%016llx authorityValid=%d authoritySeq=%llu manager=%p pgd=%p level=%d heldRune=%d revision=%llu hash=%08x sampleTick=%llu behaviorMutation=0",
      seq, state, static_cast<unsigned long long>(g_nrsc_steam_control_state.local_steam_id),
      static_cast<unsigned long long>(g_nrsc_steam_control_state.owner_steam_id),
      static_cast<unsigned long long>(GetCurrentNrscMasterLobbyId()),
      static_cast<unsigned long long>(authority.master_lobby_id),
      static_cast<unsigned long long>(authority.lobby_id), authority.valid,
      static_cast<unsigned long long>(authority.commit_seq), authority.native_manager, pgd,
      ReadI32(pgd != nullptr ? static_cast<const uint8_t*>(pgd) + 0x68 : nullptr, -1),
      ReadI32(pgd != nullptr ? static_cast<const uint8_t*>(pgd) + 0x6c : nullptr, -1),
      static_cast<unsigned long long>(key != nullptr ? key->snapshot_revision : 0),
      key != nullptr ? key->payload_hash32 : 0, static_cast<unsigned long long>(now));
}

void CaptureBhrcLocalFullPgdMainThread() {
  const DWORD now = GetTickCount();
  if (g_bhrc_full_pgd_last_capture_ms != 0 &&
      now - g_bhrc_full_pgd_last_capture_ms <
          kBhrcFullPgdCaptureIntervalMs) {
    return;
  }
  g_bhrc_full_pgd_last_capture_ms = now;

  const BhrcNativeExpeditionAuthorityState authority =
      SnapshotNativeExpeditionAuthority();
  const uint64_t local = g_nrsc_steam_control_state.local_steam_id;
  const uint64_t owner = g_nrsc_steam_control_state.owner_steam_id;
  if (!authority.valid || local == 0 || owner == 0 ||
      authority.local_steam_id != local || authority.owner_steam_id != owner ||
      authority.master_lobby_id == 0 || authority.lobby_id == 0 ||
      authority.master_lobby_id != GetCurrentNrscMasterLobbyId() ||
      ReadGameGlobalPtr(kWorldChrManPtrRva) == nullptr) {
    TraceBhrcPgdCaptureState("blocked_authority_or_transport", authority);
    return;
  }

  if (local != owner) {
    if (IsBhrcFullPgdCaptureFrozen(authority, local, owner)) {
      TraceBhrcPgdCaptureState("blocked_restore_gate", authority);
      return;
    }
    const BhrcExpeditionProbeAttempt probe = SnapshotBhrcExpeditionProbe();
    void* const current_pgd = BhrcEffectLocalPgd();
    AcquireSRWLockShared(&g_bhrc_full_pgd_restore_lock);
    // A later normal actor respawn must not freeze publication again. The
    // restored local PGD allocation and its B manager, not an old WorldChr
    // registration counter, own completion of this data copy.
    const bool final_copy_live = current_pgd != nullptr &&
        BhrcFullPgdRestoreGateMatchesProbe(g_bhrc_full_pgd_restore_gate, probe, authority) &&
        static_cast<uint8_t>(g_bhrc_full_pgd_restore_gate.stage) >=
            static_cast<uint8_t>(BhrcFullPgdRestoreGateStage::FinalApplied) &&
        g_bhrc_full_pgd_restore_gate.final_player_game_data == current_pgd;
    ReleaseSRWLockShared(&g_bhrc_full_pgd_restore_lock);
    const bool returning_restore_pending =
        IsBhrcAuthorizedClientProbe(probe) &&
        !probe.full_pgd_restore_expired && !probe.full_pgd_restore_finished &&
        probe.membership == BhrcExpeditionMembership::ReturningSameB &&
        probe.native_owner_ready && probe.host_steam_id == owner &&
        probe.master_lobby_id == authority.master_lobby_id &&
        probe.expedition_lobby_id == authority.lobby_id &&
        probe.authority_commit_seq == authority.commit_seq &&
        !final_copy_live;
    if (returning_restore_pending) {
      TraceBhrcPgdCaptureState("blocked_final_restore", authority);
      return;
    }
  }

  uint64_t authoritative_seq = 0;
  if (local == owner) {
    authoritative_seq = authority.commit_seq;
    PublishBhrcFullPgdAuthorityReceipt(
        authority.master_lobby_id, authority.lobby_id, owner,
        authoritative_seq);
  } else if (!SnapshotBhrcFullPgdAuthorityReceipt(
                 authority, &authoritative_seq)) {
    const BhrcExpeditionProbeAttempt probe = SnapshotBhrcExpeditionProbe();
    if (!IsBhrcAuthorizedClientProbe(probe) ||
        probe.host_steam_id != owner ||
        probe.master_lobby_id != authority.master_lobby_id ||
        probe.expedition_lobby_id != authority.lobby_id ||
        probe.authority_commit_seq == 0) {
      TraceBhrcPgdCaptureState("blocked_authority_receipt", authority);
      return;
    }
    authoritative_seq = probe.authority_commit_seq;
    PublishBhrcFullPgdAuthorityReceipt(
        authority.master_lobby_id, authority.lobby_id, owner,
        authoritative_seq);
  }
  if (authoritative_seq == 0) {
    TraceBhrcPgdCaptureState("blocked_authority_seq", authority);
    return;
  }

  void* session_mgr = ReadGameGlobalPtr(kNetModeManagerPtrRva);
  const uint8_t* local_record = session_mgr != nullptr
      ? FindSessionRecordByKey(session_mgr, local)
      : nullptr;
  void* player_game_data_manager = GetPlayerGameDataManager();
  void* local_pgd = player_game_data_manager != nullptr
      ? reinterpret_cast<void*>(ReadU64(
            static_cast<const uint8_t*>(player_game_data_manager) + 8, 0))
      : nullptr;
  if (local_record == nullptr || ReadU64(local_record + 0x10, 0) != local ||
      ReadU8(local_record + 0xe1, 0) != 1 || local_pgd == nullptr) {
    TraceBhrcPgdCaptureState("blocked_local_record", authority, local_pgd);
    return;
  }

  uint32_t codec_version = 0;
  uint32_t payload_size = 0;
  uint32_t payload_hash32 = 0;
  const bool trace_capture = BhrcEffectTraceActive() &&
      g_bhrc_effect_trace_window.final_tick_ms != 0 &&
      g_bhrc_effect_trace_window.pgd == local_pgd &&
      g_bhrc_effect_trace_window.capture_samples < 2;
  if (trace_capture) {
    ++g_bhrc_effect_trace_window.capture_samples;
    LogBhrcEffectSnapshot("before_periodic_serialize", local_pgd, -1);
  }
  // TEMP FULL PGD SERIALIZE PROFILER: begin.
  const LARGE_INTEGER temporary_profile_start =
      BeginBhrcTemporaryFullPgdProfile();
  if (!SerializeBhrcLocalFullPgd(
          local_pgd, &codec_version, &payload_size, &payload_hash32)) {
    LogWarn(
        "BHRC full_pgd_capture outcome=serialize_failed owner=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu pgd=%p nativeCodec=FUN_14020d210 coldStorage=0",
        static_cast<unsigned long long>(local),
        static_cast<unsigned long long>(authority.master_lobby_id),
        static_cast<unsigned long long>(authority.lobby_id),
        static_cast<unsigned long long>(authoritative_seq), local_pgd);
    return;
  }
  BhrcFullPgdSnapshotKey captured_key{};
  const bool stored = StoreBhrcFullPgdHotSnapshot(
      local, authority.master_lobby_id, authority.lobby_id,
      authoritative_seq, codec_version, 0,
      g_bhrc_full_pgd_capture_scratch, payload_size, payload_hash32, true,
      "native_full_pgd_periodic_capture", &captured_key);
  TraceBhrcPgdCaptureState(stored ? "captured" : "store_failed", authority,
                         local_pgd, &captured_key);
  if (trace_capture) {
    LogBhrcEffectSnapshot("after_periodic_serialize", local_pgd, -1);
  }
  if (stored) {
    // TEMP FULL PGD SERIALIZE PROFILER: finish.
    FinishBhrcTemporaryFullPgdProfile(temporary_profile_start);
  }
}


// 7a66e71 src/dllmain.cpp:13783
bool SendBhrcFullPgdPayload(
    uint64_t target_steam_id,
    const BhrcFullPgdSnapshotKey& key,
    const uint8_t* payload,
    BhrcFullPgdTransferPurpose purpose,
    uint32_t request_nonce,
    uint32_t client_generation,
    const char* reason,
    const BhrcHostAdmissionAttempt* admission_guard) {
  const bool trace_restore =
      purpose == BhrcFullPgdTransferPurpose::RestoreDelivery;
  static volatile LONG restore_send_trace_seq = 0;
  const LONG trace_seq = trace_restore
      ? InterlockedIncrement(&restore_send_trace_seq) : 0;
  if (target_steam_id == 0 || payload == nullptr ||
      key.owner_steam_id == 0 || key.master_lobby_id == 0 ||
      key.expedition_lobby_id == 0 ||
      key.authority_commit_seq == 0 || key.codec_version == 0 ||
      key.snapshot_revision == 0 || key.payload_hash32 == 0 ||
      key.payload_size < kBhrcFullPgdMinPayloadSize ||
      key.payload_size > kBhrcFullPgdMaxPayloadSize ||
      BhrcFnv1a32(payload, key.payload_size) != key.payload_hash32) {
    if (trace_restore) {
      Log("BHRC_PGD_TX_TRACE transfer seq=%ld outcome=failed failure=invalid_snapshot target=%016llx owner=%016llx nonce=%08x generation=%u revision=%llu size=%u hash=%08x submittedChunks=0 failedChunk=-1 rawSendInvoked=0 steamCalled=0 steamResultValid=0 behaviorMutation=0",
          trace_seq, static_cast<unsigned long long>(target_steam_id),
          static_cast<unsigned long long>(key.owner_steam_id), request_nonce,
          client_generation, static_cast<unsigned long long>(key.snapshot_revision),
          key.payload_size, key.payload_hash32);
    }
    return false;
  }
  const uint16_t chunk_count = static_cast<uint16_t>(
      (key.payload_size + kBhrcFullPgdChunkPayloadSize - 1) /
      kBhrcFullPgdChunkPayloadSize);
  auto* packet = static_cast<RevenantFixFullPgdChunkPacket*>(
      HeapAlloc(GetProcessHeap(), HEAP_ZERO_MEMORY,
                sizeof(RevenantFixFullPgdChunkPacket)));
  bool all_sent = packet != nullptr;
  uint16_t submitted_chunks = 0;
  int failed_chunk = -1;
  int lease_valid_trace = -1;
  bool raw_send_invoked = false;
  RevenantFixSteamSendTrace send_trace{};
  BhrcHostAdmissionAttempt observed_lease{};
  ULONGLONG lease_checked_tick = 0;
  const char* failure_reason = packet != nullptr ? "none" : "packet_alloc_failed";
  if (packet != nullptr) {
    for (uint16_t chunk_index = 0;
         chunk_index < chunk_count && all_sent; ++chunk_index) {
      *packet = RevenantFixFullPgdChunkPacket{};
      const uint32_t offset =
          static_cast<uint32_t>(chunk_index) * kBhrcFullPgdChunkPayloadSize;
      const uint32_t chunk_size =
          key.payload_size - offset < kBhrcFullPgdChunkPayloadSize
          ? key.payload_size - offset
          : kBhrcFullPgdChunkPayloadSize;
      packet->header.type = kRevenantFixSteamControlPacketTypeFullPgdChunk;
      packet->header.sender_steam_id =
          g_nrsc_steam_control_state.local_steam_id;
      packet->header.target_steam_id = target_steam_id;
      packet->header.lobby_id = key.master_lobby_id;
      packet->header.flags = static_cast<uint32_t>(purpose);
      packet->owner_steam_id = key.owner_steam_id;
      packet->master_lobby_id = key.master_lobby_id;
      packet->expedition_lobby_id = key.expedition_lobby_id;
      packet->authority_commit_seq = key.authority_commit_seq;
      packet->request_nonce = request_nonce;
      packet->client_generation = client_generation;
      packet->codec_version = key.codec_version;
      packet->snapshot_revision = key.snapshot_revision;
      packet->total_size = key.payload_size;
      packet->total_hash32 = key.payload_hash32;
      packet->chunk_index = chunk_index;
      packet->chunk_count = chunk_count;
      packet->chunk_size = chunk_size;
      packet->chunk_hash32 = BhrcFnv1a32(payload + offset, chunk_size);
      packet->purpose = static_cast<uint16_t>(purpose);
      std::memcpy(packet->payload, payload + offset, chunk_size);
      raw_send_invoked = false;
      send_trace = RevenantFixSteamSendTrace{};
      observed_lease = BhrcHostAdmissionAttempt{};
      lease_checked_tick = 0;
      if (admission_guard != nullptr) {
        bool lease_valid = false;
        AcquireSRWLockShared(&g_bhrc_host_admission_lock);
        for (const BhrcHostAdmissionAttempt& current :
             g_bhrc_host_admission_attempts) {
          const bool identity_matches = BhrcFullPgdAdmissionAttemptIdentityMatches(
              current, *admission_guard);
          const ULONGLONG checked_tick = identity_matches ? GetTickCount64() : 0;
          if (trace_restore && current.valid &&
              current.steam_id == admission_guard->steam_id) {
            observed_lease = current;
            lease_checked_tick = checked_tick;
          }
          if (identity_matches && current.expires_tick_ms > checked_tick &&
              current.full_pgd_codec_version == key.codec_version &&
              current.full_pgd_snapshot_revision ==
                  key.snapshot_revision &&
              current.full_pgd_payload_size == key.payload_size &&
              current.full_pgd_snapshot_hash32 ==
                  key.payload_hash32) {
            lease_valid = true;
            break;
          }
        }
        lease_valid_trace = lease_valid ? 1 : 0;
        if (lease_valid) {
          raw_send_invoked = true;
          all_sent = TrySendRevenantFixSteamPacketRaw(
              target_steam_id, packet,
              static_cast<uint32_t>(offsetof(RevenantFixFullPgdChunkPacket, payload) +
                                    chunk_size),
              packet->header.type, reason,
              purpose == BhrcFullPgdTransferPurpose::RestoreDelivery,
              trace_restore ? &send_trace : nullptr);
        } else {
          all_sent = false;
          failure_reason = "admission_lease";
        }
        ReleaseSRWLockShared(&g_bhrc_host_admission_lock);
      } else {
        raw_send_invoked = true;
        all_sent = TrySendRevenantFixSteamPacketRaw(
            target_steam_id, packet,
            static_cast<uint32_t>(offsetof(RevenantFixFullPgdChunkPacket, payload) +
                                  chunk_size), packet->header.type,
            reason, false, trace_restore ? &send_trace : nullptr);
      }
      if (all_sent) {
        ++submitted_chunks;
      } else {
        failed_chunk = static_cast<int>(chunk_index);
        if (raw_send_invoked) failure_reason = send_trace.failure_reason;
      }
    }
  }
  if (packet != nullptr) {
    HeapFree(GetProcessHeap(), 0, packet);
  }
  Log(
      "BHRC full_pgd_send outcome=%s reason=%s purpose=%s target=%016llx owner=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu nonce=%08x clientGeneration=%u codecVersion=%u revision=%llu size=%u hash=%08x chunks=%u coldStorage=0",
      all_sent ? "sent" : "failed",
      reason != nullptr ? reason : "unknown",
      BhrcFullPgdPurposeName(purpose),
      static_cast<unsigned long long>(target_steam_id),
      static_cast<unsigned long long>(key.owner_steam_id),
      static_cast<unsigned long long>(key.master_lobby_id),
      static_cast<unsigned long long>(key.expedition_lobby_id),
      static_cast<unsigned long long>(key.authority_commit_seq),
      request_nonce, client_generation, key.codec_version,
      static_cast<unsigned long long>(key.snapshot_revision),
      key.payload_size, key.payload_hash32, chunk_count);
  if (trace_restore) {
    const char* failed_check = nullptr;
    uint64_t expected_value = 0;
    uint64_t actual_value = 0;
    // Diagnose the locked snapshot only after releasing the admission lock.
    // These comparisons never participate in the send decision.
    if (lease_valid_trace == 0 && admission_guard != nullptr) {
      auto compare = [&](const char* field, uint64_t expected, uint64_t actual) {
        if (failed_check == nullptr && expected != actual) {
          failed_check = field;
          expected_value = expected;
          actual_value = actual;
        }
      };
      compare("admission_present", 1, observed_lease.valid ? 1 : 0);
      if (observed_lease.valid) {
        compare("guard_valid", 1, admission_guard->valid ? 1 : 0);
        compare("reservation_serial", admission_guard->reservation_serial, observed_lease.reservation_serial);
        compare("steam_id", admission_guard->steam_id, observed_lease.steam_id);
        compare("record_key", admission_guard->record_key, observed_lease.record_key);
        compare("master_lobby_id", admission_guard->master_lobby_id, observed_lease.master_lobby_id);
        compare("expedition_lobby_id", admission_guard->expedition_lobby_id, observed_lease.expedition_lobby_id);
        compare("authority_commit_seq", admission_guard->authority_commit_seq, observed_lease.authority_commit_seq);
        compare("manager_id", admission_guard->manager_id, observed_lease.manager_id);
        compare("request_nonce", admission_guard->request_nonce, observed_lease.request_nonce);
        compare("client_generation", admission_guard->client_generation, observed_lease.client_generation);
        compare("identity_hash32", admission_guard->identity_hash32, observed_lease.identity_hash32);
        compare("trigger", static_cast<uint64_t>(admission_guard->trigger), static_cast<uint64_t>(observed_lease.trigger));
        compare("membership", static_cast<uint64_t>(admission_guard->membership), static_cast<uint64_t>(observed_lease.membership));
        if (failed_check == nullptr && observed_lease.expires_tick_ms <= lease_checked_tick) {
          failed_check = "expires_tick_ms_minimum";
          expected_value = lease_checked_tick + 1;
          actual_value = observed_lease.expires_tick_ms;
        }
        compare("codec_version", key.codec_version, observed_lease.full_pgd_codec_version);
        compare("snapshot_revision", key.snapshot_revision, observed_lease.full_pgd_snapshot_revision);
        compare("payload_size", key.payload_size, observed_lease.full_pgd_payload_size);
        compare("payload_hash32", key.payload_hash32, observed_lease.full_pgd_snapshot_hash32);
      }
      if (failed_check == nullptr) failed_check = "unclassified_lease_mismatch";
    }
    Log("BHRC_PGD_TX_TRACE transfer seq=%ld outcome=%s failure=%s requestReason=%s target=%016llx owner=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu nonce=%08x generation=%u revision=%llu size=%u hash=%08x chunks=%u submittedChunks=%u failedChunk=%d chunkIndexBase=0 leaseValid=%d leaseRecordFound=%d leaseCheck=%s expected=%016llx actual=%016llx leaseCheckedTick=%llu rawSendInvoked=%d steamCalled=%d steamResultValid=%d steamResult=%d resultScope=last_or_failed_chunk deliveryAck=0 behaviorMutation=0",
        trace_seq, all_sent ? "submitted" : "failed", failure_reason,
        reason != nullptr ? reason : "unknown",
        static_cast<unsigned long long>(target_steam_id),
        static_cast<unsigned long long>(key.owner_steam_id),
        static_cast<unsigned long long>(key.master_lobby_id),
        static_cast<unsigned long long>(key.expedition_lobby_id),
        static_cast<unsigned long long>(key.authority_commit_seq),
        request_nonce, client_generation,
        static_cast<unsigned long long>(key.snapshot_revision),
        key.payload_size, key.payload_hash32, static_cast<unsigned>(chunk_count),
        static_cast<unsigned>(submitted_chunks), failed_chunk, lease_valid_trace,
        observed_lease.valid ? 1 : 0, failed_check != nullptr ? failed_check : "none",
        static_cast<unsigned long long>(expected_value),
        static_cast<unsigned long long>(actual_value),
        static_cast<unsigned long long>(lease_checked_tick), raw_send_invoked ? 1 : 0,
        send_trace.steam_called ? 1 : 0, send_trace.steam_result_valid ? 1 : 0,
        send_trace.steam_result);
  }
  return all_sent;
}


// 7a66e71 src/dllmain.cpp:13895
bool SendBhrcFullPgdSnapshot(
    uint64_t target_steam_id,
    const BhrcFullPgdSnapshotKey& requested,
    BhrcFullPgdTransferPurpose purpose,
    uint32_t request_nonce,
    uint32_t client_generation,
    const char* reason,
    BhrcFullPgdSnapshotKey* out_sent_key) {
  if (out_sent_key != nullptr) {
    *out_sent_key = BhrcFullPgdSnapshotKey{};
  }
  BhrcFullPgdSnapshotKey key{};
  uint8_t* payload = nullptr;
  if (!CopyBhrcFullPgdHotSnapshot(requested, &key, &payload)) {
    return false;
  }
  const bool sent = SendBhrcFullPgdPayload(
      target_steam_id, key, payload, purpose, request_nonce,
      client_generation, reason);
  HeapFree(GetProcessHeap(), 0, payload);
  if (sent && out_sent_key != nullptr) {
    *out_sent_key = key;
  }
  return sent;
}


// 7a66e71 src/dllmain.cpp:13921
void MarkBhrcFullPgdSnapshotsForPublish(const char* reason) {
  uint32_t marked = 0;
  const uint64_t local = g_nrsc_steam_control_state.local_steam_id;
  const bool local_host = IsLocalNrscHost();
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_hot_lock);
  for (BhrcFullPgdHotSnapshot& snapshot : g_bhrc_full_pgd_hot_snapshots) {
    if (snapshot.valid && (local_host || snapshot.owner_steam_id == local)) {
      snapshot.publish_pending = true;
      ++marked;
    }
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_hot_lock);
  if (marked != 0) {
    Log(
        "BHRC full_pgd_publish_marked reason=%s snapshots=%u coldStorage=0",
        reason != nullptr ? reason : "unknown", marked);
  }
}


// 7a66e71 src/dllmain.cpp:13940
void MarkBhrcFullPgdSnapshotPublished(
    const BhrcFullPgdSnapshotKey& key) {
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_hot_lock);
  BhrcFullPgdHotSnapshot* snapshot = FindBhrcFullPgdHotSnapshotLocked(
      key.owner_steam_id, key.master_lobby_id, key.expedition_lobby_id,
      key.authority_commit_seq);
  if (snapshot != nullptr &&
      snapshot->snapshot_revision == key.snapshot_revision &&
      snapshot->payload_hash32 == key.payload_hash32) {
    snapshot->publish_pending = false;
    snapshot->last_publish_tick_ms = GetTickCount64();
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_hot_lock);
}


// 7a66e71 src/dllmain.cpp:13955
void AdvanceBhrcFullPgdSnapshotPublication() {
  BhrcFullPgdSnapshotKey pending[kBhrcFullPgdHotSnapshotCapacity]{};
  uint32_t pending_count = 0;
  AcquireSRWLockShared(&g_bhrc_full_pgd_hot_lock);
  for (const BhrcFullPgdHotSnapshot& snapshot :
       g_bhrc_full_pgd_hot_snapshots) {
    if (!snapshot.valid || !snapshot.publish_pending ||
        pending_count >= _countof(pending)) {
      continue;
    }
    BhrcFullPgdSnapshotKey& key = pending[pending_count++];
    key.owner_steam_id = snapshot.owner_steam_id;
    key.master_lobby_id = snapshot.master_lobby_id;
    key.expedition_lobby_id = snapshot.expedition_lobby_id;
    key.authority_commit_seq = snapshot.authority_commit_seq;
    key.codec_version = snapshot.codec_version;
    key.snapshot_revision = snapshot.snapshot_revision;
    key.payload_size = snapshot.payload_size;
    key.payload_hash32 = snapshot.payload_hash32;
  }
  ReleaseSRWLockShared(&g_bhrc_full_pgd_hot_lock);
  if (pending_count == 0) {
    return;
  }

  const uint64_t local = g_nrsc_steam_control_state.local_steam_id;
  const uint64_t owner = g_nrsc_steam_control_state.owner_steam_id;
  if (local == 0 || owner == 0) {
    return;
  }
  uint64_t peers[_countof(g_active_nrsc_peer_steam_ids)]{};
  AcquireSRWLockShared(&g_active_nrsc_peer_lock);
  std::memcpy(peers, g_active_nrsc_peer_steam_ids, sizeof(peers));
  ReleaseSRWLockShared(&g_active_nrsc_peer_lock);

  for (uint32_t index = 0; index < pending_count; ++index) {
    const BhrcFullPgdSnapshotKey& key = pending[index];
    bool completed = true;
    bool had_required_target = false;
    if (local == owner) {
      for (uint64_t peer : peers) {
        if (peer == 0 || peer == key.owner_steam_id) {
          continue;
        }
        had_required_target = true;
        if (!SendBhrcFullPgdSnapshot(
                peer, key, BhrcFullPgdTransferPurpose::AuthorityRelay,
                0, 0, "authority_hot_snapshot_relay", nullptr)) {
          completed = false;
        }
      }
      // A remote owner already holds its own current data. With no other peer
      // there is no relay recipient, so this revision is complete until a join
      // marks all snapshots pending again.
      if (!had_required_target && key.owner_steam_id == local) {
        for (uint64_t peer : peers) {
          if (peer != 0) {
            had_required_target = true;
            if (!SendBhrcFullPgdSnapshot(
                    peer, key,
                    BhrcFullPgdTransferPurpose::AuthorityRelay,
                    0, 0, "authority_local_snapshot_relay", nullptr)) {
              completed = false;
            }
          }
        }
      }
    } else {
      if (key.owner_steam_id != local || !IsNrscPeerActive(owner)) {
        completed = false;
      } else {
        had_required_target = true;
        completed = SendBhrcFullPgdSnapshot(
            owner, key, BhrcFullPgdTransferPurpose::OwnerPublish,
            0, 0, "owner_hot_snapshot_publish", nullptr);
      }
    }
    if (completed && (had_required_target || local == owner)) {
      MarkBhrcFullPgdSnapshotPublished(key);
    }
  }
}


// 7a66e71 src/dllmain.cpp:14038
bool BhrcFullPgdPacketMatchesAssembly(
    const BhrcFullPgdInboundAssembly& assembly,
    uint64_t sender,
    const RevenantFixFullPgdChunkPacket& packet) {
  return assembly.valid && assembly.sender_steam_id == sender &&
      assembly.target_steam_id == packet.header.target_steam_id &&
      assembly.owner_steam_id == packet.owner_steam_id &&
      assembly.master_lobby_id == packet.master_lobby_id &&
      assembly.expedition_lobby_id == packet.expedition_lobby_id &&
      assembly.authority_commit_seq == packet.authority_commit_seq &&
      assembly.request_nonce == packet.request_nonce &&
      assembly.client_generation == packet.client_generation &&
      assembly.codec_version == packet.codec_version &&
      assembly.snapshot_revision == packet.snapshot_revision &&
      assembly.total_size == packet.total_size &&
      assembly.total_hash32 == packet.total_hash32 &&
      assembly.chunk_count == packet.chunk_count &&
      assembly.purpose == packet.purpose;
}


// 7a66e71 src/dllmain.cpp:14058
bool ArmBhrcFullPgdRestoreTicket(
    uint64_t sender,
    const RevenantFixFullPgdChunkPacket& packet,
    const BhrcExpeditionProbeAttempt& probe,
    const uint8_t* payload) {
  bool conflicting_retry = false;
  bool accepted = false;
  bool already_final_generation = false;
  if (payload == nullptr ||
      BhrcFnv1a32(payload, packet.total_size) != packet.total_hash32) {
    return false;
  }
  const BhrcNativeExpeditionAuthorityState authority =
      SnapshotNativeExpeditionAuthority();
  const bool authority_matches_probe = authority.valid &&
      authority.commit_seq == probe.authority_commit_seq &&
      authority.master_lobby_id == probe.master_lobby_id &&
      authority.lobby_id == probe.expedition_lobby_id &&
      authority.owner_steam_id == probe.host_steam_id &&
      authority.local_steam_id == packet.owner_steam_id &&
      authority.manager_id != 0 &&
      authority.native_manager != nullptr;
  BhrcExpeditionWorldPhaseState world_phase{};
  AcquireSRWLockShared(&g_bhrc_expedition_world_phase_lock);
  world_phase = g_bhrc_expedition_world_phase;
  ReleaseSRWLockShared(&g_bhrc_expedition_world_phase_lock);
  void* const current_world_chr_man =
      ReadGameGlobalPtr(kWorldChrManPtrRva);
  void* const player_game_data_manager = GetPlayerGameDataManager();
  void* const current_local_pgd = player_game_data_manager != nullptr
      ? reinterpret_cast<void*>(ReadU64(
            static_cast<const uint8_t*>(player_game_data_manager) + 8, 0))
      : nullptr;
  AcquireSRWLockShared(&g_bhrc_expedition_probe_lock);
  const auto& live_probe = g_bhrc_expedition_probe;
  if (live_probe.request_nonce != probe.request_nonce ||
      live_probe.client_generation != probe.client_generation ||
      live_probe.host_steam_id != sender ||
      BhrcFullPgdRestoreWindowClosed(live_probe)) {
    ReleaseSRWLockShared(&g_bhrc_expedition_probe_lock);
    return false;
  }
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  const bool same_attempt = g_bhrc_full_pgd_restore_ticket.valid &&
      g_bhrc_full_pgd_restore_ticket.host_steam_id == sender &&
      g_bhrc_full_pgd_restore_ticket.owner_steam_id ==
          packet.owner_steam_id &&
      g_bhrc_full_pgd_restore_ticket.master_lobby_id ==
          packet.master_lobby_id &&
      g_bhrc_full_pgd_restore_ticket.expedition_lobby_id ==
          packet.expedition_lobby_id &&
      g_bhrc_full_pgd_restore_ticket.request_nonce == packet.request_nonce &&
      g_bhrc_full_pgd_restore_ticket.client_generation ==
          packet.client_generation &&
      g_bhrc_full_pgd_restore_ticket.authority_commit_seq ==
          packet.authority_commit_seq &&
      g_bhrc_full_pgd_restore_ticket.source_authority_manager_id ==
          probe.manager_id;
  const bool same_snapshot = same_attempt &&
      g_bhrc_full_pgd_restore_ticket.codec_version == packet.codec_version &&
      g_bhrc_full_pgd_restore_ticket.snapshot_revision ==
          packet.snapshot_revision &&
      g_bhrc_full_pgd_restore_ticket.payload_size == packet.total_size &&
      g_bhrc_full_pgd_restore_ticket.payload_hash32 == packet.total_hash32;
  const bool gate_final_for_same_native_generation =
      g_bhrc_full_pgd_restore_gate.valid &&
      static_cast<uint8_t>(g_bhrc_full_pgd_restore_gate.stage) >=
          static_cast<uint8_t>(
              BhrcFullPgdRestoreGateStage::FinalApplied) &&
      g_bhrc_full_pgd_restore_gate.local_steam_id ==
          packet.owner_steam_id &&
      g_bhrc_full_pgd_restore_gate.host_steam_id == sender &&
      g_bhrc_full_pgd_restore_gate.master_lobby_id ==
          packet.master_lobby_id &&
      g_bhrc_full_pgd_restore_gate.expedition_lobby_id ==
          packet.expedition_lobby_id &&
      g_bhrc_full_pgd_restore_gate.authority_commit_seq ==
          packet.authority_commit_seq &&
      g_bhrc_full_pgd_restore_gate.source_authority_manager_id ==
          probe.manager_id &&
      authority.valid &&
      authority.local_steam_id == packet.owner_steam_id &&
      authority.owner_steam_id == sender &&
      authority.master_lobby_id == packet.master_lobby_id &&
      authority.lobby_id == packet.expedition_lobby_id &&
      authority.commit_seq == packet.authority_commit_seq &&
      authority.manager_id != 0 &&
      g_bhrc_full_pgd_restore_gate.local_manager_id ==
          authority.manager_id &&
      authority.native_manager != nullptr &&
      authority.native_manager ==
          g_bhrc_full_pgd_restore_gate.native_manager &&
      current_world_chr_man != nullptr &&
      current_world_chr_man ==
          g_bhrc_full_pgd_restore_gate.final_world_chr_man &&
      g_bhrc_full_pgd_restore_gate.final_player_game_data != nullptr &&
      g_bhrc_full_pgd_restore_gate.final_player_game_data ==
          current_local_pgd &&
      world_phase.local_base_registration_seq ==
          g_bhrc_full_pgd_restore_gate
              .final_local_base_registration_seq;
  auto install_ticket = [&](bool final_already_applied) {
    g_bhrc_full_pgd_restore_ticket = BhrcFullPgdRestoreTicket{};
    g_bhrc_full_pgd_restore_ticket.valid = true;
    g_bhrc_full_pgd_restore_ticket.received_tick_ms = GetTickCount64();
    g_bhrc_full_pgd_restore_ticket.owner_steam_id =
        packet.owner_steam_id;
    g_bhrc_full_pgd_restore_ticket.host_steam_id = sender;
    g_bhrc_full_pgd_restore_ticket.master_lobby_id =
        packet.master_lobby_id;
    g_bhrc_full_pgd_restore_ticket.expedition_lobby_id =
        packet.expedition_lobby_id;
    g_bhrc_full_pgd_restore_ticket.authority_commit_seq =
        packet.authority_commit_seq;
    g_bhrc_full_pgd_restore_ticket.source_authority_manager_id =
        probe.manager_id;
    g_bhrc_full_pgd_restore_ticket.local_manager_id =
        authority_matches_probe ? authority.manager_id : 0;
    g_bhrc_full_pgd_restore_ticket.native_manager =
        authority_matches_probe ? authority.native_manager : nullptr;
    g_bhrc_full_pgd_restore_ticket.request_nonce =
        packet.request_nonce;
    g_bhrc_full_pgd_restore_ticket.client_generation =
        packet.client_generation;
    g_bhrc_full_pgd_restore_ticket.codec_version =
        packet.codec_version;
    g_bhrc_full_pgd_restore_ticket.snapshot_revision =
        packet.snapshot_revision;
    g_bhrc_full_pgd_restore_ticket.payload_size = packet.total_size;
    g_bhrc_full_pgd_restore_ticket.payload_hash32 =
        packet.total_hash32;
    if (final_already_applied) {
      g_bhrc_full_pgd_restore_ticket.applied = true;
      g_bhrc_full_pgd_restore_ticket.final_applied = true;
      g_bhrc_full_pgd_restore_ticket.applied_player_game_data =
          g_bhrc_full_pgd_restore_gate.final_player_game_data;
      g_bhrc_full_pgd_restore_ticket.final_player_game_data =
          g_bhrc_full_pgd_restore_gate.final_player_game_data;
      g_bhrc_full_pgd_restore_ticket.applied_tick_ms =
          g_bhrc_full_pgd_restore_gate.updated_tick_ms;
      g_bhrc_full_pgd_restore_ticket.final_applied_tick_ms =
          g_bhrc_full_pgd_restore_gate.updated_tick_ms;
      std::memset(
          g_bhrc_full_pgd_restore_payload, 0,
          sizeof(g_bhrc_full_pgd_restore_payload));
    } else {
      std::memcpy(
          g_bhrc_full_pgd_restore_payload, payload, packet.total_size);
    }
  };
  if (BhrcFullPgdRestoreWindowClosed(live_probe)) {
    accepted = false;
  } else if (same_snapshot) {
    // Exact retransmission is idempotent in every ticket state, including
    // applying/applied/failed. Never clear progress or run the native codec
    // twice because Steam delivered the same complete body again.
    accepted = true;
  } else if (g_bhrc_full_pgd_restore_ticket.applying) {
    conflicting_retry = true;
  } else if (!same_attempt) {
    install_ticket(gate_final_for_same_native_generation);
    already_final_generation = gate_final_for_same_native_generation;
    accepted = true;
  } else if (same_attempt && !same_snapshot) {
    // One authorization attempt owns exactly one host-pinned revision.
    // Preserve an already pending/applied/failed ticket rather than letting a
    // late retry replace its identity or make a successful restore run twice.
    conflicting_retry = true;
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_restore_lock);
  ReleaseSRWLockShared(&g_bhrc_expedition_probe_lock);
  if (conflicting_retry) {
    LogWarn(
        "BHRC full_pgd_restore outcome=retry_rejected reason=attempt_snapshot_changed owner=%016llx host=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu nonce=%08x clientGeneration=%u revision=%llu size=%u hash=%08x",
        static_cast<unsigned long long>(packet.owner_steam_id),
        static_cast<unsigned long long>(sender),
        static_cast<unsigned long long>(packet.master_lobby_id),
        static_cast<unsigned long long>(packet.expedition_lobby_id),
        static_cast<unsigned long long>(packet.authority_commit_seq),
        packet.request_nonce, packet.client_generation,
        static_cast<unsigned long long>(packet.snapshot_revision),
        packet.total_size, packet.total_hash32);
  } else if (accepted && already_final_generation) {
    Log(
        "BHRC full_pgd_restore outcome=already_final reason=same_native_object_generation owner=%016llx host=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu nonce=%08x clientGeneration=%u revision=%llu size=%u hash=%08x nativeReplay=0",
        static_cast<unsigned long long>(packet.owner_steam_id),
        static_cast<unsigned long long>(sender),
        static_cast<unsigned long long>(packet.master_lobby_id),
        static_cast<unsigned long long>(packet.expedition_lobby_id),
        static_cast<unsigned long long>(packet.authority_commit_seq),
        packet.request_nonce, packet.client_generation,
        static_cast<unsigned long long>(packet.snapshot_revision),
        packet.total_size, packet.total_hash32);
  }
  return accepted;
}


// 7a66e71 src/dllmain.cpp:14243
bool HandleRevenantFixFullPgdChunk(
    uint64_t sender,
    const RevenantFixFullPgdChunkPacket& packet) {
  const uint64_t local = g_nrsc_steam_control_state.local_steam_id;
  const uint64_t owner = g_nrsc_steam_control_state.owner_steam_id;
  const auto purpose =
      static_cast<BhrcFullPgdTransferPurpose>(packet.purpose);
  const uint32_t expected_chunk_size =
      packet.chunk_index + 1 == packet.chunk_count
      ? packet.total_size -
            static_cast<uint32_t>(packet.chunk_index) *
                kBhrcFullPgdChunkPayloadSize
      : kBhrcFullPgdChunkPayloadSize;
  const char* reject_reason = nullptr;
  if (local == 0 || sender == 0 || packet.header.target_steam_id != local) {
    reject_reason = "identity_or_target_mismatch";
  } else if (packet.header.lobby_id == 0 ||
             packet.header.lobby_id != packet.master_lobby_id ||
             packet.owner_steam_id == 0 || packet.expedition_lobby_id == 0 ||
             packet.authority_commit_seq == 0 || packet.codec_version == 0 ||
             packet.snapshot_revision == 0 || packet.total_hash32 == 0) {
    reject_reason = "missing_authority_or_snapshot_identity";
  } else if (!IsBhrcFullPgdPayloadShapeValid(
                 packet.total_size, packet.chunk_count) ||
             packet.chunk_index >= packet.chunk_count ||
             packet.chunk_size != expected_chunk_size ||
             packet.chunk_size == 0 ||
             packet.chunk_size > kBhrcFullPgdChunkPayloadSize) {
    reject_reason = "invalid_chunk_shape";
  } else if (packet.chunk_hash32 == 0 ||
             BhrcFnv1a32(packet.payload, packet.chunk_size) !=
                 packet.chunk_hash32) {
    reject_reason = "chunk_hash_mismatch";
  }

  const BhrcNativeExpeditionAuthorityState local_authority =
      SnapshotNativeExpeditionAuthority();
  BhrcExpeditionProbeAttempt probe{};
  if (reject_reason == nullptr &&
      purpose == BhrcFullPgdTransferPurpose::OwnerPublish) {
    if (!IsLocalNrscHost() || packet.owner_steam_id != sender ||
        packet.request_nonce != 0 || packet.client_generation != 0 ||
        !local_authority.valid ||
        local_authority.owner_steam_id != local ||
        packet.master_lobby_id != local_authority.master_lobby_id ||
        packet.expedition_lobby_id != local_authority.lobby_id ||
        packet.authority_commit_seq != local_authority.commit_seq) {
      reject_reason = "owner_publish_authority_mismatch";
    }
  } else if (reject_reason == nullptr &&
             purpose == BhrcFullPgdTransferPurpose::AuthorityRelay) {
    probe = SnapshotBhrcExpeditionProbe();
    const bool local_tuple = local_authority.valid && sender == owner &&
        local_authority.owner_steam_id == sender &&
        packet.master_lobby_id == local_authority.master_lobby_id &&
        packet.expedition_lobby_id == local_authority.lobby_id;
    const bool authorized_early_tuple =
        IsBhrcAuthorizedClientProbe(probe) &&
        sender == probe.host_steam_id &&
        packet.master_lobby_id == probe.master_lobby_id &&
        packet.expedition_lobby_id == probe.expedition_lobby_id &&
        packet.authority_commit_seq == probe.authority_commit_seq;
    const bool nrsc_owner_transport_tuple = sender == owner && owner != 0 &&
        packet.master_lobby_id == GetCurrentNrscMasterLobbyId() &&
        packet.expedition_lobby_id != packet.master_lobby_id;
    uint64_t known_authority_seq = 0;
    const bool has_known_authority =
        SnapshotBhrcFullPgdAuthorityReceipt(
            local_authority, &known_authority_seq);
    if (IsLocalNrscHost() || packet.request_nonce != 0 ||
        packet.client_generation != 0 ||
        (!local_tuple && !authorized_early_tuple &&
         !nrsc_owner_transport_tuple) ||
        (has_known_authority &&
         packet.authority_commit_seq < known_authority_seq)) {
      reject_reason = "authority_relay_tuple_mismatch";
    }
  } else if (reject_reason == nullptr &&
             purpose == BhrcFullPgdTransferPurpose::RestoreDelivery) {
    probe = SnapshotBhrcExpeditionProbe();
    if (IsLocalNrscHost() || !IsBhrcAuthorizedClientProbe(probe) ||
        packet.owner_steam_id != local || sender != probe.host_steam_id ||
        packet.request_nonce == 0 ||
        packet.request_nonce != probe.request_nonce ||
        packet.client_generation != probe.client_generation ||
        packet.master_lobby_id != probe.master_lobby_id ||
        packet.expedition_lobby_id != probe.expedition_lobby_id ||
        packet.authority_commit_seq != probe.authority_commit_seq) {
      reject_reason = "restore_delivery_attempt_mismatch";
    } else if (BhrcFullPgdRestoreWindowClosed(probe)) {
      // Do not assemble a late body or let its arrival restart the clock.
      if (packet.chunk_index == 0) {
        LogWarn(
            "BHRC full_pgd_recv outcome=rejected reason=restore_window_closed nonce=%08x clientGeneration=%u revision=%llu limitMs=%llu nativeReplay=0",
            packet.request_nonce, packet.client_generation,
            static_cast<unsigned long long>(packet.snapshot_revision),
            static_cast<unsigned long long>(kBhrcFullPgdRestoreWindowMs));
      }
      return true;
    }
  } else if (reject_reason == nullptr) {
    reject_reason = "unsupported_purpose";
  }

  if (reject_reason != nullptr) {
    LogWarn(
        "BHRC full_pgd_recv outcome=rejected reason=%s purpose=%s sender=%016llx target=%016llx owner=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu nonce=%08x clientGeneration=%u codecVersion=%u revision=%llu totalSize=%u totalHash=%08x chunk=%u/%u chunkSize=%u chunkHash=%08x coldStorage=0",
        reject_reason, BhrcFullPgdPurposeName(purpose),
        static_cast<unsigned long long>(sender),
        static_cast<unsigned long long>(packet.header.target_steam_id),
        static_cast<unsigned long long>(packet.owner_steam_id),
        static_cast<unsigned long long>(packet.master_lobby_id),
        static_cast<unsigned long long>(packet.expedition_lobby_id),
        static_cast<unsigned long long>(packet.authority_commit_seq),
        packet.request_nonce, packet.client_generation, packet.codec_version,
        static_cast<unsigned long long>(packet.snapshot_revision),
        packet.total_size, packet.total_hash32, packet.chunk_index,
        packet.chunk_count, packet.chunk_size, packet.chunk_hash32);
    return true;
  }

  if (purpose == BhrcFullPgdTransferPurpose::AuthorityRelay) {
    PublishBhrcFullPgdAuthorityReceipt(
        packet.master_lobby_id, packet.expedition_lobby_id, sender,
        packet.authority_commit_seq);
  }

  uint8_t* completed_payload = nullptr;
  bool complete = false;
  AcquireSRWLockExclusive(&g_bhrc_full_pgd_assembly_lock);
  const ULONGLONG now = GetTickCount64();
  BhrcFullPgdInboundAssembly* assembly = nullptr;
  BhrcFullPgdInboundAssembly* oldest =
      &g_bhrc_full_pgd_inbound_assemblies[0];
  for (BhrcFullPgdInboundAssembly& candidate :
       g_bhrc_full_pgd_inbound_assemblies) {
    if (candidate.valid &&
        now - candidate.received_tick_ms >= kBhrcFullPgdAssemblyLifetimeMs) {
      std::memset(&candidate, 0, sizeof(candidate));
    }
    if (BhrcFullPgdPacketMatchesAssembly(candidate, sender, packet)) {
      assembly = &candidate;
      break;
    }
    if (!candidate.valid && assembly == nullptr) {
      assembly = &candidate;
    }
    if (candidate.received_tick_ms < oldest->received_tick_ms) {
      oldest = &candidate;
    }
  }
  if (assembly == nullptr) {
    assembly = oldest;
  }
  if (!BhrcFullPgdPacketMatchesAssembly(*assembly, sender, packet)) {
    std::memset(assembly, 0, sizeof(*assembly));
    assembly->valid = true;
    assembly->sender_steam_id = sender;
    assembly->target_steam_id = packet.header.target_steam_id;
    assembly->owner_steam_id = packet.owner_steam_id;
    assembly->master_lobby_id = packet.master_lobby_id;
    assembly->expedition_lobby_id = packet.expedition_lobby_id;
    assembly->authority_commit_seq = packet.authority_commit_seq;
    assembly->request_nonce = packet.request_nonce;
    assembly->client_generation = packet.client_generation;
    assembly->codec_version = packet.codec_version;
    assembly->snapshot_revision = packet.snapshot_revision;
    assembly->total_size = packet.total_size;
    assembly->total_hash32 = packet.total_hash32;
    assembly->chunk_count = packet.chunk_count;
    assembly->purpose = packet.purpose;
  }
  assembly->received_tick_ms = now;
  const uint32_t offset =
      static_cast<uint32_t>(packet.chunk_index) *
      kBhrcFullPgdChunkPayloadSize;
  std::memcpy(assembly->payload + offset, packet.payload, packet.chunk_size);
  assembly->received_chunk_mask |= uint64_t{1} << packet.chunk_index;
  const uint64_t expected_mask = packet.chunk_count == 64
      ? UINT64_MAX
      : ((uint64_t{1} << packet.chunk_count) - 1);
  if (assembly->received_chunk_mask == expected_mask) {
    completed_payload = static_cast<uint8_t*>(HeapAlloc(
        GetProcessHeap(), 0, assembly->total_size));
    if (completed_payload != nullptr) {
      std::memcpy(completed_payload, assembly->payload, assembly->total_size);
      complete = true;
    }
    std::memset(assembly, 0, sizeof(*assembly));
  }
  ReleaseSRWLockExclusive(&g_bhrc_full_pgd_assembly_lock);
  if (!complete) {
    return true;
  }

  const uint32_t full_hash =
      BhrcFnv1a32(completed_payload, packet.total_size);
  if (full_hash != packet.total_hash32) {
    LogWarn(
        "BHRC full_pgd_recv outcome=rejected reason=full_hash_mismatch purpose=%s sender=%016llx owner=%016llx revision=%llu size=%u packetHash=%08x actualHash=%08x coldStorage=0",
        BhrcFullPgdPurposeName(purpose),
        static_cast<unsigned long long>(sender),
        static_cast<unsigned long long>(packet.owner_steam_id),
        static_cast<unsigned long long>(packet.snapshot_revision),
        packet.total_size, packet.total_hash32, full_hash);
    HeapFree(GetProcessHeap(), 0, completed_payload);
    return true;
  }
  BhrcFullPgdSnapshotKey stored{};
  const bool stored_ok =
      purpose == BhrcFullPgdTransferPurpose::RestoreDelivery
      ? ArmBhrcFullPgdRestoreTicket(
            sender, packet, probe, completed_payload)
      : StoreBhrcFullPgdHotSnapshot(
            packet.owner_steam_id, packet.master_lobby_id,
            packet.expedition_lobby_id, packet.authority_commit_seq,
            packet.codec_version, packet.snapshot_revision, completed_payload,
            packet.total_size, packet.total_hash32,
            purpose == BhrcFullPgdTransferPurpose::OwnerPublish,
            BhrcFullPgdPurposeName(purpose), &stored);
  HeapFree(GetProcessHeap(), 0, completed_payload);
  Log(
      "BHRC full_pgd_recv outcome=%s purpose=%s sender=%016llx owner=%016llx masterA=%016llx expeditionB=%016llx authoritySeq=%llu nonce=%08x clientGeneration=%u codecVersion=%u revision=%llu size=%u hash=%08x chunks=%u restoreArmed=%d relayPending=%d coldStorage=0",
      stored_ok ? "assembled" : "store_rejected",
      BhrcFullPgdPurposeName(purpose),
      static_cast<unsigned long long>(sender),
      static_cast<unsigned long long>(packet.owner_steam_id),
      static_cast<unsigned long long>(packet.master_lobby_id),
      static_cast<unsigned long long>(packet.expedition_lobby_id),
      static_cast<unsigned long long>(packet.authority_commit_seq),
      packet.request_nonce, packet.client_generation, packet.codec_version,
      static_cast<unsigned long long>(packet.snapshot_revision),
      packet.total_size, packet.total_hash32, packet.chunk_count,
      stored_ok && purpose == BhrcFullPgdTransferPurpose::RestoreDelivery
          ? 1
          : 0,
      stored_ok && purpose == BhrcFullPgdTransferPurpose::OwnerPublish
          ? 1
          : 0);
  return true;
}


// 7a66e71 src/dllmain.cpp:14475
const char* BhrcRejectReasonName(BhrcRejectReason reason) {
  switch (reason) {
    case BhrcRejectReason::None:
      return "none";
    case BhrcRejectReason::NotHost:
      return "not_host";
    case BhrcRejectReason::MissingLobby:
      return "missing_lobby";
    case BhrcRejectReason::LobbyMismatch:
      return "lobby_mismatch";
    case BhrcRejectReason::MissingSteamId:
      return "missing_steam_id";
    case BhrcRejectReason::MissingRecordKey:
      return "missing_record_key";
    case BhrcRejectReason::NoSessionManager:
      return "no_session_manager";
    case BhrcRejectReason::SessionNotInExpedition:
      return "session_not_in_expedition";
    case BhrcRejectReason::RecordNotFound:
      return "record_not_found";
    case BhrcRejectReason::PlayerIndexMismatch:
      return "player_index_mismatch";
    case BhrcRejectReason::PlayerGameDataMissing:
      return "player_game_data_missing";
    case BhrcRejectReason::RestoreContextMissing:
      return "restore_context_missing";
    case BhrcRejectReason::NativeRestoreException:
      return "native_restore_exception";
    case BhrcRejectReason::WorldChrMissing:
      return "world_chr_missing";
    case BhrcRejectReason::PartyMemberMissing:
      return "party_member_missing";
    case BhrcRejectReason::ClientRecordPrereqMissing:
      return "client_record_prereq_missing";
    case BhrcRejectReason::Timeout:
      return "timeout";
    case BhrcRejectReason::GameDataIdMismatch:
      return "game_data_id_mismatch";
    case BhrcRejectReason::CachedRecordOnly:
      return "cached_record_only";
    default:
      return "unknown";
  }
}


// 7a66e71 src/dllmain.cpp:14523
const char* BhrcPhaseName(BhrcPhase phase) {
  switch (phase) {
    case BhrcPhase::Idle:
      return "idle";
    case BhrcPhase::RequestingTransport:
      return "requesting_transport";
    case BhrcPhase::PeerDiscovered:
      return "peer_discovered";
    case BhrcPhase::Done:
      return "done";
    case BhrcPhase::Failed:
      return "failed";
    default:
      return "unknown";
  }
}


// 7a66e71 src/dllmain.cpp:14540
uint32_t CountKnownNrscPeers() {
  uint32_t count = 0;
  for (uint64_t peer : g_known_nrsc_peer_steam_ids) {
    if (peer != 0 && peer != g_nrsc_steam_control_state.local_steam_id) {
      ++count;
    }
  }
  return count;
}


// 7a66e71 src/dllmain.cpp:14554
void CountBhrcRecordCache(uint32_t* active_count, uint32_t* inactive_count) {
  BhrcRecordCacheGuard cache_guard;
  uint32_t active = 0;
  uint32_t inactive = 0;
  for (const BhrcSteamRecordCacheEntry& entry : g_bhrc_active_record_cache) {
    if (entry.valid && entry.steam_id != 0) {
      ++active;
    }
  }
  for (const BhrcSteamRecordCacheEntry& entry : g_bhrc_inactive_record_cache) {
    if (entry.valid && entry.steam_id != 0) {
      ++inactive;
    }
  }
  if (active_count != nullptr) {
    *active_count = active;
  }
  if (inactive_count != nullptr) {
    *inactive_count = inactive;
  }
}


// 7a66e71 src/dllmain.cpp:14576
void LogBhrcRecordCacheSummary(const char* reason) {
  BhrcRecordCacheGuard cache_guard;
  uint32_t active_count = 0;
  uint32_t inactive_count = 0;
  CountBhrcRecordCache(&active_count, &inactive_count);
  Log(
      "BHRC record_cache_summary reason=%s local=%016llx owner=%016llx lobby=%016llx active=%u inactive=%u generation=%u knownPeers=%u",
      reason != nullptr ? reason : "unknown",
      static_cast<unsigned long long>(g_nrsc_steam_control_state.local_steam_id),
      static_cast<unsigned long long>(g_nrsc_steam_control_state.owner_steam_id),
      static_cast<unsigned long long>(GetSavedNrscSteamLobbyId()),
      active_count,
      inactive_count,
      g_bhrc_record_cache_generation,
      CountKnownNrscPeers());
  for (uint32_t i = 0; i < kBhrcActiveRecordSlots; ++i) {
    const BhrcSteamRecordCacheEntry& entry = g_bhrc_active_record_cache[i];
    if (!entry.valid || entry.steam_id == 0) {
      continue;
    }
    Log(
        "BHRC record_cache_slot reason=%s state=active index=%u steamId=%016llx lobby=%016llx recordKey=%016llx recordRole=%s playerIndex=%d gameDataId=%d recordD4Id=%d partyMemberSlot=%d partyMemberHandle=%016llx membership=%s validMask=%08x evidenceMask=%08x identityHash=%08x identityRevision=%u eventHash=%08x nativeHash=%08x generation=%u lastSeenMs=%lu",
        reason != nullptr ? reason : "unknown",
        i,
        static_cast<unsigned long long>(entry.steam_id),
        static_cast<unsigned long long>(entry.lobby_id),
        static_cast<unsigned long long>(entry.record_key),
        BhrcRecordRoleName(entry.identity.record_role),
        entry.player_index,
        entry.game_data_id,
        entry.party_slot,
        entry.identity.party_member_slot,
        static_cast<unsigned long long>(entry.identity.party_member_handle),
        BhrcIdentityMembershipStateName(entry.identity.membership_state),
        entry.identity.valid_mask,
        entry.identity.evidence_mask,
        entry.identity.identity_hash32,
        entry.identity.snapshot_revision,
        entry.event_record_hash32,
        entry.native_record_hash32,
        entry.generation,
        static_cast<unsigned long>(entry.last_seen_ms));
  }
  for (uint32_t i = 0; i < kBhrcInactiveRecordSlots; ++i) {
    const BhrcSteamRecordCacheEntry& entry = g_bhrc_inactive_record_cache[i];
    if (!entry.valid || entry.steam_id == 0) {
      continue;
    }
    Log(
        "BHRC record_cache_slot reason=%s state=inactive index=%u steamId=%016llx lobby=%016llx recordKey=%016llx recordRole=%s playerIndex=%d gameDataId=%d recordD4Id=%d partyMemberSlot=%d partyMemberHandle=%016llx membership=%s validMask=%08x evidenceMask=%08x identityHash=%08x identityRevision=%u eventHash=%08x nativeHash=%08x generation=%u lastSeenMs=%lu inactiveSinceMs=%lu",
        reason != nullptr ? reason : "unknown",
        i,
        static_cast<unsigned long long>(entry.steam_id),
        static_cast<unsigned long long>(entry.lobby_id),
        static_cast<unsigned long long>(entry.record_key),
        BhrcRecordRoleName(entry.identity.record_role),
        entry.player_index,
        entry.game_data_id,
        entry.party_slot,
        entry.identity.party_member_slot,
        static_cast<unsigned long long>(entry.identity.party_member_handle),
        BhrcIdentityMembershipStateName(entry.identity.membership_state),
        entry.identity.valid_mask,
        entry.identity.evidence_mask,
        entry.identity.identity_hash32,
        entry.identity.snapshot_revision,
        entry.event_record_hash32,
        entry.native_record_hash32,
        entry.generation,
        static_cast<unsigned long>(entry.last_seen_ms),
        static_cast<unsigned long>(entry.inactive_since_ms));
  }
}


// 7a66e71 src/dllmain.cpp:14652
void BhrcSetPhase(BhrcPhase phase, const char* reason) {
  g_bhrc.phase = phase;
  g_bhrc.phase_started_ms = GetTickCount();
  Log(
      "BHRC phase=%s reason=%s nonce=%08x peer=%016llx lobby=%016llx recordKey=%016llx playerIndex=%d gameDataId=%d",
      BhrcPhaseName(phase),
      reason != nullptr ? reason : "unknown",
      g_bhrc.request_nonce,
      static_cast<unsigned long long>(g_bhrc.peer_steam_id),
      static_cast<unsigned long long>(g_bhrc.lobby_id),
      static_cast<unsigned long long>(g_bhrc.record_key),
      g_bhrc.player_index,
      g_bhrc.game_data_id);
}


// 7a66e71 src/dllmain.cpp:14667
void RememberSuppressedTeamSessionDialog(void* state, uint8_t reason, const char* detail) {
  if (state == nullptr || reason == 0) {
    LogWarn(
        "BHRC suppressed_prompt_not_recorded reason=invalid_team_dialog_state detail=%s state=%p dialogReason=%u",
        detail != nullptr ? detail : "unknown",
        state,
        reason);
    return;
  }
  g_bhrc.suppressed_team_dialog_valid = true;
  g_bhrc.suppressed_failure_prompt_shown = false;
  g_bhrc.suppressed_team_dialog_state = state;
  g_bhrc.suppressed_team_dialog_reason = reason;
  g_bhrc.suppressed_team_dialog_ms = GetTickCount();
  Log(
      "BHRC suppressed_prompt_recorded type=team_session detail=%s state=%p reason=%u reasonName=%s",
      detail != nullptr ? detail : "unknown",
      state,
      reason,
      TeamSessionDialogReasonName(reason));
}


// 7a66e71 src/dllmain.cpp:14689
bool ShowFixedTeamSessionFailurePrompt(uint8_t reason, const char* failure, const char* detail) {
  const bool dialogue_text = reason == 1 || reason == 6 || reason == 7;
  auto build_text = ResolveNative<TextByIdFn>(
      dialogue_text ? kDialogueTextByIdRva : kSystemMessageTextByIdRva);
  auto show_text = ResolveNative<DialogShowTextFn>(kDialogShowTextRva);
  const uint32_t text_id = TeamSessionDialogTextIdForReason(reason);
  if (build_text == nullptr || show_text == nullptr || text_id == 0) {
    LogWarn(
        "BHRC suppressed_prompt_fixed_skip reason=native_missing failure=%s detail=%s dialogReason=%u textId=%08x buildText=%p showText=%p",
        failure != nullptr ? failure : "unknown",
        detail != nullptr ? detail : "unknown",
        reason,
        text_id,
        reinterpret_cast<void*>(build_text),
        reinterpret_cast<void*>(show_text));
    return false;
  }

  alignas(16) uint8_t text_buffer[0x80]{};
  alignas(16) uint8_t dialog_buffer[0x80]{};
  bool ok = false;
  __try {
    void* text = build_text(text_buffer, text_id);
    show_text(dialog_buffer, text);
    ok = true;
  } __except (LogSehException("BHRC suppressed_prompt_fixed_text", GetExceptionInformation())) {
    ok = false;
  }
  Log(
      "BHRC suppressed_prompt_fixed_text ok=%d failure=%s detail=%s reason=%u reasonName=%s textId=%08x resolver=%s buildText=%p showText=%p",
      ok ? 1 : 0,
      failure != nullptr ? failure : "unknown",
      detail != nullptr ? detail : "unknown",
      reason,
      TeamSessionDialogReasonName(reason),
      text_id,
      dialogue_text ? "Dialogue" : "SystemMessage",
      reinterpret_cast<void*>(build_text),
      reinterpret_cast<void*>(show_text));
  return ok;
}


// 7a66e71 src/dllmain.cpp:14731
void ReplaySuppressedMatchedPlayersUiAfterReconnectFailure(BhrcRejectReason reason, const char* detail) {
  if (IsLocalNrscHost() ||
      !g_bhrc.suppressed_team_dialog_valid ||
      g_bhrc.suppressed_failure_prompt_shown ||
      g_bhrc.suppressed_team_dialog_reason == 0) {
    Log(
        "BHRC suppressed_prompt_replay_skip reason=%s detail=%s localHost=%d promptValid=%d alreadyShown=%d state=%p dialogReason=%u",
        BhrcRejectReasonName(reason),
        detail != nullptr ? detail : "unknown",
        IsLocalNrscHost() ? 1 : 0,
        g_bhrc.suppressed_team_dialog_valid ? 1 : 0,
        g_bhrc.suppressed_failure_prompt_shown ? 1 : 0,
        g_bhrc.suppressed_team_dialog_state,
        g_bhrc.suppressed_team_dialog_reason);
    return;
  }

  const DWORD age_ms = GetTickCount() - g_bhrc.suppressed_team_dialog_ms;
  if (age_ms > 60000) {
    LogWarn(
        "BHRC suppressed_prompt_replay_skip reason=stale_prompt detail=%s failure=%s ageMs=%lu state=%p dialogReason=%u",
        detail != nullptr ? detail : "unknown",
        BhrcRejectReasonName(reason),
        static_cast<unsigned long>(age_ms),
        g_bhrc.suppressed_team_dialog_state,
        g_bhrc.suppressed_team_dialog_reason);
    return;
  }

  g_bhrc.suppressed_failure_prompt_shown = true;
  Log(
      "BHRC suppressed_prompt_replay type=fixed_text failure=%s detail=%s ageMs=%lu state=%p reason=%u reasonName=%s",
      BhrcRejectReasonName(reason),
      detail != nullptr ? detail : "unknown",
      static_cast<unsigned long>(age_ms),
      g_bhrc.suppressed_team_dialog_state,
      g_bhrc.suppressed_team_dialog_reason,
      TeamSessionDialogReasonName(g_bhrc.suppressed_team_dialog_reason));
  ShowFixedTeamSessionFailurePrompt(
      g_bhrc.suppressed_team_dialog_reason,
      BhrcRejectReasonName(reason),
      detail);
}


// 7a66e71 src/dllmain.cpp:14775
void BhrcFail(BhrcRejectReason reason, const char* detail) {
  g_bhrc.last_error = reason;
  g_bhrc.phase = BhrcPhase::Failed;
  g_bhrc.phase_started_ms = GetTickCount();
  LogWarn(
      "BHRC failed reason=%s detail=%s nonce=%08x peer=%016llx lobby=%016llx recordKey=%016llx playerIndex=%d gameDataId=%d",
      BhrcRejectReasonName(reason),
      detail != nullptr ? detail : "unknown",
      g_bhrc.request_nonce,
      static_cast<unsigned long long>(g_bhrc.peer_steam_id),
      static_cast<unsigned long long>(g_bhrc.lobby_id),
      static_cast<unsigned long long>(g_bhrc.record_key),
      g_bhrc.player_index,
      g_bhrc.game_data_id);
  LogBhrcSessionRecords("failure_snapshot", ReadGameGlobalPtr(kNetModeManagerPtrRva), g_bhrc.record_key);
  LogBhrcRecordCacheSummary("failure_snapshot");
  ReplaySuppressedMatchedPlayersUiAfterReconnectFailure(reason, detail);
}


// 7a66e71 src/dllmain.cpp:14794
bool LoadPersistedReconnectIdentity(PersistedReconnectIdentity* out) {
  if (out == nullptr) {
    return false;
  }
  wchar_t path[MAX_PATH]{};
  if (!BuildReconnectStatePath(path, MAX_PATH)) {
    return false;
  }
  BhrcStateFileGuard state_file_guard(false);
  PersistedReconnectIdentity id{};
  id.record_key = ReadIniU64(path, L"Reconnect", L"recordKey", 0);
  id.player_index = ReadIniI32(path, L"Reconnect", L"playerIndex", -1);
  id.game_data_id = ReadIniI32(path, L"Reconnect", L"gameDataId", -1);
  id.party_slot =
      ReadIniI32(path, L"Reconnect", L"recordD4Id", -1);
  id.record_hash32 = static_cast<uint32_t>(ReadIniU64(path, L"Reconnect", L"recordHash32", 0));
  id.generation = static_cast<uint32_t>(ReadIniU64(path, L"Reconnect", L"generation", 0));
  id.host_steam_id = ReadIniU64(path, L"Reconnect", L"hostSteamId", 0);
  id.lobby_id = ReadIniU64(path, L"Reconnect", L"lobbyId", 0);
  id.master_lobby_id = ReadIniU64(path, L"Reconnect", L"masterLobbyId", 0);
  id.record_role = static_cast<uint32_t>(
      ReadIniU64(path, L"Reconnect", L"recordRole", 0));
  *out = id;
  return id.record_key != 0 || id.host_steam_id != 0 || id.lobby_id != 0;
}


// 7a66e71 src/dllmain.cpp:14820
const char* BhrcRecordRoleName(uint32_t role) {
  if (role == kBhrcRecordRoleSelf) {
    return "self";
  }
  return role == kBhrcRecordRoleRemote ? "remote" : "unknown";
}


// 7a66e71 src/dllmain.cpp:14827
bool PersistReconnectIdentity(
    const PersistedReconnectIdentity& id,
    const char* reason) {
  wchar_t path[MAX_PATH]{};
  if (!BuildReconnectStatePath(path, MAX_PATH)) {
    return false;
  }
  BhrcStateFileGuard state_file_guard(true);
  WriteIniU64Hex(path, L"Reconnect", L"recordKey", id.record_key);
  WriteIniI32(
      path, L"Reconnect", L"schemaVersion",
      static_cast<int32_t>(kBhrcPlayerIdentitySnapshotSchemaVersion));
  WriteIniI32(path, L"Reconnect", L"playerIndex", id.player_index);
  WriteIniI32(path, L"Reconnect", L"gameDataId", id.game_data_id);
  WriteIniI32(path, L"Reconnect", L"recordD4Id", id.party_slot);
  WriteIniU64Hex(path, L"Reconnect", L"recordHash32", id.record_hash32);
  WriteIniU64Hex(path, L"Reconnect", L"generation", id.generation);
  WriteIniU64Hex(path, L"Reconnect", L"hostSteamId", id.host_steam_id);
  WriteIniU64Hex(path, L"Reconnect", L"lobbyId", id.lobby_id);
  WriteIniU64Hex(path, L"Reconnect", L"masterLobbyId", id.master_lobby_id);
  WriteIniU64Hex(path, L"Reconnect", L"recordRole", id.record_role);
  // The Win32 profile API returns zero for this cache-flush form even when the
  // flush is successful.  Verify the durable generation by exact readback.
  WritePrivateProfileStringW(nullptr, nullptr, nullptr, path);
  const bool committed =
      ReadIniU64(path, L"Reconnect", L"recordKey", 0) == id.record_key &&
      ReadIniI32(path, L"Reconnect", L"playerIndex", -1) ==
          id.player_index &&
      ReadIniI32(path, L"Reconnect", L"gameDataId", -1) ==
          id.game_data_id &&
      ReadIniI32(path, L"Reconnect", L"recordD4Id", -1) == id.party_slot &&
      static_cast<uint32_t>(
          ReadIniU64(path, L"Reconnect", L"recordHash32", 0)) ==
          id.record_hash32 &&
      static_cast<uint32_t>(
          ReadIniU64(path, L"Reconnect", L"generation", 0)) ==
          id.generation &&
      ReadIniU64(path, L"Reconnect", L"hostSteamId", 0) ==
          id.host_steam_id &&
      ReadIniU64(path, L"Reconnect", L"lobbyId", 0) == id.lobby_id &&
      ReadIniU64(path, L"Reconnect", L"masterLobbyId", 0) ==
          id.master_lobby_id &&
      static_cast<uint32_t>(
          ReadIniU64(path, L"Reconnect", L"recordRole", 0)) ==
          id.record_role;
  if (!committed) {
    LogWarn(
        "BHRC identity_save_failed reason=%s masterLobbyA=%016llx expeditionLobbyB=%016llx host=%016llx recordKey=%016llx generation=%u recordHash=%08x readbackExact=0",
        reason != nullptr ? reason : "unknown",
        static_cast<unsigned long long>(id.master_lobby_id),
        static_cast<unsigned long long>(id.lobby_id),
        static_cast<unsigned long long>(id.host_steam_id),
        static_cast<unsigned long long>(id.record_key),
        id.generation,
        id.record_hash32);
    return false;
  }
  Log(
      "BHRC identity_saved reason=%s schemaVersion=%u masterLobbyA=%016llx expeditionLobbyB=%016llx host=%016llx recordKey=%016llx recordRole=%s playerIndex=%d gameDataId=%d recordD4Id=%d recordHash=%08x generation=%u",
      reason != nullptr ? reason : "unknown",
      kBhrcPlayerIdentitySnapshotSchemaVersion,
      static_cast<unsigned long long>(id.master_lobby_id),
      static_cast<unsigned long long>(id.lobby_id),
      static_cast<unsigned long long>(id.host_steam_id),
      static_cast<unsigned long long>(id.record_key),
      BhrcRecordRoleName(id.record_role),
      id.player_index,
      id.game_data_id,
      id.party_slot,
      id.record_hash32,
      id.generation);
  return true;
}


// 7a66e71 src/dllmain.cpp:14901
bool GetSessionRecordBounds(void* session_mgr, SessionRecordBounds* out) {
  if (out != nullptr) {
    *out = SessionRecordBounds{};
  }
  if (session_mgr == nullptr) {
    return false;
  }
  const uint64_t begin = ReadU64(static_cast<const uint8_t*>(session_mgr) + 0x78, 0);
  const uint64_t end = ReadU64(static_cast<const uint8_t*>(session_mgr) + 0x80, 0);
  if (begin == 0 || end < begin) {
    return false;
  }
  const uint64_t bytes = end - begin;
  if (bytes > kNetPeerRecordSize * 64ull || (bytes % kNetPeerRecordSize) != 0) {
    return false;
  }
  if (out != nullptr) {
    out->begin = reinterpret_cast<const uint8_t*>(begin);
    out->end = reinterpret_cast<const uint8_t*>(end);
    out->bytes = bytes;
    out->count = static_cast<uint32_t>(bytes / kNetPeerRecordSize);
  }
  return true;
}


// 7a66e71 src/dllmain.cpp:14926
const uint8_t* FindSessionRecordByKey(void* session_mgr, uint64_t record_key) {
  if (record_key == 0) {
    return nullptr;
  }
  SessionRecordBounds bounds{};
  if (!GetSessionRecordBounds(session_mgr, &bounds)) {
    return nullptr;
  }
  for (const uint8_t* cursor = bounds.begin; cursor + kNetPeerRecordSize <= bounds.end; cursor += kNetPeerRecordSize) {
    const uint64_t key = ReadU64(cursor + 0x10, 0);
    if (key == record_key) {
      return cursor;
    }
  }
  return nullptr;
}


// 7a66e71 src/dllmain.cpp:14943
uint32_t CountSessionRecords(void* session_mgr) {
  SessionRecordBounds bounds{};
  if (!GetSessionRecordBounds(session_mgr, &bounds)) {
    return 0;
  }
  return bounds.count;
}


