// 7a66e71 src/dllmain.cpp:17748
void ObserveNativeExplicitLobbyCandidate(
    uint64_t lobby_id, uintptr_t caller_rva, int operation_result) {
  if (lobby_id == 0 ||
      caller_rva != kNativeOperationExplicitPayloadCallerReturnRva ||
      operation_result == 0) {
    return;
  }
  const uint64_t master_lobby = GetSavedNrscMasterLobbyId();
  if (master_lobby != 0 && lobby_id == master_lobby) {
    Log(
        "BHRC native_lobby_candidate payloadLobby=%016llx masterA=%016llx callerRva=%llx operationToken=%08x submissionAccepted=1 classification=transport_master_A stateMutation=0",
        static_cast<unsigned long long>(lobby_id),
        static_cast<unsigned long long>(master_lobby),
        static_cast<unsigned long long>(caller_rva),
        static_cast<unsigned int>(operation_result));
    return;
  }
  Log(
      "BHRC native_lobby_candidate payloadLobby=%016llx masterA=%016llx callerRva=%llx operationToken=%08x submissionAccepted=1 classification=unverified_explicit_payload stateMutation=0 authority=persisted_old_player_tuple_only",
      static_cast<unsigned long long>(lobby_id),
      static_cast<unsigned long long>(master_lobby),
      static_cast<unsigned long long>(caller_rva),
      static_cast<unsigned int>(operation_result));
}


