// 7a66e71 src/dllmain.cpp:18642
void PublishBhrcOldMemberMatchingFence(
    BhrcOldMemberMatchingFenceKind kind,
    uint32_t source_nonce,
    uint64_t master_lobby_id,
    uint64_t expedition_lobby_id,
    uint64_t host_steam_id,
    uint64_t record_key,
    uint32_t client_generation,
    uint32_t identity_hash32,
    uint64_t authority_commit_seq,
    uint32_t manager_id,
    const char* reason) {
  if (kind == BhrcOldMemberMatchingFenceKind::None ||
      master_lobby_id == 0 || expedition_lobby_id == 0 ||
      host_steam_id == 0 || record_key == 0 || client_generation == 0 ||
      identity_hash32 == 0) {
    return;
  }
  BhrcOldMemberMatchingFence next{};
  next.valid = true;
  next.kind = kind;
  next.source_nonce = source_nonce;
  next.client_generation = client_generation;
  next.identity_hash32 = identity_hash32;
  next.manager_id = manager_id;
  next.master_lobby_id = master_lobby_id;
  next.expedition_lobby_id = expedition_lobby_id;
  next.host_steam_id = host_steam_id;
  next.record_key = record_key;
  next.authority_commit_seq = authority_commit_seq;
  next.published_tick_ms = GetTickCount64();
  AcquireSRWLockExclusive(&g_bhrc_old_member_matching_fence_lock);
  g_bhrc_old_member_matching_fence = next;
  ReleaseSRWLockExclusive(&g_bhrc_old_member_matching_fence_lock);
  Log(
      "BHRC active_friend_admission edge=old_member_matching_fence outcome=published kind=%s reason=%s nonce=%08x masterA=%016llx expeditionB=%016llx host=%016llx recordKey=%016llx generation=%u identityHash=%08x authoritySeq=%llu managerId=%08x matchingRoute7=0 nativePointerStored=0",
      BhrcOldMemberMatchingFenceKindName(kind),
      reason != nullptr ? reason : "unknown", source_nonce,
      static_cast<unsigned long long>(master_lobby_id),
      static_cast<unsigned long long>(expedition_lobby_id),
      static_cast<unsigned long long>(host_steam_id),
      static_cast<unsigned long long>(record_key), client_generation,
      identity_hash32,
      static_cast<unsigned long long>(authority_commit_seq), manager_id);
}


