bool ClearBhrcOldMemberMatchingFenceForTransport(
    uint64_t master_lobby_id,
    uint64_t host_steam_id,
    uint64_t record_key,
    const char* reason) {
  BhrcOldMemberMatchingFence retired{};
  bool cleared = false;
  AcquireSRWLockExclusive(&g_bhrc_old_member_matching_fence_lock);
  if (g_bhrc_old_member_matching_fence.valid && master_lobby_id != 0 &&
      host_steam_id != 0 && record_key != 0 &&
      g_bhrc_old_member_matching_fence.master_lobby_id == master_lobby_id &&
      g_bhrc_old_member_matching_fence.host_steam_id == host_steam_id &&
      g_bhrc_old_member_matching_fence.record_key == record_key) {
    retired = g_bhrc_old_member_matching_fence;
    g_bhrc_old_member_matching_fence = BhrcOldMemberMatchingFence{};
    cleared = true;
  }
  ReleaseSRWLockExclusive(&g_bhrc_old_member_matching_fence_lock);
  if (cleared) {
    Log(
        "BHRC active_friend_admission edge=old_member_matching_fence outcome=cleared kind=%s reason=%s nonce=%08x masterA=%016llx expeditionB=%016llx host=%016llx recordKey=%016llx generation=%u authoritySeq=%llu matchingReleased=1",
        BhrcOldMemberMatchingFenceKindName(retired.kind),
        reason != nullptr ? reason : "unknown", retired.source_nonce,
        static_cast<unsigned long long>(retired.master_lobby_id),
        static_cast<unsigned long long>(retired.expedition_lobby_id),
        static_cast<unsigned long long>(retired.host_steam_id),
        static_cast<unsigned long long>(retired.record_key),
        retired.client_generation,
        static_cast<unsigned long long>(retired.authority_commit_seq));
  }
  return cleared;
}


