// 7a66e71 src/dllmain.cpp:18761
void RebindBhrcOldMemberMatchingFenceNonce(
    const BhrcExpeditionProbeAttempt& before,
    const BhrcExpeditionProbeAttempt& after,
    const char* reason) {
  const bool exact_successor = before.request_nonce != 0 &&
      after.request_nonce != 0 && before.request_nonce != after.request_nonce &&
      before.master_lobby_id == after.master_lobby_id &&
      before.expedition_lobby_id == after.expedition_lobby_id &&
      before.host_steam_id == after.host_steam_id &&
      before.record_key == after.record_key &&
      before.client_generation == after.client_generation &&
      before.identity_hash32 == after.identity_hash32;
  if (!exact_successor) {
    return;
  }
  BhrcOldMemberMatchingFence rebound{};
  bool changed = false;
  AcquireSRWLockExclusive(&g_bhrc_old_member_matching_fence_lock);
  if (g_bhrc_old_member_matching_fence.valid &&
      g_bhrc_old_member_matching_fence.source_nonce == before.request_nonce &&
      g_bhrc_old_member_matching_fence.master_lobby_id ==
          before.master_lobby_id &&
      g_bhrc_old_member_matching_fence.expedition_lobby_id ==
          before.expedition_lobby_id &&
      g_bhrc_old_member_matching_fence.host_steam_id ==
          before.host_steam_id &&
      g_bhrc_old_member_matching_fence.record_key == before.record_key &&
      g_bhrc_old_member_matching_fence.client_generation ==
          before.client_generation &&
      g_bhrc_old_member_matching_fence.identity_hash32 ==
          before.identity_hash32) {
    g_bhrc_old_member_matching_fence.source_nonce = after.request_nonce;
    g_bhrc_old_member_matching_fence.published_tick_ms = GetTickCount64();
    rebound = g_bhrc_old_member_matching_fence;
    changed = true;
  }
  ReleaseSRWLockExclusive(&g_bhrc_old_member_matching_fence_lock);
  if (changed) {
    Log(
        "BHRC active_friend_admission edge=old_member_matching_fence outcome=nonce_rebound kind=%s reason=%s priorNonce=%08x nonce=%08x masterA=%016llx expeditionB=%016llx generation=%u recordKey=%016llx",
        BhrcOldMemberMatchingFenceKindName(rebound.kind),
        reason != nullptr ? reason : "unknown", before.request_nonce,
        after.request_nonce,
        static_cast<unsigned long long>(rebound.master_lobby_id),
        static_cast<unsigned long long>(rebound.expedition_lobby_id),
        rebound.client_generation,
        static_cast<unsigned long long>(rebound.record_key));
  }
}


// 7a66e71 src/dllmain.cpp:18811
void ApplyBhrcOldMemberMatchingFenceForAcceptedProbeResponse(
    const BhrcExpeditionProbeAttempt& before,
    const BhrcExpeditionProbeAttempt& after) {
  if (after.trigger != BhrcExpeditionProbeTrigger::FriendJoin ||
      after.request_nonce == 0 || before.request_nonce != after.request_nonce) {
    return;
  }
  if (after.stage == BhrcExpeditionProbeStage::OrdinaryLobby) {
    ClearBhrcOldMemberMatchingFenceForExactProbe(
        before, "host_confirmed_ordinary_lobby");
    return;
  }
  BhrcOldMemberMatchingFenceKind kind =
      BhrcOldMemberMatchingFenceKind::PendingClassification;
  const char* reason = "host_response_pending_classification";
  if (after.stage == BhrcExpeditionProbeStage::AuthorizedReturning) {
    kind = BhrcOldMemberMatchingFenceKind::AuthorizedReturning;
    reason = "host_authorized_returning_same_B";
  } else if (after.stage == BhrcExpeditionProbeStage::Rejected ||
             after.stage == BhrcExpeditionProbeStage::TimedOut) {
    kind = BhrcOldMemberMatchingFenceKind::FailClosed;
    reason = "host_rejected_old_member_admission";
  }
  const uint64_t expedition_lobby_id = after.expedition_lobby_id != 0
      ? after.expedition_lobby_id
      : before.expedition_lobby_id;
  PublishBhrcOldMemberMatchingFence(
      kind, after.request_nonce, after.master_lobby_id,
      expedition_lobby_id, after.host_steam_id, after.record_key,
      after.client_generation, after.identity_hash32,
      after.authority_commit_seq, after.manager_id, reason);
}


// 7a66e71 src/dllmain.cpp:18867
bool BhrcExpeditionProbeOwnsReconnect() {
  const BhrcExpeditionProbeAttempt probe = SnapshotBhrcExpeditionProbe();
  return !probe.authority_observer_only &&
      probe.trigger != BhrcExpeditionProbeTrigger::None &&
      (IsBhrcExpeditionProbePendingStage(probe.stage) ||
       probe.stage == BhrcExpeditionProbeStage::AuthorizedReturning ||
       probe.stage == BhrcExpeditionProbeStage::HandedOff);
}


// 7a66e71 src/dllmain.cpp:19032
bool ArmBhrcStartupExpeditionProbe(const char* reason) {
  const BhrcStartupHostPreflightAttempt preflight =
      SnapshotBhrcStartupHostPreflight();
  if (preflight.stage !=
          BhrcStartupHostPreflightStage::RunningConfirmed ||
      preflight.request_nonce == 0 || preflight.master_lobby_id == 0 ||
      preflight.persisted_expedition_lobby_id == 0 ||
      preflight.host_steam_id == 0 || preflight.record_key == 0 ||
      preflight.host_steam_id == preflight.record_key ||
      preflight.client_generation == 0 || preflight.identity_hash32 == 0 ||
      preflight.authority_commit_seq == 0 || preflight.manager_id == 0) {
    return false;
  }
  return ArmBhrcExpeditionProbe(
      BhrcExpeditionProbeTrigger::StartupPreviousSession,
      preflight.master_lobby_id,
      preflight.persisted_expedition_lobby_id,
      preflight.host_steam_id, preflight.record_key,
      preflight.client_generation, preflight.identity_hash32, reason);
}


