// 7a66e71 src/dllmain.cpp:21244
bool BhrcOldMemberHandoffOwnsCompetingQuickMatch(
    const BhrcOldMemberHandoffState& handoff) {
  return handoff.stage != BhrcOldMemberHandoffStage::Idle &&
      handoff.stage != BhrcOldMemberHandoffStage::Failed &&
      handoff.observer_nonce != 0 && handoff.master_lobby_id != 0 &&
      handoff.expedition_lobby_id != 0 && handoff.host_steam_id != 0 &&
      handoff.record_key != 0;
}


// 7a66e71 src/dllmain.cpp:21253
bool BhrcOldMemberMatchingFirewallActiveForSnapshots(
    const BhrcOldMemberHandoffState& handoff,
    const BhrcOldMemberMatchingFence& fence) {
  // Do not derive this ownership from the current probe stage, peer-active bit
  // or admission TTL. Those are transport lifecycle facts and all rotate while
  // the native previous-session owner remains authoritative. The independent
  // scalar fence is published before the asynchronous host classification and
  // retired only by an exact ordinary result/world completion.
  return BhrcOldMemberHandoffOwnsCompetingQuickMatch(handoff) ||
      BhrcOldMemberMatchingFenceMatchesCurrent(fence);
}


// 7a66e71 src/dllmain.cpp:21286
const char* BhrcOldMemberMatchingFirewallReason(
    const BhrcOldMemberHandoffState& handoff,
    const BhrcExpeditionProbeAttempt& probe,
    const BhrcOldMemberMatchingFence& fence) {
  if (BhrcOldMemberHandoffOwnsCompetingQuickMatch(handoff)) {
    return "previous_session_owner_only";
  }
  if (BhrcOldMemberMatchingFenceMatchesCurrent(fence)) {
    switch (fence.kind) {
      case BhrcOldMemberMatchingFenceKind::PendingClassification:
        return "awaiting_host_classification";
      case BhrcOldMemberMatchingFenceKind::AuthorizedReturning:
        return "authorized_returning_generation";
      case BhrcOldMemberMatchingFenceKind::FailClosed:
        return "host_classified_fail_closed";
      case BhrcOldMemberMatchingFenceKind::None:
      default:
        break;
    }
  }
  (void)probe;
  return "old_member_firewall";
}


