// 7a66e71 src/dllmain.cpp:21596
uint32_t ReadBhrcQuickMatchControllerStep(void* controller) {
  if (controller == nullptr) {
    return 0xffffffffu;
  }
  const uint64_t vtable = ReadU64(controller, 0);
  const uint64_t getter = vtable != 0
      ? ReadU64(reinterpret_cast<const void*>(vtable + 0x50), 0)
      : 0;
  if (getter == 0) {
    return 0xffffffffu;
  }
  uint32_t step = 0xffffffffu;
  __try {
    using StateGetterFn = uint32_t(__fastcall*)(void*);
    step = reinterpret_cast<StateGetterFn>(getter)(controller);
  } __except (LogSehException(
      "BHRC QuickMatch controller state getter", GetExceptionInformation())) {
    step = 0xffffffffu;
  }
  return step;
}


