// 7a66e71 src/dllmain.cpp:23130
void QueueBhrcOldMemberFailClosed(
    uint32_t observer_nonce,
    const char* reason) {
  BhrcOldMemberHandoffState state{};
  AcquireSRWLockExclusive(&g_bhrc_old_member_handoff_lock);
  if (observer_nonce == 0 ||
      g_bhrc_old_member_handoff.observer_nonce == observer_nonce) {
    g_bhrc_old_member_handoff.stage =
        BhrcOldMemberHandoffStage::FailClosedPending;
    // A prior successful cancel happened before adapter submission.  If the
    // adapter partially started native work, fail-closed must issue a fresh
    // original cancel for that new owner generation.
    g_bhrc_old_member_handoff.cancel_called = false;
    g_bhrc_old_member_handoff.stage_tick_ms = GetTickCount64();
  }
  state = g_bhrc_old_member_handoff;
  ReleaseSRWLockExclusive(&g_bhrc_old_member_handoff_lock);
  LogWarn(
      "BHRC active_friend_admission edge=old_member_handoff_fail_closed reason=%s stage=%s observerNonce=%08x activeNonce=%08x masterA=%016llx expeditionB=%016llx authoritySeq=%llu managerId=%08x matchingOriginalCall=0",
      reason != nullptr ? reason : "unknown",
      BhrcOldMemberHandoffStageName(state.stage), state.observer_nonce,
      state.active_nonce,
      static_cast<unsigned long long>(state.master_lobby_id),
      static_cast<unsigned long long>(state.expedition_lobby_id),
      static_cast<unsigned long long>(state.authority_commit_seq),
      state.manager_id);
}


