// 7a66e71 src/dllmain.cpp:24081
void __fastcall HookNativeMainGameUpdate(void* game, void* frame) {
  if (g_native_main_game_update == nullptr) {
    LogError("BHRC FUN_140c3a900 original missing game=%p frame=%p", game, frame);
    return;
  }
  ObserveBhrcPersistentSessionDescriptorLifecycle("main_update_pre_original");
  TryRestoreBhrcAuthorizedNativeDescriptor();
  TryBeginBhrcAuthorizedOldMemberHandoff();
  ResolveBhrcHeldQuickMatchFinalizer();
  if (TryPublishBhrcAuthorizedReturningAuthorityCandidate()) {
    TryCommitPendingNativeExpeditionAuthority();
  }
  const bool previous_seed_applied = g_bhrc_full_pgd_seed_applied_this_update;
  g_bhrc_full_pgd_seed_applied_this_update = false;
  TryApplyBhrcFullPgdRestoreMainThread(false);
  __try {
    g_native_main_game_update(game, frame);
  } __except (LogSehException(
      "BHRC FUN_140c3a900 original", GetExceptionInformation())) {
    LogError(
        "BHRC FUN_140c3a900 original_exception game=%p frame=%p", game,
        frame);
    g_bhrc_full_pgd_seed_applied_this_update = previous_seed_applied;
    return;
  }
  // Keep the proven 7f7a5c4 boundary exact: the final PGD replay must be the
  // first operation after the original update returns.  In particular, do not
  // sample PGD or NR6PF state in this timing-sensitive gap.
  TryApplyBhrcFullPgdRestoreMainThread(true);
  g_bhrc_full_pgd_seed_applied_this_update = previous_seed_applied;
  ExpireBhrcFullPgdRestoreWindowMainThread();
  LogNr6pfAliveFlagsIfDueMainThread();
  ResolveBhrcHeldQuickMatchFinalizer();
  ObserveBhrcPersistentSessionDescriptorLifecycle("main_update_post_original");
  ProcessBhrcNativeDescriptorPersistence();
  TryRestoreBhrcAuthorizedNativeDescriptor();
  TryBeginBhrcAuthorizedOldMemberHandoff();
  ProcessBhrcAuthorizedOldMemberHandoff();
  CaptureBhrcLocalFullPgdMainThread();
  TraceBhrcEffectsAfterWorldMainThread();
}


// 7a66e71 src/dllmain.cpp:24214
bool LoadBhrcStartupReconnectCandidate(
    PersistedReconnectIdentity* identity_out,
    uint64_t* host_candidates_out,
    uint32_t host_candidate_capacity,
    uint32_t* host_candidate_count_out) {
  if (identity_out != nullptr) {
    *identity_out = PersistedReconnectIdentity{};
  }
  if (host_candidate_count_out != nullptr) {
    *host_candidate_count_out = 0;
  }

  PersistedReconnectIdentity reconnect{};
  const bool reconnect_loaded =
      LoadPersistedReconnectIdentity(&reconnect);
  wchar_t path[MAX_PATH]{};
  if (!BuildReconnectStatePath(path, _countof(path))) {
    return false;
  }

  PersistedReconnectIdentity identity{};
  uint64_t candidates[kBhrcStartupHostCandidateCapacity]{};
  uint32_t candidate_count = 0;
  const auto add_candidate = [&](uint64_t steam_id) {
    if (steam_id == 0 || steam_id == identity.record_key) {
      return;
    }
    for (uint32_t i = 0; i < candidate_count; ++i) {
      if (candidates[i] == steam_id) {
        return;
      }
    }
    if (candidate_count < kBhrcStartupHostCandidateCapacity) {
      candidates[candidate_count++] = steam_id;
    }
  };

  BhrcStateFileGuard state_file_guard(false);
  const uint64_t transport_master =
      ReadIniU64(path, L"Transport", L"masterLobbyId", 0);
  const uint64_t transport_b =
      ReadIniU64(path, L"Transport", L"expeditionLobbyId", 0);
  const uint64_t persisted_local =
      ReadIniU64(path, L"Transport", L"localSteamId", 0);
  const uint64_t runtime_local =
      g_nrsc_steam_control_state.local_steam_id;
  const uint64_t local = runtime_local != 0 ? runtime_local : persisted_local;
  if (transport_master == 0 || transport_b == 0 ||
      transport_master == transport_b || local == 0) {
    return false;
  }

  const bool reconnect_current = reconnect_loaded &&
      reconnect.record_role == kBhrcRecordRoleSelf &&
      reconnect.record_key == local && reconnect.generation != 0 &&
      reconnect.record_hash32 != 0 &&
      reconnect.master_lobby_id == transport_master &&
      reconnect.lobby_id == transport_b;
  if (reconnect_current) {
    identity = reconnect;
  } else {
    wchar_t self_section[40]{};
    BuildReconnectRecordSection(
        local, self_section, _countof(self_section));
    identity.record_key =
        ReadIniU64(path, self_section, L"recordKey", 0);
    identity.player_index =
        ReadIniI32(path, self_section, L"playerIndex", -1);
    identity.game_data_id =
        ReadIniI32(path, self_section, L"gameDataId", -1);
    identity.party_slot =
        ReadIniI32(path, self_section, L"recordD4Id", -1);
    identity.record_hash32 = static_cast<uint32_t>(
        ReadIniU64(path, self_section, L"recordHash32", 0));
    identity.generation = static_cast<uint32_t>(
        ReadIniU64(path, self_section, L"generation", 0));
    identity.record_role = static_cast<uint32_t>(
        ReadIniU64(path, self_section, L"recordRole", 0));
    identity.master_lobby_id = transport_master;
    identity.lobby_id = transport_b;
  }
  if (identity.record_key != local || identity.generation == 0 ||
      identity.record_hash32 == 0 ||
      identity.record_role != kBhrcRecordRoleSelf) {
    return false;
  }
  identity.master_lobby_id = transport_master;
  identity.lobby_id = transport_b;

  if (reconnect_loaded && reconnect.master_lobby_id == transport_master &&
      reconnect.lobby_id == transport_b) {
    add_candidate(reconnect.host_steam_id);
  }
  add_candidate(ReadIniU64(path, L"Transport", L"ownerSteamId", 0));

  wchar_t section_names[8192]{};
  const DWORD section_chars = GetPrivateProfileSectionNamesW(
      section_names, static_cast<DWORD>(_countof(section_names)), path);
  if (section_chars >= _countof(section_names) - 2) {
    return false;
  }
  for (const wchar_t* section = section_names;
       section != nullptr && *section != L'\0';
       section += wcslen(section) + 1) {
    if (_wcsnicmp(section, L"Record_", 7) != 0) {
      continue;
    }
    const uint64_t steam_id =
        ReadIniU64(path, section, L"steamId", 0);
    const uint64_t record_key =
        ReadIniU64(path, section, L"recordKey", 0);
    const uint64_t lobby_id =
        ReadIniU64(path, section, L"lobbyId", 0);
    if (steam_id != 0 && steam_id == record_key &&
        steam_id != local && lobby_id == transport_b) {
      add_candidate(steam_id);
    }
  }
  if (candidate_count == 0) {
    return false;
  }

  identity.host_steam_id = candidates[0];
  const BhrcStartupHostPreflightAttempt active_preflight =
      SnapshotBhrcStartupHostPreflight();
  const bool same_active_identity = active_preflight.request_nonce != 0 &&
      active_preflight.stage != BhrcStartupHostPreflightStage::Idle &&
      active_preflight.master_lobby_id == identity.master_lobby_id &&
      active_preflight.persisted_expedition_lobby_id == identity.lobby_id &&
      active_preflight.record_key == identity.record_key &&
      active_preflight.client_generation == identity.generation &&
      active_preflight.identity_hash32 == identity.record_hash32 &&
      active_preflight.host_steam_id != 0;
  if (same_active_identity) {
    identity.host_steam_id = active_preflight.host_steam_id;
  }

  if (host_candidates_out != nullptr && host_candidate_capacity != 0) {
    const uint32_t copy_count =
        candidate_count < host_candidate_capacity
        ? candidate_count
        : host_candidate_capacity;
    std::memcpy(
        host_candidates_out, candidates,
        sizeof(uint64_t) * copy_count);
  }
  if (host_candidate_count_out != nullptr) {
    *host_candidate_count_out = candidate_count;
  }
  if (identity_out != nullptr) {
    *identity_out = identity;
  }
  return true;
}


// 7a66e71 src/dllmain.cpp:24369
uint64_t __fastcall HookNativeTitleOnlineModeSelector() {
  const uintptr_t caller_rva = RvaOf(_ReturnAddress());
  uint64_t original_result = 0;
  if (g_native_title_online_mode_selector != nullptr) {
    __try {
      original_result = g_native_title_online_mode_selector();
    } __except (LogSehException(
        "BHRC FUN_140f8c330 original", GetExceptionInformation())) {
      return 0;
    }
  }
  if (caller_rva != kNativeTitleOnlineModeContextInitReturnRva ||
      !g_config.enable_nrsc_steam_control) {
    return original_result;
  }
  if ((original_result & 0xffu) != 0) {
    return original_result;
  }

  PersistedReconnectIdentity identity{};
  if (!LoadBhrcStartupReconnectCandidate(&identity) ||
      !IsBhrcOldMemberRouteReady() ||
      !ResolveBhrcStartupP2PTransport(
          "native_title_online_mode_selector")) {
    return original_result;
  }

  Log(
      "BHRC startup_title_search edge=online_mode_selector source=steam_legacy_p2p result=1 caller=%llx masterA=%016llx expeditionB=%016llx host=%016llx recordKey=%016llx nativeStateMutation=0 attemptArmed=0 next=original_title_online_graph_gate",
      static_cast<unsigned long long>(caller_rva),
      static_cast<unsigned long long>(identity.master_lobby_id),
      static_cast<unsigned long long>(identity.lobby_id),
      static_cast<unsigned long long>(identity.host_steam_id),
      static_cast<unsigned long long>(identity.record_key));
  return original_result | 1u;
}


