uint64_t* PublishBhrcNativeTitleMenuResult(
    uint64_t* out_result,
    uint32_t result,
    const char* edge) {
  if (out_result == nullptr) {
    return nullptr;
  }
  __try {
    *out_result = static_cast<uint64_t>(result);
  } __except (LogSehException(
      edge != nullptr ? edge : "BHRC startup title result publish",
      GetExceptionInformation())) {
    LogError(
        "BHRC startup_title_search edge=result_publish_exception owner=%s result=%u out=%p",
        edge != nullptr ? edge : "unknown", result, out_result);
  }
  return out_result;
}


// 7a66e71 src/dllmain.cpp:24425
uint64_t* InvokeBhrcNativeTitleOnlineGraphGate(
    NativeTitleMenuResultFn original,
    void* functor,
    uint64_t* out_result,
    const char* native_name,
    const char* edge) {
  if (original == nullptr) {
    return out_result;
  }

  uint64_t* result = out_result;
  __try {
    result = original(functor, out_result);
  } __except (LogSehException(
      native_name != nullptr ? native_name : "BHRC native title online gate",
      GetExceptionInformation())) {
    LogError(
        "BHRC startup_title_search edge=%s outcome=original_exception functor=%p out=%p",
        edge != nullptr ? edge : "online_graph_gate",
        functor,
        out_result);
    return out_result;
  }

  uint64_t* result_storage = result != nullptr ? result : out_result;
  if (result_storage == nullptr) {
    return result;
  }
  uint64_t original_result = 0;
  __try {
    original_result = *result_storage;
  } __except (LogSehException(
      "BHRC native title online gate result read",
      GetExceptionInformation())) {
    return result;
  }
  if (static_cast<uint32_t>(original_result) != 3 ||
      !g_config.enable_nrsc_steam_control) {
    return result;
  }

  PersistedReconnectIdentity identity{};
  if (!LoadBhrcStartupReconnectCandidate(&identity) ||
      !IsBhrcOldMemberRouteReady() ||
      !ResolveBhrcStartupP2PTransport(
          edge != nullptr ? edge : "native_title_online_graph_gate")) {
    return result;
  }

  Log(
      "BHRC startup_title_search edge=%s source=steam_legacy_p2p originalResult=3 result=2 masterA=%016llx expeditionB=%016llx host=%016llx recordKey=%016llx generation=%u identityHash=%08x nativeStateMutation=0 attemptArmed=0 packetSent=0 next=original_title_descriptor_gate",
      edge != nullptr ? edge : "online_graph_gate",
      static_cast<unsigned long long>(identity.master_lobby_id),
      static_cast<unsigned long long>(identity.lobby_id),
      static_cast<unsigned long long>(identity.host_steam_id),
      static_cast<unsigned long long>(identity.record_key),
      identity.generation,
      identity.record_hash32);
  return PublishBhrcNativeTitleMenuResult(
      result_storage,
      2,
      native_name != nullptr ? native_name
                             : "BHRC native title online gate result");
}


