bool HasBhrcTitlePostConfirmTraceBit(LONG bit) {
  return (InterlockedCompareExchange(
              &g_bhrc_title_post_confirm_trace_bits, 0, 0) &
          bit) != 0;
}


// 7a66e71 src/dllmain.cpp:25145
void* ReadBhrcTitleContextFromGraphFunctor(void* functor) {
  uint64_t master = 0;
  uint64_t context = 0;
  if (functor == nullptr ||
      !TryReadU64(
          static_cast<const uint8_t*>(functor) + 0x08, &master) ||
      master == 0 ||
      !TryReadU64(
          reinterpret_cast<const void*>(master + 0xde8), &context) ||
      context == 0) {
    return nullptr;
  }
  return reinterpret_cast<void*>(context);
}


// 7a66e71 src/dllmain.cpp:25160
bool ReadBhrcTitleContextTraceFields(
    const void* context,
    uint8_t* confirmed_out,
    uint32_t* state_out,
    uint8_t* disabled_out) {
  if (confirmed_out != nullptr) {
    *confirmed_out = 0xff;
  }
  if (state_out != nullptr) {
    *state_out = UINT32_MAX;
  }
  if (disabled_out != nullptr) {
    *disabled_out = 0xff;
  }
  if (context == nullptr) {
    return false;
  }
  uint8_t confirmed = 0;
  uint32_t state = 0;
  uint8_t disabled = 0;
  const bool readable =
      TryReadU8(
          static_cast<const uint8_t*>(context) + 0x16c, &confirmed) &&
      TryReadU32(
          static_cast<const uint8_t*>(context) + 0x174, &state) &&
      TryReadU8(
          static_cast<const uint8_t*>(context) + 0x1bc, &disabled);
  if (readable) {
    if (confirmed_out != nullptr) {
      *confirmed_out = confirmed;
    }
    if (state_out != nullptr) {
      *state_out = state;
    }
    if (disabled_out != nullptr) {
      *disabled_out = disabled;
    }
  }
  return readable;
}


