// 7a66e71 src/dllmain.cpp:25248
bool BhrcTitlePostConfirmTraceContextMatches(const void* context) {
  const LONG64 expected = InterlockedCompareExchange64(
      &g_bhrc_title_post_confirm_trace_context, 0, 0);
  return context != nullptr && expected != 0 &&
      static_cast<uint64_t>(expected) ==
          reinterpret_cast<uint64_t>(context);
}


// 7a66e71 src/dllmain.cpp:25256
void __fastcall HookNativeTitlePositiveConfirmCallback(void* functor) {
  uint64_t context_value = 0;
  if (functor != nullptr) {
    TryReadU64(
        static_cast<const uint8_t*>(functor) + 0x08, &context_value);
  }
  if (g_native_title_positive_confirm_callback != nullptr) {
    g_native_title_positive_confirm_callback(functor);
  }

  uint32_t nonce = 0;
  uint32_t epoch = 0;
  if (!SnapshotBhrcTitlePostConfirmTrace(&nonce, &epoch)) {
    return;
  }
  const LONG64 prior_context = InterlockedCompareExchange64(
      &g_bhrc_title_post_confirm_trace_context,
      static_cast<LONG64>(context_value), 0);
  const bool context_exact = context_value != 0 &&
      (prior_context == 0 ||
       static_cast<uint64_t>(prior_context) == context_value);
  uint8_t confirmed = 0xff;
  uint32_t state = UINT32_MAX;
  uint8_t disabled = 0xff;
  const bool fields_read = ReadBhrcTitleContextTraceFields(
      reinterpret_cast<void*>(context_value),
      &confirmed, &state, &disabled);
  if (g_native_title_positive_confirm_callback != nullptr &&
      context_exact && fields_read && confirmed == 1) {
    AcquireSRWLockExclusive(&g_bhrc_expedition_probe_lock);
    auto& probe = g_bhrc_expedition_probe;
    if (probe.trigger == BhrcExpeditionProbeTrigger::StartupPreviousSession &&
        probe.stage == BhrcExpeditionProbeStage::AuthorizedReturning &&
        probe.membership == BhrcExpeditionMembership::ReturningSameB &&
        probe.host_phase == BhrcExpeditionHostPhase::RunningExpedition &&
        IsBhrcAuthorizedClientProbe(probe) &&
        !probe.restoring_player_metadata) {
      probe.restoring_player_metadata = true;
    }
    ReleaseSRWLockExclusive(&g_bhrc_expedition_probe_lock);
  }
  ClaimBhrcTitlePostConfirmTraceBit(
      kBhrcTitlePostConfirmTraceConfirmed, &nonce, &epoch);

}


