// 7a66e71 src/dllmain.cpp:25927
bool ValidateBhrcStartupTitleProviderDescriptor(
    const BhrcExpeditionProbeAttempt& probe,
    uint32_t* descriptor_hash_out) {
  if (descriptor_hash_out != nullptr) {
    *descriptor_hash_out = 0;
  }
  BhrcNativeDescriptorSidecar sidecar{};
  if (!LoadBhrcNativeDescriptorSidecar(&sidecar) || !sidecar.valid ||
      sidecar.master_lobby_id != probe.master_lobby_id ||
      sidecar.expedition_lobby_id != probe.expedition_lobby_id ||
      sidecar.host_steam_id != probe.host_steam_id ||
      sidecar.record_key != probe.record_key ||
      sidecar.client_generation != probe.client_generation ||
      sidecar.identity_hash32 != probe.identity_hash32 ||
      sidecar.payload_size != sizeof(uint64_t)) {
    return false;
  }
  const BhrcStartupHostPreflightAttempt preflight =
      SnapshotBhrcStartupHostPreflight();
  uint64_t descriptor_multiplay_session_id = 0;
  std::memcpy(
      &descriptor_multiplay_session_id,
      sidecar.fixed_bytes +
          kBhrcNativeDescriptorMultiplaySessionIdOffset,
      sizeof(descriptor_multiplay_session_id));
  if (!BhrcStartupHostPreflightMatchesProbe(preflight, probe) ||
      descriptor_multiplay_session_id == 0 ||
      descriptor_multiplay_session_id !=
          preflight.multiplay_session_id) {
    return false;
  }

  return IsBhrcStartupNativeDescriptorExact(
      probe, &sidecar, descriptor_hash_out);
}


// 7a66e71 src/dllmain.cpp:25963
bool ValidateBhrcTitlePostConfirmHostAuthority(
    void* title_context,
    uint32_t* nonce_out,
    uint32_t* epoch_out,
    uint8_t* confirmed_out,
    uint32_t* state_out,
    uint8_t* disabled_out,
    BhrcExpeditionProbeAttempt* probe_out,
    uint32_t* descriptor_hash_out) {
  uint8_t confirmed = 0xff;
  uint32_t state = UINT32_MAX;
  uint8_t disabled = 0xff;
  uint32_t nonce = 0;
  uint32_t epoch = 0;
  BhrcStartupHostPreflightAttempt preflight{};
  BhrcExpeditionProbeAttempt probe{};
  uint32_t descriptor_hash32 = 0;
  const bool exact_authorized_post_confirm =
      ReadBhrcTitleContextTraceFields(
          title_context, &confirmed, &state, &disabled) &&
      confirmed == 1 && state == 3 && disabled == 1 &&
      SnapshotBhrcTitlePostConfirmTrace(&nonce, &epoch) &&
      IsBhrcStartupTitleProviderGraphReleased(&preflight) &&
      preflight.request_nonce == nonce &&
      ValidateBhrcStartupTitleAuthority(&probe) &&
      BhrcStartupHostPreflightMatchesProbe(preflight, probe) &&
      ValidateBhrcStartupTitleProviderDescriptor(
          probe, &descriptor_hash32) &&
      descriptor_hash32 != 0;
  if (!exact_authorized_post_confirm) {
    return false;
  }
  if (nonce_out != nullptr) {
    *nonce_out = nonce;
  }
  if (epoch_out != nullptr) {
    *epoch_out = epoch;
  }
  if (confirmed_out != nullptr) {
    *confirmed_out = confirmed;
  }
  if (state_out != nullptr) {
    *state_out = state;
  }
  if (disabled_out != nullptr) {
    *disabled_out = disabled;
  }
  if (probe_out != nullptr) {
    *probe_out = probe;
  }
  if (descriptor_hash_out != nullptr) {
    *descriptor_hash_out = descriptor_hash32;
  }
  return true;
}


// 7a66e71 src/dllmain.cpp:26019
bool SnapshotBhrcTitleOnlineSiblingAttempt(
    LONG required_trace_bits,
    BhrcTitleOnlineSiblingScope* scope_out) {
  if (scope_out == nullptr) {
    return false;
  }
  *scope_out = BhrcTitleOnlineSiblingScope{};
  const LONG trace_bits = InterlockedCompareExchange(
      &g_bhrc_title_post_confirm_trace_bits, 0, 0);
  const LONG64 context_value = InterlockedCompareExchange64(
      &g_bhrc_title_post_confirm_trace_context, 0, 0);
  uint32_t nonce = 0;
  uint32_t epoch = 0;
  uint8_t confirmed = 0xff;
  uint32_t state = UINT32_MAX;
  uint8_t disabled = 0xff;
  BhrcExpeditionProbeAttempt probe{};
  uint32_t descriptor_hash32 = 0;
  if ((trace_bits & required_trace_bits) != required_trace_bits ||
      context_value == 0 ||
      !ValidateBhrcTitlePostConfirmHostAuthority(
          reinterpret_cast<void*>(context_value), &nonce, &epoch,
          &confirmed, &state, &disabled, &probe,
          &descriptor_hash32)) {
    return false;
  }
  const BhrcStartupHostPreflightAttempt preflight =
      SnapshotBhrcStartupHostPreflight();
  if (preflight.request_nonce != nonce ||
      !BhrcStartupHostPreflightMatchesProbe(preflight, probe)) {
    return false;
  }
  scope_out->preflight_nonce = nonce;
  scope_out->formal_probe_nonce = probe.request_nonce;
  scope_out->host_steam_id = probe.host_steam_id;
  scope_out->descriptor_hash32 = descriptor_hash32;
  return true;
}


// 7a66e71 src/dllmain.cpp:26058
bool ReadBhrcLocalCharacterValue(uint32_t* value_out) {
  if (value_out == nullptr) {
    return false;
  }
  *value_out = 0;
  void* const manager =
      ReadGameGlobalPtr(kPlayerGameDataManagerGlobalPtrRva);
  uint64_t local_player = 0;
  if (manager == nullptr ||
      !TryReadU64(
          static_cast<const uint8_t*>(manager) + 0x08,
          &local_player)) {
    return false;
  }
  // FUN_140b43230 submits zero when no local PlayerGameData exists yet.
  // Preserve that original default instead of rejecting the reconnect task.
  return local_player == 0 ||
      TryReadU32(
          reinterpret_cast<const void*>(local_player + 0xec),
          value_out);
}


