// 7a66e71 src/dllmain.cpp:26460
void __fastcall HookNativeTitlePlayerChrLoginCompletion(
    void* native_task) {
  const LONG64 expected_task = InterlockedCompareExchange64(
      &g_bhrc_title_player_chr_login_task, 0, 0);
  if (expected_task == 0 ||
      reinterpret_cast<void*>(expected_task) != native_task) {
    if (g_native_title_player_chr_login_completion != nullptr) {
      g_native_title_player_chr_login_completion(native_task);
    }
    return;
  }

  const auto call_original = [&]() {
    if (g_native_title_player_chr_login_completion == nullptr) {
      return;
    }
    __try {
      g_native_title_player_chr_login_completion(native_task);
    } __except (LogSehException(
        "BHRC FUN_140b431e0 original", GetExceptionInformation())) {
      LogError(
          "BHRC title_online_sibling edge=player_chr_completion outcome=original_exception task=%p",
          native_task);
    }
  };

  const BhrcTitlePlayerChrLoginCompletionBridge bridge =
      SnapshotBhrcTitlePlayerChrLoginBridge();
  if (!bridge.authorized || bridge.native_task != native_task) {
    call_original();
    return;
  }

  constexpr LONG kRequiredTraceBits =
      kBhrcTitlePostConfirmTraceConfirmed |
      kBhrcTitlePostConfirmTraceGraphGate |
      kBhrcTitlePostConfirmTraceTaskResultGate |
      kBhrcTitlePostConfirmTraceJob78;
  BhrcTitleOnlineSiblingScope scope{};
  const bool authority_still_exact =
      SnapshotBhrcTitleOnlineSiblingAttempt(
          kRequiredTraceBits, &scope) &&
      scope.preflight_nonce == bridge.preflight_nonce &&
      scope.formal_probe_nonce == bridge.formal_probe_nonce &&
      scope.host_steam_id == bridge.host_steam_id;
  if (!authority_still_exact) {
    ClearBhrcTitlePlayerChrLoginBridge(native_task);
    call_original();
    InvalidateBhrcStartupAuthorizedLatch(
        bridge.preflight_nonce, bridge.host_steam_id,
        "player_chr_completion_authority_changed");
    LogWarn(
        "BHRC title_online_sibling edge=player_chr_completion outcome=original_failure_preserved reason=authority_changed preflightNonce=%08x formalNonce=%08x task=%p",
        bridge.preflight_nonce, bridge.formal_probe_nonce,
        native_task);
    return;
  }

  const bool applied =
      InvokeBhrcTitlePlayerChrLoginOriginalCompletion(
          native_task, bridge, "native_typed_completion_branch");
  if (!applied) {
    InvalidateBhrcStartupAuthorizedLatch(
        bridge.preflight_nonce, bridge.host_steam_id,
        "player_chr_completion_result_not_applied");
  }
}


