// 7a66e71 src/dllmain.cpp:26697
bool BhrcStartupTitleProviderScopeMatchesProbe(
    const BhrcStartupTitleProviderScopeTls& scope,
    const BhrcExpeditionProbeAttempt& probe) {
  return scope.depth == 1 &&
      scope.formal_probe_nonce == probe.request_nonce &&
      scope.client_generation == probe.client_generation &&
      scope.identity_hash32 == probe.identity_hash32 &&
      scope.master_lobby_id == probe.master_lobby_id &&
      scope.expedition_lobby_id == probe.expedition_lobby_id &&
      scope.host_steam_id == probe.host_steam_id &&
      scope.record_key == probe.record_key &&
      scope.authority_commit_seq == probe.authority_commit_seq &&
      scope.manager_id == probe.manager_id &&
      scope.descriptor_hash32 != 0;
}


// 7a66e71 src/dllmain.cpp:26713
const char* BhrcTitleProviderScopePhaseName(
    BhrcTitleProviderScopePhase phase) {
  switch (phase) {
    case BhrcTitleProviderScopePhase::StartupPreConfirm:
      return "startup_pre_confirm";
    case BhrcTitleProviderScopePhase::PostConfirmJob78:
      return "post_confirm_job78";
    default:
      return "none";
  }
}


