    Log(
        "BHRC startup_title_search edge=check_penalty_result outcome=official_response_applied preflightNonce=%08x formalNonce=%08x task=%p titleManager=%p multiplaySessionId=%016llx descriptorHash=%08x authorityStillExact=%d originalCallback=FUN_145afaf0c nativePollResult=0 next=original_FUN_14088f6a0",
        bridge.preflight_nonce, bridge.formal_probe_nonce,
        bridge.native_task, bridge.title_manager,
        static_cast<unsigned long long>(bridge.multiplay_session_id),
        descriptor_hash32, authority_still_exact ? 1 : 0);
    return 0;
