  // Still pending. Substitute the network fact on the response boundary only,
  // using the same owner pointer the vanilla poll would have used
  // (*(task+0x78), captured at submit time and re-read here).
  uint64_t live_owner = 0;
  const bool owner_exact =
      TryReadU64(
          static_cast<const uint8_t*>(native_task) + 0x78, &live_owner) &&
      live_owner != 0 &&
      reinterpret_cast<void*>(live_owner) == bridge.title_manager;

  BhrcNativeCheckPenaltyResponse response{};
  response.previous_session_available =
      (authority_still_exact && owner_exact) ? 1 : 0;
  bool callback_applied = false;
  if (g_native_title_check_penalty_result_apply != nullptr && owner_exact) {
    __try {
      g_native_title_check_penalty_result_apply(
          bridge.title_manager, &response);
      callback_applied = true;
    } __except (LogSehException(
        "BHRC FUN_145afaf0c P2P result apply",
        GetExceptionInformation())) {
      LogError(
          "BHRC startup_title_search edge=check_penalty_result outcome=callback_exception preflightNonce=%08x formalNonce=%08x task=%p titleManager=%p",
          bridge.preflight_nonce, bridge.formal_probe_nonce,
          bridge.native_task, bridge.title_manager);
    }
  }

  ClearBhrcStartupTitleCheckPenaltyBridge(native_task);
