// 7a66e71 src/dllmain.cpp:33754
void ObserveBhrcExpeditionWorldRegistration(
    void* world_chr_man,
    uint64_t entity_index,
    void* source,
    void* aux) {
  if (world_chr_man == nullptr) {
    return;
  }
  const int32_t local_base_index = GetLocalBaseOwnerIndex(world_chr_man);
  const bool local_base_registration =
      aux == nullptr && local_base_index >= 0 &&
      entity_index == static_cast<uint64_t>(local_base_index) &&
      source == static_cast<uint8_t*>(world_chr_man) + 0x9a40;
  const ULONGLONG now = GetTickCount64();
  AcquireSRWLockExclusive(&g_bhrc_expedition_world_phase_lock);
  ++g_bhrc_expedition_world_phase.registration_seq;
  g_bhrc_expedition_world_phase.last_registration_tick_ms = now;
  g_bhrc_expedition_world_phase.last_registered_world_chr_man = world_chr_man;
  if (local_base_registration) {
    ++g_bhrc_expedition_world_phase.local_base_registration_seq;
    g_bhrc_expedition_world_phase.last_local_base_registration_tick_ms = now;
    g_bhrc_expedition_world_phase.last_local_base_world_chr_man =
        world_chr_man;
    g_bhrc_expedition_world_phase.last_local_base_authority_seq =
        g_bhrc_expedition_world_phase.authority_commit_seq;
  }
  ReleaseSRWLockExclusive(&g_bhrc_expedition_world_phase_lock);
}


// 7a66e71 src/dllmain.cpp:33783
BhrcExpeditionHostPhaseSnapshot EvaluateBhrcExpeditionHostPhase() {
  BhrcExpeditionHostPhaseSnapshot out{};
  out.authority = SnapshotNativeExpeditionAuthority();
  const uint64_t current_master = GetCurrentNrscMasterLobbyId();
  const uint64_t current_owner = g_nrsc_steam_control_state.owner_steam_id;
  const uint64_t local = g_nrsc_steam_control_state.local_steam_id;
  if (!out.authority.valid || out.authority.commit_seq == 0) {
    out.phase = current_master != 0 && current_owner != 0 &&
            current_owner == local
        ? BhrcExpeditionHostPhase::WaitingHall
        : BhrcExpeditionHostPhase::NoExpedition;
    return out;
  }

  void* const team_session = ReadGameGlobalPtr(kNetModeManagerPtrRva);
  const uint32_t manager_id = team_session != nullptr
      ? ReadU32(static_cast<const uint8_t*>(team_session) + 0x08, 0)
      : 0;
  const BhrcNativeManagerRegistryLookup lookup =
      ReadBhrcNativeManagerRegistry(team_session, manager_id);
  const BhrcNativeJoinOwnershipSnapshot manager =
      ReadBhrcNativeJoinOwnershipSnapshot(lookup.manager);
  const BhrcCommittedExpeditionDescriptorSnapshot descriptor =
      ReadCommittedNativeExpeditionDescriptor();
  out.authority_live = team_session != nullptr && !lookup.read_fault &&
      manager_id == out.authority.manager_id &&
      lookup.manager == out.authority.native_manager &&
      manager.manager_id == out.authority.manager_id &&
      manager.native_state == 2 &&
      manager.owned_lobby == out.authority.lobby_id &&
      RvaOf(reinterpret_cast<const void*>(manager.manager_vtable)) ==
          kNativeSteamLobbyManagerVtableRva &&
      descriptor.valid && descriptor.lobby_id == out.authority.lobby_id &&
      current_master == out.authority.master_lobby_id &&
      current_owner == out.authority.owner_steam_id &&
      local == out.authority.local_steam_id && current_owner == local;
  if (!out.authority_live) {
    out.phase = BhrcExpeditionHostPhase::EndingUnavailable;
    return out;
  }

  out.world_chr_man = ReadGameGlobalPtr(kWorldChrManPtrRva);
  void* player_data_manager =
      ReadGameGlobalPtr(kPlayerGameDataManagerGlobalPtrRva);
  out.local_player_game_data = player_data_manager != nullptr
      ? reinterpret_cast<void*>(ReadU64(
            static_cast<const uint8_t*>(player_data_manager) + 8, 0))
      : nullptr;
  if (out.world_chr_man != nullptr && out.local_player_game_data != nullptr &&
      g_world_chr_lookup_by_game_data_id != nullptr) {
    const uint32_t entity_id = ReadU32(
        static_cast<const uint8_t*>(out.local_player_game_data) + 8,
        kInvalidEntityPart);
    if (entity_id != kInvalidEntityPart) {
      __try {
        out.local_world_chr = g_world_chr_lookup_by_game_data_id(
            out.world_chr_man, entity_id);
      } __except (LogSehException(
          "BHRC expedition phase WorldChr lookup", GetExceptionInformation())) {
        out.local_world_chr = nullptr;
      }
    }
  }
  out.current_map_family = ReadCurrentBhrcMapFamily();
  const ULONGLONG now = GetTickCount64();
  AcquireSRWLockExclusive(&g_bhrc_expedition_world_phase_lock);
  BhrcExpeditionWorldPhaseState& state = g_bhrc_expedition_world_phase;
  out.registration_seq = state.registration_seq;
  out.commit_registration_seq = state.commit_registration_seq;
  out.commit_map_family = state.commit_map_family;
  const bool ordinary_post_commit_registration =
      state.authority_commit_seq == out.authority.commit_seq &&
      state.registration_seq > state.commit_registration_seq &&
      state.last_registered_world_chr_man == out.world_chr_man;
  const bool promoted_precommit_local_base_registration =
      state.authority_commit_seq == out.authority.commit_seq &&
      state.local_base_registration_seq >
          state.commit_local_base_registration_seq &&
      state.last_local_base_world_chr_man == out.world_chr_man &&
      state.last_local_base_authority_seq == out.authority.commit_seq;
  out.post_commit_registration = ordinary_post_commit_registration ||
      promoted_precommit_local_base_registration;
  ULONGLONG matching_registration_tick_ms = 0;
  if (ordinary_post_commit_registration) {
    matching_registration_tick_ms = state.last_registration_tick_ms;
  } else if (promoted_precommit_local_base_registration) {
    matching_registration_tick_ms =
        state.last_local_base_registration_tick_ms;
  }
  out.world_stable = out.post_commit_registration &&
      matching_registration_tick_ms != 0 &&
      now >= matching_registration_tick_ms &&
      now - matching_registration_tick_ms >= kBhrcExpeditionMapStableMs;
  out.map_changed = out.current_map_family != 0xffffffffu &&
      state.commit_map_family != 0xffffffffu &&
      out.current_map_family != state.commit_map_family;
  if (out.current_map_family == 0xffffffffu || !out.map_changed) {
    state.stable_map_family = 0xffffffffu;
    state.stable_map_since_ms = 0;
  } else if (state.stable_map_family != out.current_map_family) {
    state.stable_map_family = out.current_map_family;
    state.stable_map_since_ms = now;
  }
  out.map_stable = state.stable_map_family == out.current_map_family &&
      state.stable_map_since_ms != 0 &&
      now - state.stable_map_since_ms >= kBhrcExpeditionMapStableMs;
  state.observed_world_chr_man = out.world_chr_man;
  state.local_player_game_data = out.local_player_game_data;
  state.local_world_chr = out.local_world_chr;
  ReleaseSRWLockExclusive(&g_bhrc_expedition_world_phase_lock);

  // FUN_1401fe1d0 legitimately remains 0xffffffff in a running expedition
  // on this build. Map family remains diagnostic; the authoritative running
  // boundary is a stable post-B WorldChr registration with live local world
  // objects under the same native B owner.
  out.phase = out.post_commit_registration && out.world_stable &&
          out.world_chr_man != nullptr &&
          out.local_player_game_data != nullptr && out.local_world_chr != nullptr
      ? BhrcExpeditionHostPhase::RunningExpedition
      : BhrcExpeditionHostPhase::StartingOrLoading;
  return out;
}


