// 7a66e71 src/dllmain.cpp:35462
bool ReadBhrcEmptyNativeDescriptorVector(
    const void* source,
    uint64_t* begin,
    uint64_t* end,
    uint64_t* capacity) {
  if (source == nullptr || begin == nullptr || end == nullptr ||
      capacity == nullptr ||
      !TryReadU64(static_cast<const uint8_t*>(source) + 0x40, begin) ||
      !TryReadU64(static_cast<const uint8_t*>(source) + 0x48, end) ||
      !TryReadU64(static_cast<const uint8_t*>(source) + 0x50, capacity)) {
    return false;
  }
  return *begin <= *end && *end <= *capacity && *begin == *end &&
      *capacity - *begin <= 0x10000;
}


// 7a66e71 src/dllmain.cpp:35478
bool ShouldRetainBhrcNativeDescriptor(
    uintptr_t caller_rva,
    const void* source,
    BhrcPersistentSessionDescriptorSnapshot* current_out,
    PersistedReconnectIdentity* identity_out,
    const char** reason_out,
    uint64_t* source_begin_out,
    uint64_t* source_end_out,
    uint64_t* source_capacity_out) {
  const bool targeted_clear =
      caller_rva == kQuickMatchDescriptorClearReturnRva ||
      caller_rva == kGlobalDescriptorClearReturnRva;
  if (!targeted_clear) {
    if (reason_out != nullptr) {
      *reason_out = "not_targeted_clear_owner";
    }
    return false;
  }

  uint64_t source_begin = 0;
  uint64_t source_end = 0;
  uint64_t source_capacity = 0;
  const bool source_empty = ReadBhrcEmptyNativeDescriptorVector(
      source, &source_begin, &source_end, &source_capacity);
  if (source_begin_out != nullptr) {
    *source_begin_out = source_begin;
  }
  if (source_end_out != nullptr) {
    *source_end_out = source_end;
  }
  if (source_capacity_out != nullptr) {
    *source_capacity_out = source_capacity;
  }
  if (!source_empty) {
    if (reason_out != nullptr) {
      *reason_out = "source_not_default_empty";
    }
    return false;
  }

  const BhrcPersistentSessionDescriptorSnapshot current =
      ReadBhrcPersistentSessionDescriptorSnapshot();
  if (current_out != nullptr) {
    *current_out = current;
  }
  const bool current_native_b_valid = !current.read_fault &&
      current.descriptor_bounds_valid && current.expedition_lobby_valid &&
      current.descriptor_size == sizeof(uint64_t) &&
      current.expedition_lobby_id != 0;
  if (!current_native_b_valid) {
    if (reason_out != nullptr) {
      *reason_out = "current_native_descriptor_invalid";
    }
    return false;
  }

  PersistedReconnectIdentity identity{};
  const bool tuple_loaded = LoadPersistedReconnectIdentity(&identity);
  if (identity_out != nullptr) {
    *identity_out = identity;
  }
  const bool tuple_complete = tuple_loaded && identity.record_key != 0 &&
      identity.host_steam_id != 0 && identity.lobby_id != 0 &&
      identity.master_lobby_id != 0 && identity.generation != 0 &&
      identity.record_role == kBhrcRecordRoleSelf &&
      identity.host_steam_id != identity.record_key &&
      identity.master_lobby_id != identity.lobby_id;
  if (!tuple_complete) {
    if (reason_out != nullptr) {
      *reason_out = "persisted_self_tuple_incomplete";
    }
    return false;
  }
  if (identity.lobby_id != current.expedition_lobby_id) {
    if (reason_out != nullptr) {
      *reason_out = "persisted_B_mismatch";
    }
    return false;
  }

  const uint64_t runtime_local = g_nrsc_steam_control_state.local_steam_id;
  const uint64_t runtime_owner = g_nrsc_steam_control_state.owner_steam_id != 0
      ? g_nrsc_steam_control_state.owner_steam_id
      : g_nrsc_steam_control_state.last_owner_steam_id;
  const uint64_t runtime_master =
      g_nrsc_steam_control_state.current_master_lobby_id != 0
      ? g_nrsc_steam_control_state.current_master_lobby_id
      : g_nrsc_steam_control_state.last_master_lobby_id;
  const uint64_t runtime_expedition =
      g_nrsc_steam_control_state.expedition_lobby_id;
  if ((runtime_local != 0 && runtime_local != identity.record_key) ||
      (runtime_owner != 0 && runtime_owner != identity.host_steam_id) ||
      (runtime_master != 0 && runtime_master != identity.master_lobby_id) ||
      (runtime_expedition != 0 &&
       runtime_expedition != identity.lobby_id)) {
    if (reason_out != nullptr) {
      *reason_out = "live_nrsc_identity_mismatch";
    }
    return false;
  }

  if (reason_out != nullptr) {
    *reason_out = "exact_native_B_and_persisted_self_tuple";
  }
  return true;
}


