uint32_t BhrcPreviousSessionBackendGateCallerBit(uintptr_t caller_rva) {
  switch (caller_rva) {
    case 0xdecA0c: // FUN_140dec9c0: first backend bit-8 result
      return 0x1;
    case 0xdecA5c: // FUN_140dec9c0: second backend bit-8 result
      return 0x2;
    case 0xdecAa8: // FUN_140dec9c0: third backend bit-8 result
      return 0x4;
    default:
      return 0;
  }
}


// 7a66e71 src/dllmain.cpp:35870
uint8_t __fastcall HookNativeBackendStatusBitTest(
    void* backend_status,
    uint32_t mask) {
  const uint8_t original_result =
      g_native_backend_status_bit_test != nullptr
      ? g_native_backend_status_bit_test(backend_status, mask)
      : 0;
  BhrcOldMemberBackendGateTls& gate =
      g_bhrc_old_member_backend_gate_tls;
  if (!gate.active) {
    return original_result;
  }

  const uintptr_t caller_rva = RvaOf(_ReturnAddress());
  const uint32_t caller_bit =
      BhrcPreviousSessionBackendGateCallerBit(caller_rva);
  if (mask != 0x08 || caller_bit == 0 ||
      (gate.caller_mask & caller_bit) != 0) {
    ++gate.rejected_call_count;
    return original_result;
  }
  ++gate.call_count;
  gate.caller_mask |= caller_bit;
  if (original_result != 0) {
    gate.original_ready_mask |= caller_bit;
    return original_result;
  }
  if (gate.startup_title_submission) {
    // Startup must enter the native mode-1 owner with all three wrappers
    // genuinely ready.  The P2P adapter supplies the missing service-success
    // event through FUN_140f18d30; it must not manufacture readiness bits.
    ++gate.rejected_call_count;
    return original_result;
  }
  if (!IsBhrcOldMemberBackendGateAuthorityCurrent(gate)) {
    ++gate.rejected_call_count;
    return original_result;
  }

  // This substitutes only the missing official-service readiness fact.  The
  // caller remains the original FUN_140dec9c0 and the original mode-1 factory
  // creates every native task/provider/result object after the predicate.
  gate.bridged_mask |= caller_bit;
  return 1;
}


