// 7a66e71 src/dllmain.cpp:36047
BhrcNativeBWrapperActivationSnapshot
ReadBhrcNativeBWrapperActivationSnapshot() {
  BhrcNativeBWrapperActivationSnapshot snapshot{};
  snapshot.session_manager = ReadGameGlobalPtr(kNetModeManagerPtrRva);
  if (snapshot.session_manager == nullptr) {
    return snapshot;
  }

  auto* const session_bytes =
      static_cast<uint8_t*>(snapshot.session_manager);
  snapshot.wrapper = session_bytes + 0x48;
  uint64_t backend_value = 0;
  if (!TryReadU32(session_bytes + 0x58, &snapshot.wrapper_state) ||
      !TryReadU8(session_bytes + 0x68, &snapshot.wrapper_enabled) ||
      !TryReadU64(session_bytes + 0x60, &backend_value) ||
      backend_value == 0) {
    return snapshot;
  }

  snapshot.backend = reinterpret_cast<void*>(backend_value);
  uint8_t provider_selector = 0xff;
  if (!TryReadU32(
          reinterpret_cast<const uint8_t*>(backend_value) + 0xc70,
          &snapshot.backend_mask) ||
      !TryReadU8(
          reinterpret_cast<const uint8_t*>(backend_value) + 0x25b,
          &provider_selector)) {
    return snapshot;
  }

  snapshot.provider = reinterpret_cast<void*>(
      static_cast<uintptr_t>(backend_value) +
      (provider_selector == 0 ? 0x920 : 0xa68));
  if (!TryReadU32(
          static_cast<const uint8_t*>(snapshot.provider) + 0x10,
          &snapshot.provider_active_count)) {
    return snapshot;
  }

  snapshot.readable = true;
  snapshot.ready =
      (snapshot.wrapper_state == 1 || snapshot.wrapper_state == 2) &&
      snapshot.wrapper_enabled != 0 &&
      (snapshot.backend_mask & 0x04) != 0 &&
      snapshot.provider_active_count != 0;
  return snapshot;
}


