void TraceBhrcPgdReceiveGate(uint64_t actual_steam_id,
    const RevenantFixFullPgdChunkPacket& packet, bool peer_active,
    LONG bridge_state, const char* outcome) {
  __try {
    if (!IsLocalNrscHost()) return;
    struct GateSample {
      uint64_t peer = 0;
      ULONGLONG tick = 0;
      uint32_t nonce = 0, generation = 0;
      uint16_t purpose = 0;
      bool active = false;
      const char* outcome = nullptr;
    };
    static thread_local GateSample samples[kObservedPartyMemberSlots]{};
    GateSample* sample = nullptr;
    for (auto& candidate : samples) {
      if (candidate.outcome != nullptr && candidate.peer == actual_steam_id) { sample = &candidate; break; }
      if (sample == nullptr && candidate.outcome == nullptr) sample = &candidate;
    }
    if (sample == nullptr) sample = &samples[0];
    const ULONGLONG now = GetTickCount64();
    if (sample->outcome != nullptr && sample->peer == actual_steam_id &&
        sample->active == peer_active && std::strcmp(sample->outcome, outcome) == 0 &&
        sample->nonce == packet.request_nonce && sample->generation == packet.client_generation &&
        sample->purpose == packet.purpose && now >= sample->tick && now - sample->tick < 10000)
      return;
    *sample = {actual_steam_id, now, packet.request_nonce, packet.client_generation,
               packet.purpose, peer_active, outcome};
    static volatile LONG count = 0;
    LONG seq = 0;
    if (!BhrcDiagnosticBudget(&count, 128, "pgd_receive_gate", &seq)) return;
    Log("BHRC_PGD_RX_TRACE receive_gate seq=%ld outcome=%s gatePeerActive=%d bridgeState=%ld actualSender=%016llx headerSender=%016llx target=%016llx owner=%016llx packetA=%016llx packetB=%016llx packetAuthoritySeq=%llu nonce=%08x generation=%u revision=%llu hash=%08x totalSize=%u purpose=%u chunkIndex=%u chunkCount=%u chunkSize=%u transportGateAccepted=%d headerClaimsUntrusted=1 behaviorMutation=0",
        seq, outcome, peer_active ? 1 : 0, bridge_state,
        static_cast<unsigned long long>(actual_steam_id), static_cast<unsigned long long>(packet.header.sender_steam_id),
        static_cast<unsigned long long>(packet.header.target_steam_id), static_cast<unsigned long long>(packet.owner_steam_id),
        static_cast<unsigned long long>(packet.master_lobby_id), static_cast<unsigned long long>(packet.expedition_lobby_id),
        static_cast<unsigned long long>(packet.authority_commit_seq), packet.request_nonce, packet.client_generation,
        static_cast<unsigned long long>(packet.snapshot_revision), packet.total_hash32, packet.total_size,
        packet.purpose, packet.chunk_index, packet.chunk_count, packet.chunk_size,
        std::strcmp(outcome, "accepted") == 0 ? 1 : 0);
    LogBhrcPgdTransportEvidence("receive_gate", seq, actual_steam_id);
  } __except (EXCEPTION_EXECUTE_HANDLER) {
    LogWarn("BHRC_PGD_RX_TRACE receive_snapshot_fault peer=%016llx outcome=%s behaviorUnchanged=1",
        static_cast<unsigned long long>(actual_steam_id), outcome);
  }
}

