// 7a66e71 src/dllmain.cpp:39071
bool IsBhrcKnownReturningRemoteSteamId(uint64_t steam_id) {
  if (steam_id == 0) {
    return false;
  }
  const BhrcSteamRecordCacheEntry* entry =
      FindCachedReconnectRecordBySteamId(steam_id);
  if (entry == nullptr || !entry->valid) {
    return false;
  }
  // Returning friend: any non-self record the host has persisted/seen.
  if (entry->identity.record_role == kBhrcRecordRoleSelf) {
    return false;
  }
  return entry->identity.record_role == kBhrcRecordRoleRemote ||
         entry->identity.record_role == kBhrcRecordRoleUnknown ||
         entry->steam_id == steam_id;
}


// 7a66e71 src/dllmain.cpp:39089
uint8_t __fastcall HookNativeMatchingMemberAcceptCheck(
    void* matching_facade,
    void* peer_key_ptr,
    uint32_t arg2,
    uint32_t arg3) {
  if (g_native_matching_member_accept_check == nullptr) {
    LogError("BHRC FUN_140b4f560 original missing");
    return 0;
  }
  uint8_t original = 0;
  __try {
    original = g_native_matching_member_accept_check(
        matching_facade, peer_key_ptr, arg2, arg3);
  } __except (LogSehException("BHRC FUN_140b4f560 original", GetExceptionInformation())) {
    LogError("BHRC FUN_140b4f560 original_exception");
    return 0;
  }

  uint64_t peer_key = 0;
  if (peer_key_ptr != nullptr) {
    TryReadU64(peer_key_ptr, &peer_key);
  }
  uint64_t peer_steam = peer_key;
  if (peer_key > 0x10000ull && (peer_key >> 56) != 0x11) {
    uint64_t nested = 0;
    if (TryReadU64(reinterpret_cast<const void*>(peer_key), &nested) &&
        nested != 0) {
      peer_steam = nested;
    }
  }

  const bool host = IsLocalNrscHost();
  bool returning = host && IsBhrcKnownReturningRemoteSteamId(peer_steam);
  if (!returning && host && peer_steam != 0) {
    const BhrcSteamRecordCacheEntry* by_steam =
        FindCachedReconnectRecordBySteamId(peer_steam);
    if (by_steam != nullptr && by_steam->valid &&
        by_steam->identity.record_role != kBhrcRecordRoleSelf) {
      returning = true;
      peer_steam = by_steam->steam_id;
    }
  }
  if (!returning && host && peer_key != 0 && peer_key != peer_steam) {
    if (IsBhrcKnownReturningRemoteSteamId(peer_key)) {
      returning = true;
      peer_steam = peer_key;
    }
  }

  uint8_t result = original;
  const bool forced = host && returning && original == 0;
  if (forced) {
    result = 1;
    LogWarn(
        "BHRC native_matching_accept_check edge=returning_member_admitted matching=%p peerKeyPtr=%p peerKey=%016llx peerSteam=%016llx arg2=%08x arg3=%08x original=0 result=1",
        matching_facade, peer_key_ptr,
        static_cast<unsigned long long>(peer_key),
        static_cast<unsigned long long>(peer_steam), arg2, arg3);
  }
  return result;
}


// 7a66e71 src/dllmain.cpp:39234
bool ShouldHoldAuthorizedNativeJoinLobbyLeave(
    void* manager,
    const BhrcNativeJoinOwnershipSnapshot& ownership,
    const BhrcOldMemberHandoffState& handoff) {
  if (!g_config.hold_authorized_expedition_b_leave || manager == nullptr) {
    return false;
  }
  if (handoff.stage != BhrcOldMemberHandoffStage::WaitingOwnerIdle &&
      handoff.stage != BhrcOldMemberHandoffStage::FailClosedPending &&
      handoff.stage != BhrcOldMemberHandoffStage::NativeOwnerSubmitted) {
    return false;
  }
  if (handoff.expedition_lobby_id == 0) {
    return false;
  }
  // Never hold master A.
  if (handoff.master_lobby_id != 0 &&
      (ownership.owned_lobby == handoff.master_lobby_id ||
       ownership.payload_lobby == handoff.master_lobby_id)) {
    return false;
  }
  if (ownership.owned_lobby == handoff.expedition_lobby_id ||
      ownership.payload_lobby == handoff.expedition_lobby_id) {
    return true;
  }
  // Fail-clean may clear payload first; match manager id as secondary signal.
  return handoff.manager_id != 0 && ownership.manager_id == handoff.manager_id;
}


