void __fastcall HookTeamSessionDialog(void* state, uint8_t reason) {
  const uint32_t text_id = TeamSessionDialogTextIdForReason(reason);
  const bool expedition_departed = reason == 4;
  const bool restore_ended = reason == 6;

  uint64_t lobby_id = 0;
  if (expedition_departed &&
      IsCurrentReason4CleanupIntentArmed() &&
      ShouldSuppressMatchedPlayersUi(&lobby_id)) {
    const BhrcDeferredReconnectIntent intent = SnapshotBhrcDeferredReconnectIntent();
    RememberSuppressedTeamSessionDialog(state, reason, "team_session_reason4_deferred");
    Log(
        "TeamSessionDialog/FUN_140e00a20 suppressed_matched_players_ui reason=%u reasonName=%s textId=%08x state=%p expeditionLobbyB=%016llx intentSerial=%llu intentStage=%s action=deferred_until_cleanup_exit",
        reason,
        TeamSessionDialogReasonName(reason),
        text_id,
        state,
        static_cast<unsigned long long>(lobby_id),
        static_cast<unsigned long long>(intent.serial),
        BhrcDeferredReconnectStageName(intent.stage));
    return;
  }

  if (restore_ended &&
      g_bhrc.suppressed_team_dialog_valid &&
      (g_bhrc.phase == BhrcPhase::Failed || g_bhrc.suppressed_failure_prompt_shown)) {
    if (!g_bhrc.suppressed_failure_prompt_shown) {
      g_bhrc.suppressed_failure_prompt_shown = true;
      ShowFixedTeamSessionFailurePrompt(
          g_bhrc.suppressed_team_dialog_reason != 0 ? g_bhrc.suppressed_team_dialog_reason : 4,
          BhrcRejectReasonName(g_bhrc.last_error),
          "team_session_reason6_suppressed");
    }
    Log(
        "TeamSessionDialog/FUN_140e00a20 suppressed_restore_ended_after_reconnect_failure reason=%u reasonName=%s textId=%08x state=%p phase=%s lastError=%s promptShown=%d originalCall=0",
        reason,
        TeamSessionDialogReasonName(reason),
        text_id,
        state,
        BhrcPhaseName(g_bhrc.phase),
        BhrcRejectReasonName(g_bhrc.last_error),
        g_bhrc.suppressed_failure_prompt_shown ? 1 : 0);
    return;
  }

  if (text_id != 0) {
    const bool shown = ShowFixedTeamSessionFailurePrompt(
        reason,
        "team_session_original_replaced",
        "avoid_unsafe_FUN_140e00a20_trampoline");
    Log(
        "TeamSessionDialog/FUN_140e00a20 replaced_with_fixed_text reason=%u reasonName=%s textId=%08x state=%p shown=%d originalCall=0 savedLobbyId=%016llx nrscModule=%p steamMatchmaking=%p localHost=%d enableBridge=%d enableUiJoin=%d",
        reason,
        TeamSessionDialogReasonName(reason),
        text_id,
        state,
        shown ? 1 : 0,
        static_cast<unsigned long long>(GetSavedNrscSteamLobbyId()),
        g_nrsc_module,
        g_nrsc_steam_control_state.steam_matchmaking,
        IsLocalNrscHost() ? 1 : 0,
        g_config.enable_nrsc_steam_control ? 1 : 0,
        g_config.enable_nrsc_matched_players_ui_suppress ? 1 : 0);
    return;
  }

  Log(
      "TeamSessionDialog/FUN_140e00a20 blocked_unknown_text reason=%u reasonName=%s textId=%08x state=%p suppressCandidate=%d skipReason=%s savedLobbyId=%016llx nrscModule=%p steamMatchmaking=%p localHost=%d enableBridge=%d enableUiJoin=%d originalCall=0",
      reason,
      TeamSessionDialogReasonName(reason),
      text_id,
      state,
      expedition_departed ? 1 : 0,
      expedition_departed ? DescribeJoinRejectedUiSuppressSkipReason() : "not_expedition_departed",
      static_cast<unsigned long long>(GetSavedNrscSteamLobbyId()),
      g_nrsc_module,
      g_nrsc_steam_control_state.steam_matchmaking,
      IsLocalNrscHost() ? 1 : 0,
      g_config.enable_nrsc_steam_control ? 1 : 0,
      g_config.enable_nrsc_matched_players_ui_suppress ? 1 : 0);

  LogWarn(
      "TeamSessionDialog/FUN_140e00a20 original_call_blocked reason=unknown_text state=%p originalCall=0",
      state);
}


// 7a66e71 src/dllmain.cpp:39942
bool IsBhrcReturningMemberTransportLoss(uint32_t state_flags) {
  // Steam EChatMemberStateChange: 2=Left, 4=Disconnected. Kicked and Banned
  // are authoritative removals and must always reach the original owners.
  return state_flags == 2 || state_flags == 4;
}


// 7a66e71 src/dllmain.cpp:39948
BhrcReturningMemberLeaseDecision EvaluateBhrcReturningMemberLease(
    void* native_manager_hint,
    uint64_t lobby_id,
    uint64_t steam_id,
    uint32_t state_flags) {
  BhrcReturningMemberLeaseDecision out{};
  out.lobby_id = lobby_id;
  out.steam_id = steam_id;
  out.state_flags = state_flags;

  if (!IsBhrcReturningMemberTransportLoss(state_flags)) {
    out.reason = "not_transient_transport_loss";
    return out;
  }
  if (InterlockedCompareExchange(
          &g_bhrc_returning_member_lease_hook_ready, 0, 0) != 1) {
    out.reason = "native_ingress_hook_not_ready";
    return out;
  }
  if (InterlockedCompareExchange(&g_nrsc_bridge_install_state, 0, 0) != 2) {
    out.reason = "nrsc_transport_hooks_not_ready";
    return out;
  }
  if (!IsLocalNrscHost()) {
    out.reason = "local_not_host";
    return out;
  }

  out.authority = SnapshotNativeExpeditionAuthority();
  if (!out.authority.valid || out.authority.commit_seq == 0 ||
      out.authority.native_manager == nullptr ||
      out.authority.manager_id == 0 || out.authority.lobby_id == 0 ||
      out.authority.master_lobby_id == 0) {
    out.reason = "no_committed_live_B_authority";
    return out;
  }
  if (out.authority.owner_steam_id == 0 ||
      out.authority.local_steam_id != out.authority.owner_steam_id) {
    out.reason = "B_authority_not_host_owned";
    return out;
  }
  if (lobby_id != out.authority.master_lobby_id &&
      lobby_id != out.authority.lobby_id) {
    out.reason = "event_lobby_outside_A_B_generation";
    return out;
  }
  if (steam_id == 0 || steam_id == out.authority.local_steam_id ||
      steam_id == out.authority.owner_steam_id) {
    out.reason = "subject_not_remote_member";
    return out;
  }
  if (native_manager_hint != nullptr &&
      native_manager_hint != out.authority.native_manager) {
    out.reason = "callback_manager_not_committed_B";
    return out;
  }

  void* current_session_mgr = ReadGameGlobalPtr(kNetModeManagerPtrRva);
  out.current_manager_id = current_session_mgr != nullptr
      ? ReadU32(static_cast<const uint8_t*>(current_session_mgr) + 0x08, 0)
      : 0;
  if (current_session_mgr == nullptr ||
      out.current_manager_id != out.authority.manager_id) {
    out.reason = "live_session_generation_mismatch";
    return out;
  }
  const auto* native_manager =
      static_cast<const uint8_t*>(out.authority.native_manager);
  if (RvaOf(reinterpret_cast<const void*>(ReadU64(native_manager, 0))) !=
          kNativeSteamLobbyManagerVtableRva ||
      ReadU32(native_manager + 0x69c, UINT32_MAX) != 2 ||
      ReadU64(native_manager + 0x870, 0) != out.authority.lobby_id) {
    out.reason = "native_B_manager_not_live";
    return out;
  }

  if (!SnapshotCachedReconnectRecordBySteamId(steam_id, &out.cached)) {
    out.reason = "identity_mapping_missing";
    return out;
  }
  out.record_key = out.cached.record_key;
  const uint32_t required_identity =
      kBhrcIdentityValidSteamId | kBhrcIdentityValidRecordKey;
  if (out.record_key == 0 || out.cached.steam_id != steam_id ||
      out.cached.identity.schema_version !=
          kBhrcPlayerIdentitySnapshotSchemaVersion ||
      (out.cached.identity.valid_mask & required_identity) !=
          required_identity ||
      (out.cached.identity.evidence_mask &
       kBhrcIdentityEvidenceNativeBAuthority) == 0 ||
      out.cached.identity.record_role != kBhrcRecordRoleRemote ||
      out.cached.identity.steam_id != steam_id ||
      out.cached.identity.record_key != out.record_key) {
    out.reason = "identity_mapping_not_authoritative_remote";
    return out;
  }
  const uint64_t cached_expedition =
      out.cached.identity.expedition_lobby_id != 0
          ? out.cached.identity.expedition_lobby_id
          : out.cached.lobby_id;
  if (cached_expedition != out.authority.lobby_id ||
      out.cached.identity.expedition_generation !=
          static_cast<uint32_t>(out.authority.commit_seq) ||
      (out.cached.identity.master_lobby_id != 0 &&
       out.cached.identity.master_lobby_id !=
           out.authority.master_lobby_id) ||
      (out.cached.identity.owner_steam_id != 0 &&
       out.cached.identity.owner_steam_id != out.authority.owner_steam_id)) {
    out.reason = "identity_mapping_wrong_B_generation";
    return out;
  }

  out.team_state = ReadGameGlobalPtr(kNativeBTeamSessionStatePtrRva);
  if (out.team_state == nullptr) {
    out.reason = "TeamSession_owner_missing";
    return out;
  }
  const auto* team_bytes = static_cast<const uint8_t*>(out.team_state);
  if (ReadU32(team_bytes + 0x00, 0) == 0 ||
      ReadU64(team_bytes + 0x68, 0) != out.authority.owner_steam_id) {
    out.reason = "TeamSession_owner_generation_mismatch";
    return out;
  }
  out.member =
      FindBhrcNativeTeamSessionRecord(out.team_state, out.record_key);
  if (out.member.read_fault || !out.member.found ||
      out.member.key != out.record_key) {
    out.reason = "TeamSession_member_not_live";
    return out;
  }
  if (out.member.flag_e5 != 0) {
    out.reason = "TeamSession_member_not_accepted";
    return out;
  }

  out.retain = true;
  out.reason = "accepted_returning_member_reclassification_eligible";
  return out;
}


