bool InstallBhrcNativeDescriptorRetentionHook() {
  constexpr size_t kRetentionHookSlot = 119;
  if (!g_config.enable_nrsc_steam_control) {
    Log(
        "BHRC native_descriptor_retention_install outcome=skipped reason=nrsc_steam_control_disabled");
    return false;
  }
  if (g_game_base == 0 || kRetentionHookSlot >= _countof(g_hooks) ||
      g_hooks[kRetentionHookSlot].target != nullptr) {
    LogError(
        "BHRC native_descriptor_retention_install outcome=failed reason=slot_or_game_base slot=%llu gameBase=%p existingTarget=%p",
        static_cast<unsigned long long>(kRetentionHookSlot),
        reinterpret_cast<void*>(g_game_base),
        kRetentionHookSlot < _countof(g_hooks)
            ? g_hooks[kRetentionHookSlot].target
            : nullptr);
    return false;
  }

  uint8_t actual[sizeof(kNativePersistentDescriptorCommitPrologue)]{};
  char expected_text[128]{};
  char actual_text[128]{};
  const bool read_ok = ReadBhrcHookEntryBytes(
      g_game_base + kNativePersistentDescriptorCommitRva, actual,
      sizeof(actual));
  const bool match = read_ok && std::memcmp(
      actual, kNativePersistentDescriptorCommitPrologue,
      sizeof(actual)) == 0;
  FormatBhrcHookBytes(
      kNativePersistentDescriptorCommitPrologue,
      sizeof(kNativePersistentDescriptorCommitPrologue), expected_text,
      sizeof(expected_text));
  FormatBhrcHookBytes(
      actual, sizeof(actual), actual_text, sizeof(actual_text));
  Log(
      "BHRC native_descriptor_retention_preflight slot=%llu commitRva=%llx deepCopyRva=%llx readOk=%d match=%d expected=\"%s\" actual=\"%s\" quickMatchClearReturn=%llx globalCleanupClearReturn=%llx",
      static_cast<unsigned long long>(kRetentionHookSlot),
      static_cast<unsigned long long>(kNativePersistentDescriptorCommitRva),
      static_cast<unsigned long long>(kNativeDescriptorDeepCopyRva),
      read_ok ? 1 : 0, match ? 1 : 0, expected_text, actual_text,
      static_cast<unsigned long long>(kQuickMatchDescriptorClearReturnRva),
      static_cast<unsigned long long>(kGlobalDescriptorClearReturnRva));
  if (!match) {
    LogWarn(
        "BHRC native_descriptor_retention_install outcome=skipped reason=commit_prologue_mismatch originalBehaviorUnchanged=1");
    return false;
  }

  g_native_descriptor_deep_copy =
      ResolveNative<NativeDescriptorDeepCopyFn>(kNativeDescriptorDeepCopyRva);
  if (g_native_descriptor_deep_copy == nullptr ||
      !InstallInlineHook(
          g_hooks[kRetentionHookSlot],
          g_game_base + kNativePersistentDescriptorCommitRva,
          reinterpret_cast<void*>(HookNativePersistentDescriptorCommit),
          sizeof(kNativePersistentDescriptorCommitPrologue), nullptr,
          "FUN_1402022d0/native previous-session descriptor clear retention")) {
    RemoveInlineHook(g_hooks[kRetentionHookSlot]);
    g_native_descriptor_deep_copy = nullptr;
    InterlockedExchange(&g_bhrc_native_descriptor_retention_hook_ready, 0);
    LogError(
        "BHRC native_descriptor_retention_install outcome=failed reason=hook_install originalBehaviorUnchanged=1");
    return false;
  }

  InterlockedExchange(&g_bhrc_native_descriptor_retention_hook_ready, 1);
  Log(
      "BHRC native_descriptor_retention_install outcome=ready slot=%llu nativeDeepCopy=%p policy=retain_native_generated_B_only_on_exact_persisted_self_tuple targetedOwners=FUN_140b5da90,FUN_140c322e0 passthrough=FUN_140b5da90_refresh_plus_all_other_callers directSaveSubmission=0 durableBridge=exact_FUN_140201c10_shape hostRevalidationRequired=1",
      static_cast<unsigned long long>(kRetentionHookSlot),
      reinterpret_cast<void*>(g_native_descriptor_deep_copy));
  return true;
}


